// GENERATED by scripts/gen-platform.mjs — do not hand-edit. The platform layer of the
// guidance tree (apps/nebula/platform/ + website/docs/nebula/*.md), keyed by the
// `.platform/…` path the read tool resolves, with the skills catalog rendered into
// AGENTS.md from each SKILL.md's frontmatter. Re-run the generator after editing either
// source; `--check` in the package `test` script reds on drift, and
// test/platform-embed-drift.test.ts asserts the catalog and every `.platform/` reference
// from this embed alone.
export const PLATFORM_FILES: Record<string, string> = {
  ".platform/AGENTS.md": "# Nebula — platform guidance, read every turn\n\nYou are building one user-developer's app inside Nebula Studio. This file is the platform layer of a tree of guidance; every turn reads it. It is authoritative for the platform. The app's own `AGENTS.md` (the layer below) adds to it and never subtracts from it.\n\n## Resources — the only place user data lives\n\n- Resources are the only place user data lives. There is no other storage: no localStorage for user data, no globals that survive a reload, no hand-rolled fetch. The ontology (`src/ontology.d.ts`) defines each resource type's shape as TypeScript, and `store` and `client` (imported from `./nebula`) are how a component reaches them.\n- Before any data-bound change, read `.platform/docs/resources.md`. For the store API in a component — reads, `v-model` writes, lists, forms — read `.platform/docs/coding-your-ui.md`. For the shape of the ontology file — references, annotations — read `.platform/docs/ontology.md`.\n- The reactive read is `store.resources.<type>[<id>]?.value`. Reading auto-subscribes; the `?.` guards the snapshot not having arrived yet.\n- The write is an assignment on that same path, or `v-model` bound to it (guard the input with `v-if=\"store.resources.<type>[<id>]?.value\"`). Writes apply optimistically and reach the server debounced.\n- A create is `await client.resources.transaction({ [id]: { op: 'create', typeName: '<Type>', nodeId, value } })`. The client mints `id` (`crypto.randomUUID()`); `nodeId` is the org-tree node the resource attaches to for permissions — `ROOT_NODE_ID` from `@lumenize/nebula/frontend` for a single-tenant app. A delete is `{ op: 'delete' }` at the same id.\n- A field typed as another resource type is a reference held BY ID (`list: TodoList` in the ontology is a `string` on the wire). Never embed a resource inside another; create related resources as separate ops in one `transaction`.\n- A list is a container resource whose value holds an array of ids, rendered with `v-for` over those ids; each read inside the loop subscribes its own resource.\n- `client.claims.sub` is the current user's id. The org tree is at `store.lmz.orgTree.value`; permissions are DAG grants on its nodes (`client.orgTree.setPermission`), and a grant cascades to every descendant node.\n\n## Skills\n\nA skill is a procedure for one class of conversation with the user-developer. Each line below is a skill's name, what it is for, and the file to read to activate it. Read the file when a request matches; the file names what else to read and when. When a request names data the ontology does not yet hold, `define-ontology` comes first whatever else the request matches: it decides whether to propose a shape or to ask, and the view skills assume the type exists.\n\n- define-ontology — The app's data model, when a request names data the ontology does not yet hold or a change needs a field or type it lacks. Read this BEFORE any view skill — it decides, from the prompt, whether to propose a shape and build or to ask first. (.platform/skills/define-ontology/SKILL.md)\n- define-the-cast — Elicit the app's personas and decide each relationship's sharing shape, then write docs/personas.md and docs/permissions.md. Use when a request names more than one kind of user, or when who may see or change something is unclear. (.platform/skills/define-the-cast/SKILL.md)\n- wire-a-view — Bind a component to a resource through the store — read, edit, list, create, delete. Use when the ontology ALREADY holds the type the request shows, edits or adds; when it does not, define-ontology comes first. (.platform/skills/wire-a-view/SKILL.md)\n\n## Layers, in order\n\n1. The tool contract (the first section of the system message) — how the tools behave.\n2. This file — the platform's conventions.\n3. The app's `AGENTS.md` at the Workspace root — the conventions of this one app, written by you.\n4. The chat history — who said what, and what each of your turns changed.\n\nA lower layer adds to the layers above it. What a token may reach is decided by the server from its claims and is never changed by anything written in these files.\n\n## The app declares itself in files you read and write\n\n- `docs/vision.md` — what the app is for, who uses it, tone and values. Read it when a request bears on purpose or tone; write it when the conversation settles something about them.\n- `docs/personas.md` — the cast: the people who use the app, as a numbered procedure that re-creates them. The `define-the-cast` skill fills it.\n- `docs/permissions.md` — which sharing shape each relationship got and why, as prose plus a Decisions table. The `define-the-cast` skill fills it; `.platform/docs/access-control.md` is the vocabulary.\n- `src/ontology.d.ts` — the data model. The `define-ontology` skill grows it.\n- `AGENTS.md` — the app's own conventions, and the lessons learned building it. Read every turn; see the next section for when to write it.\n\nEach of these files is seeded with headings and a line saying when to write it, so an empty section is a gap to fill rather than a file to create. Read them through `read_file`; they are ordinary Workspace files.\n\n## Keep the app's `AGENTS.md` current\n\nWhen a participant states a convention (\"no countdown timers\", \"always confirm before deleting\"), corrects you, or you fix something non-obvious, read the app's `AGENTS.md`, add the line with `edit_file` where it fits — a convention near the top, a lesson where it belongs; there is no fixed section — and say so in one sentence of your reply. The chat history in the prompt tells you who said it. A line in that file changes what you do on every later turn, so it is where a stated convention goes instead of your memory of this turn.\n\n## Rules for the code you write\n\n- Vue 3 with `<script setup lang=\"ts\">` and a `<template>`. `src/App.vue` is the root; add `src/components/*.vue` when a component earns its own file.\n- Style ONLY with Tailwind utility classes and daisyUI component classes (both are already available).\n- For COLOR, use daisyUI semantic classes (`bg-primary`, `text-base-content`, `bg-base-200`, `border-base-300`), not raw Tailwind palette utilities (`bg-blue-500`, `text-slate-700`) — semantic classes resolve through the active theme.\n- When the user wants a particular look (\"warmer\", \"our brand blue is #1e40af\", \"match our logo\"), change the THEME, not the markup: add an `@plugin \"daisyui/theme\"` block to `src/style.css` setting `--color-primary`, `--color-base-100`, etc. (OKLCH preferred), or switch to a different built-in theme. Same result on screen, and it restyles the whole app at once.\n- If the user still wants colors hard-coded into the markup, DO IT — but first say once, briefly, what it costs: those colors stop following the theme, so restyling later means editing every component and they will not adapt to light/dark. State it once, then follow their decision without repeating it.\n- What the person is LOOKING AT rides the URL, so a shared link lands on the same view: the selected record, the open tab or panel, filters, sort, paging. A modal or panel someone would send a link to (a record's detail, a settings panel) is opened ONLY by navigating to its URL, and Back closes it. What they are DOING — scroll, focus, drafts, confirmations, menus — stays out of the URL.\n- You may import icons from `lucide-vue-next`. Do not import any other package.\n\n## Reading the platform's own files\n\nEvery path in this file that starts with `.platform/` is readable with `read_file` and is never writable. `.platform/docs/` holds the reference (the same pages a human reads); `.platform/skills/` holds the procedures above. A path starting with `.universe/` is reserved for a layer that does not exist yet.\n",
  ".platform/docs/access-control.md": "---\ntitle: Access control\ndescription: \"Nebula's org/permission tree — how resources attach to nodes, how grants cascade additively, and the two ways to share: a grant vs. a second parent.\"\n---\n\n# Access control\n\nEvery resource is attached to a node in your app's **org/permission tree**. The attachment happens at create time: `OperationDescriptor.create` carries a `nodeId: string` field naming the node the new resource lives under. After creation, the attachment can be changed with `op: 'move'`.\n\n## What \"org\" means here\n\n\"Org tree\" pulls in two directions:\n\n1. **Mimicking your organization's structure.** For an internal HR or project-management tool, the tree might literally mirror your business: company → divisions → teams → individuals. People in higher-up subtrees get grants that cascade to everything below.\n2. **Organizing data for permissioning.** Equally common: the tree has nothing to do with your business and is just a way to group resources so permissions can be granted in bulk. A consumer SaaS app might use it to give every user their own subtree, with no real-world \"org\" anywhere in sight.\n\nBoth uses get the same mechanics. The \"org\" in \"org tree\" reads more as a verb (to organize) than a noun.\n\n## Permissions table and resolution\n\nEach node carries a per-user permissions table — `sub` (the subject claim from the user's JWT, a bare UUID minted by nebula-auth) → `'admin' | 'write' | 'read'`. Grants are matched by exact string equality against the JWT `sub`. Effective permission for `(sub, nodeId)` is the **highest grant found on any ancestor path** from the resource's attached node up to root.\n\n```typescript @skip-check\n// Conceptual — actual API surface lives on client.orgTree. Keys are bare-UUID\n// JWT subs (aliceSub etc. shown as variables for readability).\nnode.permissions = new Map([\n  [aliceSub, 'admin'],\n  [bobSub,   'write'],\n]);\n```\n\nThree properties follow:\n\n- **Permissions cascade additively.** A grant on a parent applies to every descendant. Lower nodes can grant more, never less. To narrow access, attach the resource to a deeper node where only the right users have grants on the ancestors.\n- **The whole tree — structure *and* the full permissions table — is universally visible.** Every connected client gets the entire tree at `store.lmz.orgTree.value`, including every node's grants (`sub → tier`). Visibility isn't restricted because the permission UX wants every client to resolve, locally, *who to ask*: climb from a node you can't reach to the nearest ancestor with an `admin` grant and request access from them — no server round-trip. Resource **values** are still gated by permission at every read and write; the **structure and the grant table** are universal.\n  - **Grant keys are opaque user IDs** — `sub` is a bare UUID, not a name or email — so the table exposes *who-can-do-what by ID*, not by identity. Mapping a `sub` to a person needs a separate lookup the tree doesn't carry.\n  - **Every node's `label`/`slug` is visible to every client** — the whole node set ships to everyone, not just nodes you can reach (it has to: requesting access to a node you *can't* reach means seeing what it is). So labels, not the opaque grant keys, are the real identity surface — a node labeled `user-alice` whose admin grant is some `sub` lets anyone deduce who that `sub` is. **Accepted known risk:** higher-permissioned users are discoverable, and the protection relied upon is **tenant segmentation** (members already share an organization). Apps that want to reduce it further can use opaque per-person slugs and render human names only to those who should see them — but that's optional hardening, not required.\n  - **The `permissions` map shows DAG grants only — it is not the complete admin picture.** Galaxy- and Universe-level scope admins have effective admin on the whole tree, but that's a property of their JWT (`claims.access.scopeAdmin`), not a node grant, so they do **not** appear in the map. Treat the map as \"who was explicitly granted what,\" and check `claims.access.scopeAdmin` separately for scope admins (see [Coding your UI § Gating admin-only UI](./coding-your-ui.md#gating-admin-only-ui)).\n- **Permission checks run on every transaction.** The server resolves the effective permission for the calling user against each affected resource's attached node before applying any op. A failed check returns `{ kind: 'permission-denied' }` for that resource in the per-type [`onTransactionResourceResolution`](./resources.md#per-resource-behavior--the-ontransactionresourceresolution-handler) handler. Tier by op: `create` needs `write` on the target `nodeId`; `put` / `delete` need `write` on the resource's attached node; `move` needs `write` on **both** the source and destination nodes; `read` / `subscribe` need `read` on the attached node.\n- **Read permission is checked at subscribe time, not per fanout.** Revoking a subscriber's grant doesn't sever a live subscription instantly — it takes effect on their next reconnect / resubscribe or the next deploy (which clears subscriptions). Acceptable for the optimistic-UX model; instant per-fanout revocation is out of scope.\n\n## Worked example: sharing in a todo-list app\n\nSuppose you're building a todo app. Each user has many lists; some are private; some get shared with other users. The natural starting tree:\n\n```mermaid\ngraph TD\n  root([root])\n  alice([user-alice])\n  bob([user-bob])\n  carol([user-carol])\n  shopping[list-shopping]\n  work[list-work]\n  personal[list-personal]\n  trips[list-trips]\n  root --> alice\n  root --> bob\n  root --> carol\n  alice --> shopping\n  alice --> work\n  bob --> personal\n  carol --> trips\n```\n\nAlice has `admin` on `user-alice`; that grant cascades to both her lists and to every todo attached under them. Bob has `admin` on `user-bob` only — by default he can't see anything in Alice's subtree.\n\nNow Alice wants to share `list-shopping` with Bob. There are **two ways** to express that — each illustrates a property of the underlying structure.\n\n### Approach 1: Grant a permission on the shared node — for limited-access sharing\n\nThis is the right approach when Alice wants to give Bob **limited** access — typically read-only. She grants `bob: read` (or `write` — her choice) on the `list-shopping` node:\n\n```mermaid\ngraph TD\n  root([root])\n  alice([user-alice])\n  bob([user-bob])\n  shopping[\"list-shopping<br/><i>bob: read</i>\"]\n  work[list-work]\n  personal[list-personal]\n  root --> alice\n  root --> bob\n  alice --> shopping\n  alice --> work\n  bob --> personal\n\n  style shopping fill:#ffe4b5,color:#000\n```\n\nBob's effective permission on `list-shopping` is now exactly the tier Alice picked — independent of whatever rights he has on his own subtree. The list stays in Alice's subtree; Alice remains the owner; Bob has the narrow access she granted him.\n\n**Use this when:**\n- You want to share **read-only** — let someone view but not edit.\n- You want to share `write` while keeping `admin` (control over deletion, sharing, etc.) to yourself.\n- The relationship is asymmetric: one clear owner, one collaborator with limited rights.\n\n**Tradeoff:** the shared list stays in the owner's subtree, so the sharee's UI has to surface it via a \"shared with me\" view that pulls from outside their natural subtree.\n\n### Approach 2: Add a second parent — for co-ownership\n\nThis is the right approach when Alice and Bob should be **true co-owners** of `list-shopping`: `user-bob` becomes a second parent of the list.\n\nAdding a parent edge is an access grant in structural clothing — everyone with grants on or above the new parent gains cascaded access to the child's subtree — so `addEdge` requires `write` on the new parent **and `admin` on the child** (the same tier `setPermission` demands). Neither party holds both (Alice has no `write` on `user-bob`; Bob starts with no `admin` on the list), and that's the point: co-ownership takes both the owner's consent and the recipient's acceptance. The flow is a two-step share-accept:\n\n1. **Alice offers** — grants Bob `admin` on the list (Approach 1 mechanics, at the top tier): `setPermission(listShoppingId, bobSub, 'admin')`.\n2. **Bob accepts** — adds the edge into his own subtree: `addEdge(userBobNodeId, listShoppingId)`. He holds `write` on `user-bob` and, since step 1, `admin` on the list.\n3. **Optional cleanup** — the direct grant is now redundant (Bob's `admin` on `user-bob` cascades to the list through the new edge): `revokePermission(listShoppingId, bobSub)` keeps the permissions table minimal.\n\n```mermaid\ngraph TD\n  root([root])\n  alice([user-alice])\n  bob([user-bob])\n  shopping[list-shopping]\n  work[list-work]\n  personal[list-personal]\n  root --> alice\n  root --> bob\n  alice --> shopping\n  alice --> work\n  bob --> personal\n  bob -. \"2nd parent\" .-> shopping\n\n  style shopping fill:#ffe4b5,color:#000\n```\n\nAfter cleanup, no direct grant on `list-shopping` remains. Effective-permission resolution climbs **all** ancestor paths and takes the maximum: Bob has `admin` via `user-bob`, Alice via `user-alice`. **Both users have full admin over the list.**\n\nThe flexibility to give one node multiple parents is what makes the underlying structure technically a **DAG** (directed acyclic graph) rather than a strict tree. The \"tree\" in \"org/permission tree\" is a friendly shorthand; the actual graph type is a DAG, with all the extra modeling power that brings.\n\n**Co-ownership is real, not nominal.** If Alice later \"removes the list from her account\" — which in UI terms means deleting her parent edge — the list doesn't disappear:\n\n```mermaid\ngraph TD\n  root([root])\n  alice([user-alice])\n  bob([user-bob])\n  shopping[list-shopping]\n  work[list-work]\n  personal[list-personal]\n  root --> alice\n  root --> bob\n  alice --> work\n  bob --> personal\n  bob --> shopping\n\n  style shopping fill:#ffe4b5,color:#000\n```\n\n`list-shopping` still exists under `user-bob`, who retains full admin. Symmetric: if Bob removes his edge instead, Alice keeps full admin. **Either party can leave; the other keeps everything.**\n\n**Use this when:**\n- You want both parties to have the same rights — e.g., a shared household to-do list both partners can edit and reshare equally.\n- You want either party to be able to leave the relationship without disrupting the other.\n- You want the shared item to appear in the second user's natural subtree, with no \"shared with me\" framing.\n- You want to give a whole group access by attaching a single edge — e.g., add `team-eng` as a second parent of every team project, and every member's grants on `team-eng` cascade in automatically.\n\n**Tradeoffs:**\n- You can't grant narrower-than-admin access this way. The sharee gets whatever they have on their own subtree, which is usually admin. For read-only sharing, Approach 1 is the right tool.\n- Mental model is harder: the same node appears in two places.\n- Cycles are still forbidden — if Alice tried to make `list-shopping` a parent of `user-bob`, the cycle detector at [dag-ops.ts](https://github.com/lumenize/lumenize/blob/main/apps/nebula/src/dag-ops.ts) would reject it.\n\n### When to use which\n\n| Goal | Approach 1 (grant) | Approach 2 (second parent) |\n|---|---|---|\n| Read-only sharing | ✓ the right tool | ✗ — sharee gets full admin |\n| Share `write` while keeping `admin` for yourself | ✓ the right tool | ✗ |\n| True co-ownership (both have admin, either can leave) | awkward to express | ✓ the right tool |\n| Either party can leave without taking the resource with them | ✗ — owner's delete is the resource's delete | ✓ — leaving = deleting only your edge |\n| Resource appears in sharee's natural subtree | ✗ | ✓ |\n| Grant to a whole group via a single edge | ✗ — per-resource grants | ✓ — one parent edge per resource |\n\nThe two approaches **compose freely** — a real app uses both. Grants for \"show this list read-only to my accountant\"; second-parent edges for \"this shared household list belongs to all the roommates equally.\"\n\nSee [Coding your UI § Worked example: rendering the built-in tree](./coding-your-ui.md#worked-example-rendering-the-built-in-tree) for the client-side patterns that render this structure (including the **multi-parent rendering** case — a node with two parents shows up under each one in the tree view).\n",
  ".platform/docs/api-reference.md": "---\ntitle: API reference\ndescription: API surface for @lumenize/nebula/frontend and the NebulaClient resources namespace.\n---\n\n# API reference\n\nThis page is the contract for the `@lumenize/nebula/frontend` factory + NebulaClient `resources` namespace. Every signature mentioned in [Coding your UI](./coding-your-ui.md) resolves to a section here. Conceptual explanations live there; this page is the lookup.\n\n## Status legend\n\nEach surface below carries one tag describing its provenance. The tags captured the **as-of-5.3.7-v1** state and the contract for what 5.3.7-v3 would implement; v3 has since shipped them — the surfaces below now live in `apps/nebula/src/frontend/` + NebulaClient (`apps/nebula/src/nebula-client.ts`).\n\n- **`implemented-in-spike`** — validated in the Vue-in-DOM spike, then ported to `apps/nebula/src/frontend/` in v3. (The spike — `apps/nebula/spike/vue-factory/` — was removed after the port, in 5.3.7/P11.)\n- **`new-in-v3`** — the spike didn't cover this; v3 designed and implemented it.\n- **`deferred-post-5.3.7`** — referenced for completeness but explicitly NOT shipping in 5.3.7 (v4/post-demo). These do not exist yet.\n\n## Summary\n\n| Surface | Tag | Section |\n| --- | --- | --- |\n| `createNebulaClient(config)` | new-in-v3 | [createNebulaClient](#createnebulaclient) |\n| `client.resources.subscribe(rt, rid)` | implemented-in-spike | [resources.subscribe](#resourcessubscribe) |\n| `client.resources.createAndSubscribe(rt, rid, nodeId, value)` | new-in-v3 | [resources.createAndSubscribe](#resourcescreateandsubscribe) |\n| `client.resources.unsubscribe(rt, rid)` | implemented-in-spike | [resources.unsubscribe](#resourcesunsubscribe) |\n| `client.resources.subscribeQuery(query, options?)` | new-in-v3 | [resources.subscribeQuery](#resourcessubscribequery) |\n| `client.resources.read(rt, rid, options?)` | implemented-in-spike | [resources.read](#resourcesread) |\n| `client.resources.transaction(ops, options?)` | implemented-in-spike (single-resource happy path); new-in-v3 (per-resource outcomes, infrastructure-error, multi-resource) | [resources.transaction](#resourcestransaction) |\n| `client.resources.onTransactionResourceResolution(rt, handler, options?)` | new-in-v3 (replaces shipped `onETagConflict`) | [resources.onTransactionResourceResolution](#resourcesontransactionresourceresolution) |\n| `client.resources.transactionDebounce(rt, opts)` (runtime override) | new-in-v3 | [resources.transactionDebounce](#resourcestransactiondebounce) |\n| `client.dispose()` | new-in-v3 | [client.dispose](#clientdispose) |\n| `client.logout()` | new-in-v3 | [client.logout](#clientlogout) |\n| `client.orgTree.*` (org/permission tree mutations) | new-in-v3 | [client.orgTree](#clientorgtree) |\n| org/permission tree at `store.lmz.orgTree` (dedicated channel, not a resource) | new-in-v3 | [OrgTreeState](#orgtreestate) |\n| `ROOT_NODE_ID` (sentinel UUID) constant | new-in-v3 | [OrgTreeState](#orgtreestate) |\n| Reserved state paths (`store.resources.*`, `store.lmz.*`) | implemented-in-spike | [Reserved state paths](#reserved-state-paths) |\n| `store.lmz.connection.{state, connected, lastConnectedAt}` | implemented-in-spike | [lmz.connection](#lmzconnection) |\n| `client.subscribeProfile(id)` (+ auto-subscribe on read) | new-in-v3 | [subscribeProfile](#subscribeprofile) |\n| `store.lmz.profiles[profileId].value.{name, nickname, picture}` | new-in-v3 | [store.lmz.profiles](#lmzprofiles) |\n| `client.subscribeQuerySubscribers(query)` (+ auto-subscribe on read) | new-in-v3 | [subscribeQuerySubscribers](#subscribequerysubscribers) |\n| `store.lmz.querySubscribers.<typeName>.<field>[value]` (live roster) | new-in-v3 | [store.lmz.querySubscribers](#lmzquerysubscribers) |\n| `textMerge(server, local, base)` helper | new-in-v3 | [textMerge](#textmerge) |\n| Handler `context.bindings` arg | deferred-post-5.3.7 | [Handler bindings](#handler-bindings) |\n| `TransactionOutcome` discriminated union (top-level, what `transaction()` resolves with) | implemented-in-spike (`'committed'` shape only); new-in-v3 (kinds `'committed'` / `'rejected'` / `'timeout'` / `'infrastructure-error'` / `'ontology-stale'`, `retryable` flag on failures) | [TransactionOutcome](#transactionoutcome) |\n| `TransactionResourceResolution` discriminated union (per-resource, what the handler receives) | new-in-v3 | [TransactionResourceResolution](#transactionresourceresolution) |\n| `ConflictResolverVerdict` (what the handler returns for `'conflict-pending'`) | implemented-in-spike (under old `ConflictResolution` name) | [ConflictResolverVerdict](#conflictresolververdict) |\n| `Snapshot` / `SnapshotMeta` (what reads, subscribes, and store entries hold) | implemented-in-spike (`meta.mimeType` new-in-v3) | [Snapshot](#snapshot) |\n| `client.claims` (inherited JWT payload) | inherited from `LumenizeClient` | [client.claims](#clientclaims) |\n\n## `createNebulaClient` {#createnebulaclient}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nfunction createNebulaClient(config: NebulaClientConfig): {\n  client: NebulaClient;\n  store: Record<string, any>;\n  ready: Promise<void>;\n  use: (middleware: Middleware) => () => void;\n  dispose: () => void;\n};\n```\n\nWraps a `NebulaClient` with a Vue-reactive store and a middleware chain. The factory **captures the client's current connection state at creation** (replay) and then tracks transitions via its observer — so registration order doesn't matter and `store.lmz.connection.*` is correct even if the client already advanced past its initial `connecting` transition. (`store.lmz.connection.*` is cosmetic UI status only — not an authorization boundary; authorization is enforced server-side on every operation. `ready` and `client.claims` only control what UI renders.)\n\n### Config\n\n`NebulaClientConfig` extends [`LumenizeClientConfig`](/docs/mesh/lumenize-client) (minus `refresh` and `gatewayBindingName`) with these additional fields. In a browser session that has completed the auth discovery flow, **only `ontologyVersion` is required** — all other fields auto-detect from the environment. The remaining fields stay configurable as escape hatches for admin/scripting callers (headless tests, server-side tooling) where there's no browser cookie or no same-origin server.\n\n| Field | Type | Default | Description |\n| --- | --- | --- | --- |\n| `ontologyVersion` | `string` | required | The installed ontology version this client's resource ops ride (the server enforces the match). Auto-attached to every `resources.*` call. Studio's bootstrap substitutes this at deploy time; that's the entire reason Studio's `nebula.ts` has substitution markup. |\n| `baseUrl` | `string` | `window.location.origin` | Origin of the back end. Default works whenever UI and API share an origin, which is Nebula's standard deployment shape (the tenant's Star serves both). Specify only for cross-origin admin/scripting use. |\n| `authScope` | `string` | from deployment URL | The scope whose per-scope refresh endpoint (`/auth/{authScope}/refresh-token`) and path-scoped cookie this client uses. A deployed app is pinned to one scope, taken from the deployment URL (`window.location`). NOT readable from the refresh cookie (it's HttpOnly). Specify only for cross-origin admin/scripting callers. |\n| `activeScope` | `string` | same as `authScope` | The scope a call's JWT is bound to (`aud`) — where you're currently working. Defaults to `authScope`. A Galaxy/Universe admin sets it to any scope at or below their own to work in a child Star or back in the parent (see [Auth flows § Admin active-scope switching](./auth-flows.md#admin-active-scope-switching-within-one-scopes-subtree)). Sent in the refresh body; the server bounds it against the scope on their membership. Differs from `authScope` by at least the active branch once branches exist. |\n| `onShouldRefreshUI?` | `(info: OntologyStaleInfo) => void` | `() => window.location.reload()` | Invoked when the server signals the client's app version is stale. The arg type **`OntologyStaleInfo`** (`{ clientVersion: string; currentVersion: string; reason: 'ontology-stale' }`) is exported from `@lumenize/nebula/frontend` — note its `reason` field is distinct from the `'ontology-stale'` **`TransactionOutcome`** variant's `kind` (different objects: the hook receives `OntologyStaleInfo`; the awaited transaction resolves `{ kind: 'ontology-stale', clientVersion, currentVersion }`). Default reload fetches the new bundle. Pass a custom function for \"new version available\" UX (banner, save-first prompt, etc.). **To opt out, pass an explicit no-op `() => {}`; omitting it keeps the default reload** (a stray `null` is coerced to the default too — there is no \"disable\" sentinel, by design). The default reload is once-guarded (a `sessionStorage` sentinel) so an immediate re-stale after the reload shows nothing rather than looping. |\n| `unsubscribeGraceMs` | `number` | `2000` | Grace period (ms) between binding-refcount reaching zero and `client.resources.unsubscribe` firing. New bindings inside the window cancel the pending unsubscribe. |\n\n### Return shape\n\n| Field | Type | Description |\n| --- | --- | --- |\n| `client` | `NebulaClient` | Lower-level API. Use for explicit subscriptions, reads, transactions, resolver registration. |\n| `store` | `Record<string, any>` | Vue-reactive Proxy. Reads inside a component's `setup()` auto-subscribe to the resources they touch (refcounted, grace-period-aware). Writes under `store.resources.<rt>.<rid>.value.*` flow through the synced-state middleware → optimistic apply + debounced transaction submission. Seeded with `resources`, `lmz` (`connection`, `orgTree`, `profiles`, `querySubscribers`), and empty `ui` / `app` objects. |\n| `ready` | `Promise<void>` | **Resolves** after the first successful connection — the initial token refresh has completed and `client.claims` is populated. Studio's bootstrap top-level-awaits it, so components in Studio-generated apps always render with claims present (see [client.claims](#clientclaims)). **Rejects** with a `LoginRequiredError` (mesh's existing terminal-auth signal, also delivered via the `onLoginRequired` hook — there is no separate `AuthRequiredError`) on *terminal* auth failure (no valid session — e.g. the refresh endpoint returns 401 for a logged-out visitor); the bootstrap catches it and redirects to the login / auth-discovery flow. It stays **pending** through *transient* failures (network blips, server restarts), which the client retries with backoff — so a flaky connection shows a loading state, not an error. The distinction matters: without it, a logged-out visitor's `ready` would hang forever and the top-level `await` would leave a blank page. |\n| `use(middleware)` | `(mw: Middleware) => () => void` | Register an additional middleware. Returns a deregistration function. Synced-state middleware is always-on; user-supplied middleware layers on top. |\n| `dispose()` | `() => void` | Same as [`client.dispose()`](#clientdispose): flush pending debounced writes, clear refcount + pending-unsubscribe timers, dispose internal scopes, and disconnect the underlying `LumenizeClient` WebSocket. |\n\n### Example\n\nThe Studio-generated `nebula.ts` in a browser app:\n\n```typescript @skip-check\n// nebula.ts (Studio bootstrap)\nimport { createNebulaClient } from '@lumenize/nebula/frontend';\n\nexport const { client, store, ready } = createNebulaClient({\n  ontologyVersion: __APP_VERSION__,   // Studio substitutes at deploy time\n});\n\n// Top-level await: main.ts (and every component) imports this module, so the\n// app mounts only after the first connection — client.claims is populated\n// before any component renders. See § client.claims.\ntry {\n  await ready;\n} catch {\n  // Terminal auth failure (logged-out visitor) — go authenticate. Transient\n  // failures don't reject; they keep retrying behind a loading state.\n  window.location.assign('/login');\n}\n```\n\nAll other fields auto-detect: `baseUrl` from `window.location.origin`, `authScope` from the deployment URL (`window.location`) with `activeScope` defaulting to it, `onShouldRefreshUI` from the default reload.\n\nAdmin/scripting form with all overrides explicit:\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nconst { client, store } = createNebulaClient({\n  baseUrl: 'https://my-app.example.com',\n  authScope: 'acme.app.tenant-a',\n  activeScope: 'acme.app.tenant-a',\n  ontologyVersion: 'v42',\n  onShouldRefreshUI: () => {},    // opt out of auto-reload (null/undefined both KEEP the default reload)\n});\n```\n\nSee [Coding your UI § Building your UI on top of Resources](./coding-your-ui.md#building-your-ui-on-top-of-resources) for how `nebula.ts` fits into the Studio-managed bootstrap, and [tasks/nebula-studio.md § Bootstrap files](https://github.com/lumenize/lumenize/blob/main/tasks/nebula-studio.md) for what Studio scaffolds.\n\n## `client.resources.subscribe` {#resourcessubscribe}\n\n**Tag**: `implemented-in-spike` (return shape reshaped in v3 — now a `Disposable` handle for `using`-compatible scope binding).\n\n```typescript @skip-check\nsubscribe(resourceType: string, resourceId: string): ResourceSubscription;\n\ninterface ResourceSubscription extends Disposable {\n  /** Resolves with the initial snapshot on the first server-side `handleResourceUpdate`\n   *  for `(rt, rid)`. Subsequent fanout updates write through to bound state but\n   *  do not re-resolve this promise. */\n  readonly snapshot: Promise<Snapshot | null>;\n  /** Manual unsubscribe; equivalent to leaving a `using` scope. */\n  [Symbol.dispose](): void;\n}\n```\n\nSubscribes synchronously (registers the subscriber row immediately); the **initial snapshot** arrives asynchronously via `handleResourceUpdate` and is exposed on `.snapshot`.\n\n:::note[The resource must already exist]\n\n`subscribe` requires the resource to exist — there is no subscribe-before-create path on the server (a subscription's read authorization is derived from the resource's current snapshot, which a not-yet-created resource doesn't have). Subscribing to an absent resource **rejects** `.snapshot`. To create a resource and start observing it in one step, use [`createAndSubscribe`](#resourcescreateandsubscribe).\n\n:::\n\nIf a pending subscribe for the same `(rt, rid)` already exists, the new handle's `.snapshot` piggybacks on that pending settlement instead of issuing a duplicate request. `[Symbol.dispose]()` decrements per-handle; the underlying server-side subscription releases when the last handle disposes (mirrors auto-subscribe's refcount-with-grace).\n\n### Idiomatic usage with `using`\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n{\n  using sub = client.resources.subscribe('todo', 'task-42');\n  const snap = await sub.snapshot;            // wait for initial fanout if you care\n  // ... work with the resource ...\n}                                              // auto-unsubscribes here\n```\n\n### Manual control (subscribe and unsubscribe in different places)\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// Some setup code:\nclient.resources.subscribe('todo', 'task-42');                  // handle discarded; subscription stays live\n\n// Some teardown code, possibly elsewhere:\nclient.resources.unsubscribe('todo', 'task-42');                // standalone API\n```\n\n**Typical usage**: rarely called directly. Most subscriptions happen via auto-subscribe (reading from the store inside a Vue component triggers `subscribe` on the underlying client). Call explicitly only when subscribing to a resource the UI doesn't yet bind to — warming a cache before navigation, scripting, headless tests. The `using` form is the idiomatic explicit pattern; the standalone `unsubscribe` is for cases where the subscribe and release sites legitimately differ.\n\n**TypeScript requirement**: `Disposable` and the `using` keyword are ES2023 / TypeScript 5.2+. Studio-generated tsconfig includes the needed `lib: [\"ESNext\"]` or equivalent.\n\n## `client.resources.createAndSubscribe` {#resourcescreateandsubscribe}\n\n**Tag**: `new-in-v3`.\n\n```typescript @skip-check\ncreateAndSubscribe(\n  resourceType: string,\n  resourceId: string,\n  nodeId: string,\n  value: unknown,\n): ResourceSubscription;\n```\n\nThe ergonomic form of the **create-then-subscribe** pattern: since [`subscribe`](#resourcessubscribe) requires the resource to already exist, this method sequences a `create` [transaction](#resourcestransaction) followed by a `subscribe`, client-side, so you get one call and a `using`-compatible handle. Returns the [`ResourceSubscription`](#resourcessubscribe) **synchronously** (refcount + `[Symbol.dispose]()` behave exactly as `subscribe`); the underlying server subscribe is deferred until the create commits, so `.snapshot` resolves with the **freshly-created snapshot**.\n\nIf the create does **not** commit (the resource already exists, or a permission / validation failure), `.snapshot` **rejects** — use plain `subscribe` for a resource that already exists. Disposing the handle before the create lands cancels the pending subscription (the already-submitted create is not unwound). It routes to the active scope's Star binding like every other resource call (so it works against a dev Star too).\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/nebula-client-create-and-subscribe.test.ts')\nusing sub = client.resources.createAndSubscribe('Todo', rid, ROOT_NODE_ID, { title: 'made', done: false });\nconst snap = await sub.snapshot;\n```\n\n## `client.resources.unsubscribe` {#resourcesunsubscribe}\n\n**Tag**: `implemented-in-spike`\n\n```typescript @skip-check\nunsubscribe(resourceType: string, resourceId: string): void;\n```\n\nUnsubscribe from a resource. Fire-and-forget. Server drops the subscriber row.\n\n**Equivalent to calling `[Symbol.dispose]()` on the matching [`ResourceSubscription`](#resourcessubscribe) handle.** Use this standalone form when the subscribe and unsubscribe sites legitimately differ (a parent component subscribes; an unrelated event handler later unsubscribes). When subscribe and unsubscribe live in the same scope, prefer `using` — see [`subscribe`](#resourcessubscribe) for the idiomatic form.\n\nAuto-subscribe handles the common case (component unmount → grace period → unsubscribe). Call explicitly only when you subscribed explicitly.\n\n## `client.resources.subscribeQuery` {#resourcessubscribequery}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nsubscribeQuery(query: QueryDescriptor, options?: { renderGraceMs?: number }): QuerySubscription;\n```\n\nSubscribe to a **live query** — the ordered set of resource ids matching a relationship query, kept current as resources are created / deleted / re-parented. Fire-and-forget (the client computes the query's canonical hash locally and correlates pushes by it — ADR-003), so the initial membership arrives asynchronously: `await handle.ready`. Membership is REPLACED on every push (idempotent, self-healing — no delta merge).\n\nv1 supports exactly one query shape — equality on a single to-one relationship field:\n\n```typescript @skip-check\ninterface QueryDescriptor {\n  queryType: 'parentChild';   // the only v1 queryType\n  typeName: string;           // the CHILD type being matched, e.g. 'Message'\n  field: string;              // its to-one relationship field, e.g. 'session'\n  value: string;              // the parent id that `field` must equal\n  onPartial?: 'error' | 'allow';  // per-push shape for a subscriber with denied nodes (default 'allow')\n  orderBy?: 'validFrom';          // v1 only (default)\n}\n```\n\nThe handle is a `using`-compatible `QuerySubscription`:\n\n```typescript @skip-check\ninterface QuerySubscription extends Disposable {\n  readonly ready: Promise<void>;          // resolves on the first push; rejects if the query is rejected\n  readonly resourceIds: string[];         // current ordered membership — the ids you may read\n  readonly deniedNodes: string[];         // node ids you can't reach (drives request-access UI)\n  setRenderWindow(resourceIds: string[]): void;  // open content subs for exactly these ids\n  onChange(cb: () => void): void;          // fired on every membership / denied change\n}\n```\n\n**The query delivers ids, not content.** `resourceIds` is the ordered membership; read each resource's value the normal way (`store.resources.<typeName>[id].value.*`), which auto-subscribes it. For large results, call `setRenderWindow(ids)` with just the ids you're actually rendering (e.g. the 25 visible rows of a virtual list) — the factory opens per-resource content subscriptions for exactly those and releases ids that scroll out of view after a grace period. Content subs are refcounted and shared with direct [`subscribe`](#resourcessubscribe).\n\n`deniedNodes` lists nodes the subscriber can't reach; surface a \"request access\" affordance (climb the org tree to the nearest admin — see [`OrgTreeState`](#orgtreestate)). `[Symbol.dispose]()` is per-handle (refcounted); the server-side `unsubscribeQuery` fires when the last handle releases.\n\nTo watch **who is subscribed** to a query (its live roster) rather than its data, see [`client.subscribeQuerySubscribers`](#subscribequerysubscribers).\n\n## `client.resources.read` {#resourcesread}\n\n**Tag**: `implemented-in-spike`\n\n```typescript @skip-check\nread(\n  resourceType: string,\n  resourceId: string,\n  options?: ReadOptions,\n): Promise<Snapshot | null>;\n\ninterface ReadOptions {\n  ontologyVersion?: string;   // override constructor's version for this call\n}\n```\n\nAd-hoc read of a resource. Each call gets its own `requestId`; concurrent reads to the same `(rt, rid)` are independently correlated.\n\n**Does NOT write to the store.** `read` is for scripting and ad-hoc inspection. For reactive UI, use the store + auto-subscribe (or `subscribe` explicitly).\n\nReturns `null` only if the resource was **never created**. A soft-deleted resource returns a real `Snapshot` with `meta.deleted: true` (see [Snapshot](#snapshot)) — `null` never means \"deleted.\"\n\n## `client.resources.transaction` {#resourcestransaction}\n\n**Tag**: `implemented-in-spike` for single-resource happy path; `new-in-v3` for the new two-level `TransactionOutcome` shape + per-resource handler invocations + infrastructure-error wrapping.\n\n```typescript @skip-check\ntransaction(\n  ops: Record<string, OperationDescriptor>,\n  options?: TransactionOptions,\n): Promise<TransactionOutcome>;\n```\n\nSubmit a transaction. **Always resolves** with a [`TransactionOutcome`](#transactionoutcome); never rejects. Infrastructure failures (network drops, mesh crashes) come back as `{ kind: 'infrastructure-error', error }` so the caller's `switch` at the await-site handles every transaction-wide terminal state in one place.\n\nPer-resource outcomes (commit, server-wins, conflict-pending, validation-failed, permission-denied, etc.) are NOT handled at the await-site — they're delivered to the per-type [`onTransactionResourceResolution`](#resourcesontransactionresourceresolution) handler (or its per-call override). The await-site's `switch` only needs to handle the transaction-wide cases.\n\n### `ops` shape\n\n`ops` is keyed by `resourceId`. Each value is an `OperationDescriptor`:\n\n```typescript @skip-check\ntype OperationDescriptor =\n  | { op: 'create'; typeName: string; nodeId: string; value: any }\n  | { op: 'put';    typeName: string; value: any;       eTag?: string }\n  | { op: 'move';   typeName: string; nodeId: string;   eTag?: string }\n  | { op: 'delete'; typeName: string;                   eTag?: string };\n```\n\n`typeName` is required on every op (needed for client-side `eTag` lookup on put/move/delete; matches `create`'s pre-existing requirement).\n\n**`eTag` auto-derives from the local store.** For `put` / `move` / `delete`, omitting `eTag` causes the factory to look up `store.resources.<typeName>[<resourceId>]?.meta?.eTag` at call time and use that as the optimistic-concurrency baseline. This is the normal case — UI code never has to wire eTags manually. If the resource isn't in the local store (e.g., admin/scripting code that hasn't subscribed), the call throws a clear client-side error rather than letting the server reject; pass `eTag` explicitly to bypass auto-derive (see [Explicit eTag override](#explicit-etag-override) below).\n\nMulti-resource transactions are atomic: every op commits or none do.\n\n### `TransactionOptions`\n\n| Field | Type | Default | Description |\n| --- | --- | --- | --- |\n| `ontologyVersion` | `string` | constructor's `ontologyVersion` | Override for admin/scripting calls. |\n| `newETag` | `string` | `crypto.randomUUID()` | One `newETag` shared across every op in the batch. Override for the idempotency-retry pattern (a dropped response is retried with the same `newETag` to avoid double-write). |\n| `onTransactionResourceResolution` | `Record<string, ResourceHandler>` | per-type registered, else framework default | Per-call handlers, **keyed by `resourceId`** — e.g. `{ 'task-42': handler }`. Each entry handles only its own resource; resources NOT in the map fall through to their per-type handler automatically (no defensive `rid` filtering needed). A listed resource's entry **layers in front of** its per-type handler — verdict-returning on `'conflict-pending'`, additive on terminal branches. See [Precedence](#precedence). |\n| `maxRetries` | `number` | per-call value, else min across involved per-type values, else `5` | **Batch-level** cap on the conflict resolve-and-resubmit loop. On exhaustion the batch lands at top-level `{ kind: 'rejected', retryable: true }` with that resource at `'retries-exhausted'`. The retry budget is client-side policy (the server stays stateless + `newETag`-idempotent). In a multi-type batch the per-call value wins, else the **min** across the involved per-type values. |\n\n### Example — single resource\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// eTag auto-derives from store.resources.todo['task-42']?.meta?.eTag.\nconst outcome = await client.resources.transaction({\n  'task-42': { op: 'put', typeName: 'todo', value: { title: 'New title' } },\n});\n```\n\n### Example — multi-resource atomic batch\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nconst newId = crypto.randomUUID();\nconst outcome = await client.resources.transaction({\n  [newId]: { op: 'create', typeName: 'todo', nodeId: ROOT_NODE_ID,\n             value: { title, description: '', status: 'open' } },\n  // per-user keying — see Coding your UI § Lists with v-for\n  [client.claims.sub]: { op: 'put', typeName: 'todoList',\n             value: { ...list, items: [...list.items, newId] } },\n});\n```\n\nIf either op fails (validation, conflict, permission), neither commits. Use this shape when one resource references another by ID — atomicity prevents orphans and dangling references.\n\n### Explicit eTag override {#explicit-etag-override}\n\nPass `eTag` explicitly to bypass auto-derive. Two real use cases:\n\n1. **Resource not in the local store** — admin/scripting code that submits a put/delete without first subscribing. Auto-derive would throw; passing `eTag` lets the call proceed.\n2. **Baseline on a stashed snapshot, not the current local one** — e.g., the human-in-the-loop conflict pattern stashes a `server.meta.eTag` at conflict-detection time and submits resolution later against that specific baseline. The local store may have moved on; the stashed eTag is the right baseline. See [Resources § human-in-the-loop verdict](./resources.md#human-in-the-loop-verdict-non-blocking--defer-to-the-app).\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// Explicit baseline — Bob's resolution submission against the stashed snapshot.\nconst outcome = await client.resources.transaction({\n  'task-42': { op: 'put', typeName: 'todo',\n               eTag: conflict.server.meta.eTag,            // ← stashed baseline, not auto-derived\n               value: resolvedValue },\n});\n```\n\nIn typical UI code (every example outside this subsection), omit `eTag` and let the framework derive it.\n\n## `client.resources.onTransactionResourceResolution` {#resourcesontransactionresourceresolution}\n\n**Tag**: `new-in-v3`. Replaces the shipped `onETagConflict(rt, resolver, options?)` — it absorbs the conflict-resolver job and adds reactions for every per-resource outcome (committed, validation-failed, permission-denied, etc.).\n\n```typescript @skip-check\nonTransactionResourceResolution(\n  resourceType: string,\n  handler: ResourceHandler,\n  options?: OnTransactionResourceResolutionOptions,\n): void;\n\ntype ResourceHandler = (\n  resourceId: string,\n  resolution: TransactionResourceResolution,\n) =>\n  | ConflictResolverVerdict\n  | Promise<ConflictResolverVerdict>\n  | void;\n\ninterface OnTransactionResourceResolutionOptions {\n  /** Per-type contribution to the **batch-level** `'use-this'` retry cap (the min across a\n   *  batch's involved types is used; a per-call `maxRetries` overrides). On exhaustion the\n   *  batch lands at top-level `{ kind: 'rejected', retryable: true }` with this resource at\n   *  `'retries-exhausted'`. Default 5. */\n  maxRetries?: number;\n  /** Default flash classes for this resource's resolution. **Reserved — DOM flash is deferred\n   *  to v4**; no effect in 5.3.7. `null` disables the corresponding default once flash lands. */\n  flashClass?: {\n    committed?: string | null;    // default 'lumenize-commit-success' (green outline animation)\n    rolledBack?: string | null;   // default 'lumenize-conflict-revert' (red outline animation)\n  };\n  /** Flash duration in ms. Default 1000. */\n  flashDuration?: number;\n}\n```\n\nRegister a per-type handler. Fires once per resource per transaction with a [`TransactionResourceResolution`](#transactionresourceresolution). The handler does two jobs in one place:\n\n1. **Decide conflict resolutions** — when called with `{ kind: 'conflict-pending', local, server, base, context }`, the handler returns a [`ConflictResolverVerdict`](#conflictresolververdict) that drives the next step (`'use-server'` / `'use-this'` / `'human-in-the-loop'`). Return `undefined` to fall through to the next handler in the chain (a per-type handler if this is a per-call override, then the framework default `{ kind: 'use-server' }` — see [Precedence](#precedence)). `base` is the common ancestor needed for a correct 3-way merge — see [`textMerge`](#textmerge).\n2. **React to terminal outcomes** — for all other resolution values, the handler's return is ignored; the handler is purely informational (flash custom classes, surface validation errors, navigate, etc.).\n\nThe same handler can fire multiple times for a single resource in a single transaction if the chain involves `'use-this'`: first call is `'conflict-pending'` → handler returns `{ kind: 'use-this', value }` → framework re-submits → maybe conflicts again → handler fires with `'conflict-pending'` again → eventually terminates at `'committed'` or `'retries-exhausted'`.\n\n### Default flashes\n\n**Deferred to v4** — no DOM-flash mechanism ships in 5.3.7. Finding the bound elements needs a binding-discovery mechanism Vue doesn't provide for free, so the decision (a compiler-injected flash directive is the leading candidate) is deferred. The class vocabulary and the `flashClass` / `flashDuration` options are **reserved** so the API stays stable; they have no DOM effect in 5.3.7. When flash lands, the framework will add these classes to the affected fields' elements:\n\n| Resolution branch | Default class | Intent |\n| --- | --- | --- |\n| `'committed'` | `lumenize-commit-success` | Green outline, brief animation — signals \"your write landed.\" |\n| `'use-server'`, `'permission-denied'`, `'validation-failed'`, `'retries-exhausted'` | `lumenize-conflict-revert` | Red outline, brief animation — signals \"your write was reverted to a server-authoritative value.\" |\n| `'human-in-the-loop'` | (none — app handles UX explicitly) | — |\n| `'conflict-pending'` | (none — handler is deciding) | — |\n\nWhen it lands, the framework will just toggle class names (the user-facing CSS lives in app stylesheets). See [Resources § Custom flash visuals](./resources.md#custom-flash-visuals).\n\n### Precedence\n\nThe per-call `options.onTransactionResourceResolution` is a **map keyed by `resourceId`** (`Record<string, ResourceHandler>`), so each entry handles exactly one resource and resources absent from the map fall through to their per-type handler with no defensive filtering. A listed resource's per-call entry **layers in front of** that resource's per-type handler (it does not replace it):\n\n- **`'conflict-pending'`** (verdict-returning): the resource's per-call entry first; returning `undefined` falls through to the per-type handler; *its* `undefined` falls through to the framework default (`{ kind: 'use-server' }`). The first non-`undefined` verdict wins.\n- **Terminal branches** (return ignored): the per-type handler fires for every resource; a per-call entry's terminal reaction layers on top (additive) for its own resource.\n\nConcretely: a form's `transaction(ops, { onTransactionResourceResolution: { 'task-42': handler } })` handles `task-42` and leaves a sibling `todoList` in the same batch to its per-type set-union handler — the override **can't** shadow it, because `todoList` isn't a key in the map. (The map values are ordinary `ResourceHandler`s; the `resourceId` first arg equals the key.)\n\nSee [TransactionResourceResolution](#transactionresourceresolution) for the input shape and [ConflictResolverVerdict](#conflictresolververdict) for the return shape on `'conflict-pending'`.\n\n## `client.resources.transactionDebounce` {#resourcestransactiondebounce}\n\n**Tag**: `new-in-v3`. Runtime override only — for normal use, debounce config is declared in the ontology and emitted into the validator bundle Studio ships with each app.\n\n```typescript @skip-check\ntransactionDebounce(\n  resourceType: string,\n  opts: {\n    quietMs?: number;       // type default for fields without an explicit setting\n    maxWaitMs?: number;\n    fields?: Record<string, { quietMs?: number; maxWaitMs?: number }>;\n  },\n): void;\n```\n\n**The primary surface for debounce config is the ontology**, not this call. Field-type-derived defaults (e.g., `boolean` → `quietMs: 0`) and explicit `@debounce(q, m)` / `@longform` annotations on the .d.ts compile into the bundle the factory loads at startup. See [Ontology § Annotations](./ontology.md#annotations).\n\n`transactionDebounce` exists as a **runtime override** for edge cases the annotation model doesn't cover — A/B testing different debounce values, slower-network modes, role-based tuning. Precedence: runtime override > ontology annotation > type-based default > framework default (`500` / `2000`).\n\n**Resource-level merge rule** when multiple fields have pending writes with different timings: **shortest active timer wins** for both `quietMs` and `maxWaitMs`. Clicking a `@debounce(0)` checkbox flushes the entire pending resource transaction immediately, including any pending text-field edits — which matches the intuition that the click was a deliberate commit.\n\nOther middleware-level behaviors (always-on, not configurable per-call): pending writes flush on input blur (a `focusout` on the bound input) and on `client.dispose()` (component unmount does not itself flush — the quiet/max-wait timers, which are per-`(rt, rid)` not per-component, still submit a buffered write on schedule). At most one transaction in flight per `(rt, rid)`; subsequent writes buffer and submit using the in-flight transaction's resulting eTag. State machine + property tests at [tasks/archive/debounce-serial-queue.md](https://github.com/lumenize/lumenize/blob/main/tasks/archive/debounce-serial-queue.md).\n\n## `client.dispose` {#clientdispose}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nclient.dispose(): void;\n// Also available on the factory return as `dispose()`.\n```\n\nTear down the factory:\n\n1. Flush every pending debounced write through the serial-per-resource queue.\n2. Clear refcount + pending-unsubscribe timers.\n3. Dispose internal effectScopes.\n4. Disconnect the underlying `LumenizeClient` WebSocket.\n\nAfter dispose, the store remains readable (Vue reactivity is independent) but writes no longer trigger transactions and no new subscribes fire. Typically called only in tests or at full page teardown.\n\n## `client.logout` {#clientlogout}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nclient.logout(): Promise<void>;\n```\n\nUser-initiated **sign-out**: revokes + clears the (HttpOnly, path-scoped) refresh cookie via the auth logout endpoint, drops the in-memory access token, and sets `store.lmz.connection.state` to `'disconnected'`. The app then redirects to login — typically the same redirect the `ready` / `onLoginRequired` terminal-auth path uses.\n\nDistinct from [`client.dispose()`](#clientdispose), which tears down the client/connection **without** revoking the session (a disposed client could reconnect with the same valid cookie; a logged-out one cannot). The server-side logout endpoint is a nebula-auth concern added alongside this method.\n\n## `client.orgTree` {#clientorgtree}\n\n**Tag**: `new-in-v3`. The client-facing namespace is built in v3; the server-side methods it proxies already exist at [`apps/nebula/src/dag-tree.ts`](https://github.com/lumenize/lumenize/blob/main/apps/nebula/src/dag-tree.ts).\n\nMutations to the app's **org/permission tree** (the DAG that resources attach to for tenancy and access control). The conceptual model — cascading permissions, the two sharing approaches — is in [Resources § Access control](./access-control.md); the usage patterns and worked examples are in [Coding your UI § Mutating the org/permission tree](./coding-your-ui.md#mutating-the-orgpermission-tree).\n\n**Reads do not go through this namespace.** The full tree is delivered on a dedicated channel to `store.lmz.orgTree.value` (an [`OrgTreeState`](#orgtreestate)) — under the framework-reserved `store.lmz.*` prefix, not `store.resources.*` (the tree isn't a resource). Bind to it reactively rather than polling a query method. `client.orgTree.*` is mutations only.\n\n**Unlike [`transaction()`](#resourcestransaction), these reject the returned Promise on failure.** Each method is a request/response mesh call, Promise-correlated client-side: a permission failure, cycle violation, slug collision, or unknown node rejects the returned Promise. There is no `TransactionOutcome` wrapper — `try`/`catch` (or `.catch`) at the call site. (Tree mutations are infrequent and individually meaningful, so a plain reject is the right ergonomics here; the always-resolve `TransactionOutcome` is for the high-frequency resource-write path.)\n\n**While disconnected:** there is no connection-gating here (unlike the resource write path — tree mutations hold no optimistic store state to roll back, and the await-site handles the reject). A call issued while offline is queued and sent on reconnect (or rejects on timeout); a call already in flight when the socket drops is **not** auto-resubmitted — it times out and rejects.\n\nEvery method requires the caller to hold a permission on the relevant node, resolved by the same cascading rules as resource access (`admin` on the node grants everything below it). Node ids are **client-supplied UUID strings** (`crypto.randomUUID()`); `sub` is a JWT subject claim — a bare UUID as minted by nebula-auth (the current user's is `client.claims.sub`; grants are matched by exact string equality against the JWT `sub`). `ROOT_NODE_ID` (a reserved sentinel node) cannot be deleted, undeleted, or renamed. `createNode` is deliberately **not** one of the before-permission short-circuits below — its replay returns node content (slug/label), so it checks `write` on the parent *first*, then does the id-presence check. (One nuance: an **idempotent no-op** — adding an edge that exists, removing one that doesn't, revoking an absent grant, deleting an already-deleted node, or undeleting a live one — short-circuits to success *before* the permission check, so it neither mutates nor requires permission. This short-circuit is non-disclosing **only because** the tree is universally visible (M7) — a caller can already see every edge/grant, so \"exists\" (success) vs \"absent\" (permission-checked) reveals nothing new. If tree visibility is ever scoped per-branch, these short-circuits must move *after* the permission check, or they become an existence oracle for unauthorized callers.)\n\n### Structural mutations (require `write`)\n\n```typescript @skip-check\n// Create a child node. `slug` must match /^[a-z0-9](?:[a-z0-9-]{0,98}[a-z0-9])?$/\n// and be unique among siblings. The CALLER supplies the node's id (a v4 UUID,\n// `crypto.randomUUID()`); createNode is idempotent — a retry with the same id\n// returns the same node (a reused id with a different slug throws loudly).\ncreateNode(nodeId: string, parentNodeId: string, slug: string, label: string): Promise<string>;\n\n// Add a second parent edge (the co-ownership pattern — see Resources §\n// Access control for the two-party share-accept flow). Requires `write` on\n// the new parent AND `admin` on the child: adding a parent edge is an access\n// grant in structural clothing (everyone with grants on/above the new parent\n// gains cascaded access to the child's subtree), so the child side demands\n// setPermission's tier. Idempotent; cycle- and sibling-slug-uniqueness-checked.\naddEdge(parentNodeId: string, childNodeId: string): Promise<void>;\n\n// Remove a parent edge (\"remove from my account\"). Idempotent.\nremoveEdge(parentNodeId: string, childNodeId: string): Promise<void>;\n\n// Move a node from one parent to another in one step. Requires `write` on BOTH\n// the old and the new parent, PLUS `admin` on the child — re-parenting adds a\n// parent edge, so it has addEdge's access-widening property (see addEdge above).\n// Cycle- and slug-uniqueness-checked.\nreparentNode(childNodeId: string, oldParentId: string, newParentId: string): Promise<void>;\n\n// Soft-delete (sets the node's `deleted` flag; the row survives). Idempotent.\ndeleteNode(nodeId: string): Promise<void>;\n\n// Reverse a soft-delete. Idempotent.\nundeleteNode(nodeId: string): Promise<void>;\n\n// Change the slug (the URL/path segment). Validated and re-checked for\n// uniqueness under every parent of the node.\nrenameNode(nodeId: string, newSlug: string): Promise<void>;\n\n// Change the human-readable display label (non-empty, ≤ 500 chars).\nrelabelNode(nodeId: string, newLabel: string): Promise<void>;\n```\n\nThe `write` permission is checked on the node being changed — for `createNode`/`removeEdge` that's the parent; for the node-targeting methods it's the node itself. Both edge-*adding* operations also require **`admin` on the child** because they widen who has cascaded access to it: `addEdge` checks `write` on the new parent **plus `admin` on the child**, and `reparentNode` checks `write` on **both** parents **plus `admin` on the child** (see the comments above).\n\n**`createNode` is idempotent** — the caller supplies the node's id (a v4 UUID), so a retry with the same id returns the same node rather than creating a duplicate. This closes the old ambiguous-disconnect gap: because the client already holds the id it minted, it can always address the node it may have created, even if the response was lost. A reused id with a *different* parent/slug throws a loud `NodeIdCollisionError` (never a silent no-op). One boundary remains: the client call is still an awaited request whose pending Promise is bound to the WebSocket, so an **in-session** WS drop leaves it hanging until timeout — that delivery strand is handled separately by the mesh continuation layer; interim recovery is reload → `store.lmz.orgTree` re-sync.\n\n### Permission management (require `admin`)\n\n```typescript @skip-check\n// Grant or upsert a permission tier for `sub` on `nodeId`. Cascades to all\n// descendants.\nsetPermission(nodeId: string, sub: string, level: 'admin' | 'write' | 'read'): Promise<void>;\n\n// Revoke `sub`'s direct grant on `nodeId`. Idempotent — no-op if absent.\nrevokePermission(nodeId: string, sub: string): Promise<void>;\n```\n\n`setPermission` only manages grants attached directly to `nodeId`; a user can still hold an effective permission via a grant on an ancestor. To narrow effective access, attach the resource deeper rather than revoking ancestor grants.\n\n### `OrgTreeState` {#orgtreestate}\n\n**Tag**: `new-in-v3` — both the type export and the tree delivery. The tree is **not a resource**: it's delivered on a dedicated channel (server `DagTree.#onChanged` → broadcast to a `clientId`-keyed registry, synthesized from `dagTree.getState()`) to `store.lmz.orgTree`, and mutated via [`client.orgTree.*`](#clientorgtree) — never `transaction()`. It's universally visible by design (every connected client gets the full tree; see M7). Authoritative spec: the \"Org/permission tree delivery (design B)\" item in [tasks/archive/nebula-frontend.md § Phase 5.3.7-v3](https://github.com/lumenize/lumenize/blob/main/tasks/archive/nebula-frontend.md); the superseded design-space record is § DAG-tree-as-special-resource.\n\nThe shape of the tree at `store.lmz.orgTree.value`. Exported from `@lumenize/nebula/frontend`.\n\n```typescript @skip-check\ninterface OrgTreeState {\n  nodes: Map<string, { slug: string; label: string; deleted: boolean }>;\n  edges: Set<`${string}:${string}`>;   // \"parentId:childId\" edge keys (UUIDs)\n  permissions: Map<string, Map<string, 'admin' | 'write' | 'read'>>;\n}\n```\n\n`edges` is the canonical, wire-shippable adjacency form. For O(1) parent/child lookups during a tree walk, build an `OrgTreeView` with `buildOrgTreeView(state)` (also exported from `@lumenize/nebula/frontend`) — it derives `childrenByParent` and `parentsByChild` indexes from `edges`. See [Coding your UI § Worked example: rendering the built-in tree](./coding-your-ui.md#worked-example-rendering-the-built-in-tree).\n\n`ROOT_NODE_ID` (a reserved sentinel UUID, the root node every Star is provisioned with) is also exported from `@lumenize/nebula/frontend` — the bootstrap and admin-gating examples in Coding your UI import it.\n\n## `client.subscribeProfile` {#subscribeprofile}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nsubscribeProfile(profileId: string): ResourceSubscription;\n```\n\nSubscribe to a person's **public profile** (`name` / `nickname` / `picture`) by their `profileId` — a global, cross-Star identity handle, delivered on a dedicated channel to [`store.lmz.profiles[profileId]`](#lmzprofiles). Returns the same `using`-compatible [`ResourceSubscription`](#resourcessubscribe) handle as `resources.subscribe` (`.snapshot` resolves with the first snapshot; `[Symbol.dispose]()` releases on the last handle).\n\nYou rarely call this directly — **reading `store.lmz.profiles[profileId].value` inside a component auto-subscribes it** (refcounted, grace-period-aware, windowed), exactly like reading a resource. The common pattern is resolving display identity for ids you already hold (the current user's own `client.claims.profileId` for the app chrome, or each `profileId` in a roster).\n\nProfiles are read-only through the store; the owner edits their own profile via a separate write path. A profile is a **shape**, not a resource — it lives under `store.lmz.*` (never `store.resources.*`), so a dev-user ontology type named `Profile` does **not** collide with it.\n\n## `client.subscribeQuerySubscribers` {#subscribequerysubscribers}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nsubscribeQuerySubscribers(query: QueryDescriptor): SubscriberListSubscription;\n```\n\nSubscribe to a query's **live subscriber-list roster** — the distinct-by-person set of everyone currently subscribed to that query's data — WITHOUT subscribing to the data itself. \"Who's here / who's online\" for a shared view. The roster is delivered to [`store.lmz.querySubscribers.<typeName>.<field>[value]`](#lmzquerysubscribers) as a reactive array of `{ sub, profileId }`, kept current as people join and leave.\n\n```typescript @skip-check\ninterface SubscriberListSubscription extends Disposable {\n  readonly ready: Promise<void>;  // resolves on the first roster push; rejects if the query is rejected\n}\n```\n\nAs with the other surfaces, you rarely call this directly — **reading the query-in-path `store.lmz.querySubscribers.<typeName>.<field>[value]` auto-subscribes the roster** (the path segments *are* the [`QueryDescriptor`](#resourcessubscribequery)). Resolve each entry's `profileId` to a display name/avatar by reading [`store.lmz.profiles[profileId]`](#lmzprofiles) — window it (subscribe only the profiles for rendered rows) exactly as you window a large query. The roster is advisory/display-only (reachability-gated, uniform — it carries no permission data).\n\n## Reserved state paths\n\n**Tag**: `implemented-in-spike`\n\nTwo top-level prefixes on the store are framework-reserved — but \"reserved\" doesn't mean read-only. `store.resources.<rt>.<rid>.value.*` is the **primary write surface**: `v-model` and assignments there flow through the synced-state middleware → optimistic apply + transaction (see the `set`-trap note below). What's restricted is narrower: `meta.*` is server-owned (writes pass through but are warned in debug builds), and `store.lmz.*` is framework-written only (user writes dropped) — this prefix holds `store.lmz.connection.*` (connection state) and `store.lmz.orgTree` (the org/permission tree, delivered on its own channel and mutated via [`client.orgTree.*`](#clientorgtree), never by writing the store). For when to read off `store` vs when to call methods on `client`, see [Coding your UI § `store` vs `client`](./coding-your-ui.md#store-vs-client--what-goes-where).\n\n- **`store.resources.*`** — Synced resource snapshots, written by the framework on every server push. `store.resources.{type}.{id}.value` holds the resource value; `store.resources.{type}.{id}.meta` holds the eTag, change metadata, etc.\n- **`store.lmz.*`** — Other framework-owned state, each on its own dedicated channel: `store.lmz.connection.*` (connection state — see [below](#lmzconnection)), `store.lmz.orgTree` (the org/permission tree — see [OrgTreeState](#orgtreestate)), `store.lmz.profiles[profileId]` (public profiles — see [store.lmz.profiles](#lmzprofiles)), and `store.lmz.querySubscribers.<typeName>.<field>[value]` (a query's live subscriber-list roster — see [store.lmz.querySubscribers](#lmzquerysubscribers)). Future framework-meta paths land under this prefix too.\n\nEvery other top-level segment is yours. Common conventions:\n\n- `store.ui.*` — transient UI state (modal open/closed, form drafts, conflict tracking).\n- `store.app.*` — application-wide local state (active view, current user prefs).\n- Anything else — free.\n\nThe factory pre-seeds `store.ui` and `store.app` as empty objects so first-level access works with no setup. They are conveniences, not reserved — the framework never touches them after seeding. Deeper intermediate objects are app-created (no auto-vivification under non-reserved prefixes).\n\nThe factory's `set` trap routes writes under `store.resources.<rt>.<rid>.value(\\.|$)` to the synced-state middleware. Writes to `store.resources.<rt>.<rid>.meta.*` pass through middleware unchanged (server-owned, intentional) — but those paths are still server-managed in practice; user-code writes to `meta.eTag` will be warned-on in debug builds.\n\n## `store.lmz.connection` {#lmzconnection}\n\n**Tag**: `implemented-in-spike`\n\nThe factory mirrors the underlying `LumenizeClient` connection state to three reserved paths so the UI can bind declaratively without event listeners:\n\n| Path | Type | Description |\n| --- | --- | --- |\n| `store.lmz.connection.state` | `'connecting' \\| 'connected' \\| 'reconnecting' \\| 'disconnected'` | Initialized to `'disconnected'`. Updated on every connection-state transition. |\n| `store.lmz.connection.connected` | `boolean` | Initialized to `false`. `true` iff `state === 'connected'`. |\n| `store.lmz.connection.lastConnectedAt` | `number \\| undefined` | Set on each `'connected'` transition (`Date.now()`). Unset before first connect. |\n\nThe factory writes to these paths on every transition; user code never registers a connection-state listener. The initial seed values are intentional so first-paint reads never return `undefined`.\n\n## `store.lmz.profiles` {#lmzprofiles}\n\n**Tag**: `new-in-v3`\n\nPublic profiles keyed by `profileId`, delivered on a dedicated channel (never `store.resources.*`). **Reading a path auto-subscribes** the profile (refcounted, grace-period-aware, windowed) — the same auto-subscribe as resources.\n\n| Path | Type | Notes |\n| --- | --- | --- |\n| `store.lmz.profiles[profileId].value.name` | `string \\| undefined` | Full name (OIDC). |\n| `store.lmz.profiles[profileId].value.nickname` | `string \\| undefined` | Display / casual name. |\n| `store.lmz.profiles[profileId].value.picture` | `string \\| undefined` | Avatar image URL. |\n| `store.lmz.profiles[profileId].meta.eTag` | `string` | Forward-only version of the profile. |\n\nRead-only through the store. Resolve `profileId`s you already hold — `client.claims.profileId` for the current user, or the ids in a roster. See [`client.subscribeProfile`](#subscribeprofile).\n\n## `store.lmz.querySubscribers` {#lmzquerysubscribers}\n\n**Tag**: `new-in-v3`\n\nThe live subscriber-list roster of a query, delivered on a dedicated channel. **Reading the query-in-path auto-subscribes** the roster (the path segments *are* the [`QueryDescriptor`](#resourcessubscribequery)).\n\n| Path | Type | Notes |\n| --- | --- | --- |\n| `store.lmz.querySubscribers.<typeName>.<field>[value]` | `{ sub: string; profileId?: string }[]` | Distinct-by-person roster of everyone subscribed to that query's data, kept live. `v-for`-ready. |\n\nAdvisory / display-only (carries no permission data). Resolve each entry's `profileId` via [`store.lmz.profiles`](#lmzprofiles), windowed to rendered rows. See [`client.subscribeQuerySubscribers`](#subscribequerysubscribers).\n\nExample — a \"who's here\" roster for a chat session, with each person's avatar + name:\n\n```vue @skip-check\n<template>\n  <li v-for=\"{ sub, profileId } in store.lmz.querySubscribers.Message.session[sessionId].slice(0, 25)\" :key=\"sub\">\n    <img :src=\"store.lmz.profiles[profileId].value.picture\" />\n    <span>{{ store.lmz.profiles[profileId].value.name }}</span>\n  </li>\n</template>\n```\n\n## `client.claims` {#clientclaims}\n\n**Tag**: inherited from `LumenizeClient`\n\nNebulaClient extends [`LumenizeClient`](/docs/mesh/lumenize-client), so `client.claims` (the decoded JWT payload — `sub`, `aud`, `access`, etc.) is available with no Nebula-specific wrapping. See [mesh: LumenizeClient § Client identity](/docs/mesh/lumenize-client#client-identity-clientclaims) for the full surface. Idiomatic Nebula use is per-user keying: `store.resources.todoList[client.claims.sub]`. For admin-only UI, gate on **both** `client.claims.access?.admin` (Galaxy/Universe scope admin) and an `admin` grant in the org-tree (app admin) — see [Coding your UI § Gating admin-only UI](./coding-your-ui.md#gating-admin-only-ui).\n\n**Type — non-null on NebulaClient.** `LumenizeClient` is generic over its claims payload — `LumenizeClient<TClaims extends { sub: string } = JwtPayload>` with `get claims(): Readonly<TClaims> | null` (it has a genuine null window before first refresh). `NebulaClient extends LumenizeClient<NebulaJwtPayload>` and **re-declares the getter to drop the `| null`** — `get claims(): Readonly<NebulaJwtPayload>` — because the availability contract below guarantees it's populated by the time app code runs. The re-declaration is behaviorally neutral (the runtime getter is the inherited one; it only narrows the type). This is what lets the doc examples write `client.claims.sub` without a `!` or `?.` and still pass strict TypeScript.\n\nThe fields app code relies on (full payload is minted by nebula-auth):\n\n```typescript @check-example('packages/nebula-auth/src/types.ts')\nexport interface NebulaJwtPayload {\n  iss: string;\n  aud: string;\n  sub: string;\n  exp: number;\n  iat: number;\n  jti: string;\n  access: AccessEntry;\n  profileId?: string;\n  act?: ActClaim;\n}\n```\n\n`access` carries `authScope` (the scope this token belongs to, verbatim — e.g. `\"george-solopreneur\"` for a Universe-level member) and `scopeAdmin` (`true` for a Galaxy/Universe scope admin, omitted when false). A scope covers itself and every scope beneath it, by whole dot-separated segment. `profileId` is the bearer's own public profile handle; `act` is present only under impersonation.\n\n**Availability contract (pinned).** Under the hood `claims` is `null` until the client's first token refresh completes, and `client` is not Vue-reactive — claims-gated bindings never re-evaluate on their own. Studio-generated apps close this window structurally: the bootstrap top-level-awaits the factory's [`ready`](#createnebulaclient) promise, so **`client.claims` is populated by the time any component renders** — which is exactly what makes the non-null narrowing sound. Code that runs *outside* that contract (admin tools, scripts, anything before `ready`) is the one place the narrowing over-promises: there, treat `claims` as possibly-null and guard with `?.`.\n\n`sub` is a bare UUID minted by nebula-auth — the same string that keys org/permission-tree grants (see [client.orgTree](#clientorgtree)).\n\n## `Snapshot` and `SnapshotMeta` {#snapshot}\n\n**Tag**: `implemented-in-spike` (shape shipped server-side in [`apps/nebula/src/resources.ts`](https://github.com/lumenize/lumenize/blob/main/apps/nebula/src/resources.ts); `mimeType` lands new-in-v3 alongside files-as-resources)\n\nWhat `resources.read` and `resources.subscribe` resolve with, and what every store entry holds: `store.resources.<rt>[<rid>].value` is `Snapshot.value`; `store.resources.<rt>[<rid>].meta` is `Snapshot.meta`.\n\n```typescript @skip-check\ninterface Snapshot {\n  value: unknown;          // structured-clone-capable; shaped by your ontology\n  meta: SnapshotMeta;\n}\n\ninterface SnapshotMeta {\n  eTag: string;        // client-generated UUID; optimistic-concurrency token + idempotency key\n  nodeId?: number;     // org/permission-tree node the resource is attached to (present on every resource snapshot)\n  typeName?: string;   // ontology type name\n  validFrom?: string;  // ISO 8601 — when this snapshot committed server-side\n  deleted?: boolean;   // true for soft-deleted (tombstoned) resources\n  mimeType?: string;   // IETF media type, set where MIME is meaningful (file resources, blobs)\n}\n```\n\n- **User code reads `meta`; only the framework writes it.** Writes to `meta.*` pass through middleware unchanged but are warned-on in debug builds.\n- **Tombstones are real snapshots.** A deleted resource keeps its last `value`; `meta.deleted: true` is the only deletion signal — check it *before* any `value` truthiness test (see [Coding your UI § Loading and first paint](./coding-your-ui.md#loading-and-first-paint)). A `null` from `read` means \"never created\", not \"deleted\".\n- `meta.nodeId` is how UI code attaches new resources next to existing ones — [Coding your UI § Atomic append](./coding-your-ui.md#atomic-append--adding-to-a-collection) creates a todo at the list's `meta.nodeId`.\n- Additional framework-owned fields (`validTo`, `actingToken`, `ontologyVersion`) exist server-side and may appear; treat `meta` as an open, read-only shape.\n\n## `textMerge` {#textmerge}\n\n**Tag**: `new-in-v3`\n\n```typescript @skip-check\nfunction textMerge(server: string, local: string, base: string): string;\n```\n\nThree-way merge helper (LCS-based) for long-form text fields, used inside a `'use-this'` resolver to preserve both the local user's edits and a concurrent server-side commit. Exported from `@lumenize/nebula/frontend`'s top level.\n\n`base` is the **common ancestor** — the value both `local` and `server` diverged from — and it is required for the merge to preserve both sides: pass `resolution.base.value.<field>`, never `resolution.server.value.<field>`. (With `base === server` the server→base diff is empty and the merge collapses to \"local wins,\" silently dropping the concurrent edit.) The `'conflict-pending'` resolution supplies `base` directly (see [TransactionResourceResolution](#transactionresourceresolution)) — your handler just reads `resolution.base.value`. The framework sources it client-side as the value the local edit was based on and keeps it current as that baseline advances (across a clean commit, and across a chained `'use-this'` re-conflict, where `base` becomes the previous conflict's `server` snapshot). It is never a server-side history lookup.\n\n**Auto-registration**: a field annotated [`@longform`](./ontology.md#annotations) gets a text-merge resolver registered for it automatically — most apps never call `textMerge` directly. Call it by hand only for a custom merge inside a hand-written [`onTransactionResourceResolution`](#resourcesontransactionresourceresolution) handler. See [Resources § Text fields specifically — don't leave the default](./resources.md#text-fields-specifically--dont-leave-the-default).\n\n**Limitations**: `textMerge` preserves *non-overlapping* concurrent edits but can garble or drop characters when two edits overlap the same span. Full protection for keystrokes typed *before* a concurrent fanout arrives is provided by the synced-state middleware holding fanouts while a resource has pending optimistic writes (shipped alongside this helper in v3). Conflict-free collaborative editing under arbitrary interleaving needs a CRDT — out of scope for 5.3.7 (see [tasks/archive/nebula-frontend.md § Out of scope](https://github.com/lumenize/lumenize/blob/main/tasks/archive/nebula-frontend.md)). The sibling `setUnion` / `counterMerge` helpers remain deferred-post-5.3.7.\n\n## Handler bindings {#handler-bindings}\n\n**Tag**: `deferred-post-5.3.7`\n\nWhen the handler is called with `'conflict-pending'`, the resolution carries a `context.bindings` field intended to expose the per-field DOM bindings under the conflicting resource, so the handler can trigger custom UX beyond the default flash classes (apply a class to a parent card, fire a JS animation, jump-scroll to the conflict, etc.).\n\n```typescript @skip-check\n// Shape, when the resolution is 'conflict-pending':\ntype ConflictPending = {\n  kind: 'conflict-pending';\n  local:  { value: unknown; eTag: string };\n  server: Snapshot;\n  base:   { value: unknown; eTag: string };\n  context: { bindings: Map<string, HTMLElement[]> };\n};\n```\n\n**Status in 5.3.7**: `context.bindings` is always an empty `Map`; DOM flash + binding discovery are **deferred to v4**. Vue has no element→path map for free, so v4 decides the mechanism — a **compiler-injected flash directive** is the leading candidate (the SFC compile pass we own injects it, so the author writes nothing). Earlier options weighed and not chosen: an author-written `v-flash` directive (authors would later have to remove it — fails the no-churn principle) and a `client.bindings(rt, rid, field)` runtime registry (most code, brittle).\n\nDecision deferred to post-5.3.7. The argument's shape is locked so handler signatures don't churn when it lands.\n\n## `TransactionOutcome` {#transactionoutcome}\n\n**Tag**: `implemented-in-spike` for the `'committed'` happy path (under the old single-level shape); **`new-in-v3`** for the five-kind top-level shape (`'committed'` / `'rejected'` / `'timeout'` / `'infrastructure-error'` / `'ontology-stale'`) and the move of per-resource detail into the handler.\n\n`transaction()` **always resolves** with a `TransactionOutcome` — never rejects. Top-level handles transaction-wide concerns only; per-resource detail is delivered to the per-type [`onTransactionResourceResolution`](#resourcesontransactionresourceresolution) handler (or its per-call override) and is also available on `outcome.resources` for inspection at the await-site.\n\n```typescript @skip-check\ntype ResourceMap = Record<string, TransactionResourceResolution>;\n\n// The await-site's one decision is \"do I resubmit?\" — answered by `retryable`. `kind` says\n// what happened; per-op detail lives in `resources` (committed/rejected only). The union\n// shows which extra fields each kind carries.\ntype TransactionOutcome =\n  // Every op landed (atomicity ⟹ a committed batch committed every op; an op may still\n  // show 'use-server' in `resources` — committed, but the server's value, not yours).\n  | { kind: 'committed';            resources: ResourceMap }\n\n  // The server processed it but nothing committed, for a per-op reason — see `resources`\n  // (permission-denied / validation-failed / conflict-retries-exhausted / human-in-the-loop).\n  // `retryable` is the framework's verdict on whether a blind resubmit can help (an exhausted\n  // conflict → true; a permission/validation failure → false).\n  | { kind: 'rejected';             retryable: boolean; resources: ResourceMap }\n\n  // Transaction-wide failures — no per-op detail.\n  | { kind: 'timeout';              retryable: true }\n  | { kind: 'infrastructure-error'; retryable: true;  error: Error }\n  | { kind: 'ontology-stale';       retryable: false; clientVersion: string; currentVersion: string };\n```\n\nThe discriminant key is `kind` (same as on the per-resource [`TransactionResourceResolution`](#transactionresourceresolution) below). The variable name (`outcome` for transaction-wide, `resolution` for per-resource) carries the level distinction; the discriminant is uniformly `.kind`. (The three-level vocabulary — `TransactionOutcome` / `TransactionResourceResolution` / `ConflictResolverVerdict` — is deliberate over a flatter single type: each names a different altitude, and collapsing them would lose the await-site-vs-handler distinction. One-line anchor in [Resources § Awaiting transaction()](./resources.md#awaiting-transaction-at-the-call-site).)\n\nEffect on the optimistic store, per branch:\n\n| Outcome | Optimistic store | Caller responsibility |\n| --- | --- | --- |\n| `'committed'` | Per-resource — see [`TransactionResourceResolution`](#transactionresourceresolution) (an op may be `'use-server'`: committed, but the server's value). Per-type handler already fired (DOM flash is v4). | Usually nothing; the handler is the primary place. Inspect `outcome.resources` only for aggregate decisions (e.g., did every op commit *your* value, or did some resolve to `'use-server'`). |\n| `'rejected'` | Per-resource, per each op's [`TransactionResourceResolution`](#transactionresourceresolution): `'permission-denied'` / `'validation-failed'` / `'retries-exhausted'` → rolled back; `'human-in-the-loop'` → optimistic paint stays. | `outcome.retryable` is the resubmit verdict (an exhausted conflict → `true`; permission/validation → `false`). Per-op detail in `outcome.resources`: `'permission-denied'` → climb the orgTree to the nearest admin → request-access; `'validation-failed'` → surface per-field errors to fix. |\n| `'timeout'` | Roll back all optimistic writes. No server response within 5–10 s **while connected**. **Connection-gated** — a mere disconnect never produces it. | `retryable: true` — an idempotent resubmit (same `newETag`) can land. |\n| `'infrastructure-error'` | Roll back all optimistic writes. **Connection-gated.** `error` carries the underlying `Error` (network drop, mesh crash). | `retryable: true` — resubmit (idempotent) or surface to user. |\n| `'ontology-stale'` | Optimistic state untouched. The `onShouldRefreshUI` hook fires (typically reloads). | Usually nothing; page reload handles it. |\n\nThe `'timeout'` and `'infrastructure-error'` outcomes fire only for failures that occur **while the client is connected**. A plain disconnect does *not* produce them: the write path suspends while `store.lmz.connection.connected` is `false` — writes are held and re-submitted on reconnect (idempotent via `newETag`) — so a transient blip never rolls anything back. That is what makes the \"your changes are queued\" disconnected banner honest. (Held writes live in memory only; a full page reload while offline drops anything unsent.)\n\n## `TransactionResourceResolution` {#transactionresourceresolution}\n\n**Tag**: `new-in-v3` (replaces the shipped flat `TransactionResolution` shape).\n\nWhat the per-type handler receives for each resource in a transaction. The handler fires once per resource per transaction for terminal branches; for the non-terminal `'conflict-pending'` branch, it may fire multiple times across a `'use-this'` chain before the resource reaches a terminal resolution.\n\n```typescript @skip-check\ntype TransactionResourceResolution =\n  // Non-terminal — handler MAY return a ConflictResolverVerdict to drive the chain.\n  // Undefined return falls through to the framework default ({ kind: 'use-server' }).\n  | {\n      kind: 'conflict-pending';\n      local:  { value: unknown; eTag: string };   // your in-flight edit + the baseline it was based on\n      server: Snapshot;                            // the conflicting committed version\n      base:   { value: unknown; eTag: string };    // common ancestor — the value `local` diverged from (see below)\n      context: { bindings: Map<string, HTMLElement[]> };  // deferred-post-5.3.7; empty Map in 5.3.7\n    }\n\n  // Terminal — handler return is ignored.\n  | { kind: 'committed';         eTag: string }\n  | { kind: 'use-server';        snapshot: Snapshot }\n  | { kind: 'human-in-the-loop'; snapshot: Snapshot }\n  | { kind: 'retries-exhausted'; snapshot: Snapshot; attempts: number }\n  | { kind: 'validation-failed'; errors: unknown }\n  | { kind: 'permission-denied' };\n```\n\nEffect on the optimistic store, per branch:\n\n| Resolution | Optimistic state for that resource | Notes |\n| --- | --- | --- |\n| `'conflict-pending'` | Optimistic state unchanged from pre-resolution. Handler is deciding. | Handler returns a [`ConflictResolverVerdict`](#conflictresolververdict) to drive the next step. |\n| `'committed'` | `meta.eTag` updated to the new value. Framework adds default `lumenize-commit-success` flash class. | The user's write landed. |\n| `'use-server'` | Server's `value` + `meta` already written through. Framework adds default `lumenize-conflict-revert` flash class at diff fields. | The user's write was reverted to the server's authoritative value. |\n| `'human-in-the-loop'` | Optimistic stays painted; no flash class. | App owns the eventual resolution submission (typically a \"review later\" UI). |\n| `'retries-exhausted'` | Roll back to the B4 baseline (the value at the eTag the failed submission asserted; for a `use-this` chain, the last conflict's server snapshot). Framework adds default `lumenize-conflict-revert` flash. `snapshot` is the latest server snapshot; `attempts` is how many `'use-this'` re-submits ran. | Surface to user. |\n| `'validation-failed'` | Roll back to the B4 baseline (the value at the eTag the failed submission asserted; for a `use-this` chain, the last conflict's server snapshot). Framework adds default `lumenize-conflict-revert` flash. `errors` carries the server's per-field messages. | Surface validation messages. |\n| `'permission-denied'` | Roll back to the B4 baseline (the value at the eTag the failed submission asserted; for a `use-this` chain, the last conflict's server snapshot). Framework adds default `lumenize-conflict-revert` flash. | Surface \"not authorized\" message. |\n\nThe `'use-this'` verdict from the handler is intermediate — never appears as a `TransactionResourceResolution` branch — it triggers a recursive re-submission with the handler-returned value at the server's current eTag. A successful chain terminates in `'committed'`; a failed one terminates in `'retries-exhausted'`.\n\n**Atomicity invariant**: the server is atomic (all-or-nothing), so there is no mixed top-level outcome. A transaction's top-level [`TransactionOutcome`](#transactionoutcome) is `'committed'` whenever every op landed — even when a resource lands at `'use-server'` (the server's value won and the user's original `value` didn't, but the data is consistent and the op committed) — and `'rejected'` when an op failed for a per-op reason (`'permission-denied'` / `'validation-failed'` / `'human-in-the-loop'` / `'retries-exhausted'`). The per-resource breakdown in `resources` reveals each resource's final state.\n\n## `ConflictResolverVerdict` {#conflictresolververdict}\n\n**Tag**: `implemented-in-spike` for the shape (under the old name `ConflictResolution`); renamed to disambiguate from `TransactionResourceResolution`.\n\nWhat the handler returns from the `'conflict-pending'` branch.\n\n```typescript @skip-check\ntype ConflictResolverVerdict =\n  | { kind: 'use-server' }\n  | { kind: 'use-this'; value: unknown }\n  | { kind: 'human-in-the-loop' };\n```\n\n- `'use-server'` — accept the server's value, abandon local changes for this resource.\n- `'use-this'` — re-submit with `value` and the server's new `eTag`. The verdict `value` is also painted optimistically (it's a fresh optimistic write at the server baseline — the merged text is visible while the re-submission is in flight and stays painted when it commits). Bounded by `maxRetries` — on cap, the resource lands at `'retries-exhausted'`.\n- `'human-in-the-loop'` — defer to the user. Optimistic state stays painted; the handler (or app code outside it) is responsible for any follow-up `transaction()`.\n\nThe handler can be sync or async. The in-flight queue's 5–10 s timeout is **suspended** during handler execution at `'conflict-pending'` — a modal can sit open for minutes without triggering `'timeout'`.\n\nReturning `undefined` (or omitting the return) from `'conflict-pending'` falls through to the framework default `{ kind: 'use-server' }`. The handler is required for nothing — without one, the framework still applies sensible defaults (server-wins on conflict, default flash classes on every outcome).\n\nFor details on `context.bindings`, see [Handler bindings](#handler-bindings).\n\n## Internal mechanics\n\nThe following surfaces are not user-facing API but are listed for completeness — they show up in error messages, debug builds, and source spelunking.\n\n### Middleware\n\n```typescript @skip-check\ntype Middleware = (args: {\n  path: string;\n  oldValue: unknown;\n  newValue: unknown;\n  context: WriteContext;\n}) => unknown;\n\ntype WriteContext = { source: 'local' | 'remote' | 'rollback' | 'computed' };\n```\n\nFires on every write through the Proxy `set` trap — and on intercepted collection-mutator calls (`Map.set/delete/clear`, `Set.add/delete/clear`) on values under `store.resources.*.value`, which run the identical middleware chain as property assignments (see [tasks/archive/factory-collection-sync.md](https://github.com/lumenize/lumenize/blob/main/tasks/archive/factory-collection-sync.md)). For a mutator-driven invocation: `path` is the owning collection's path (e.g. `resources.todo.t1.value.tags`), `oldValue` is a pre-mutation snapshot of the collection, and `newValue` is the post-mutation value; returning a substitute collection applies it in place of the mutation. No-op mutations (`add` of an existing element, `set` to a deep-equal value, `delete` of an absent key, `clear` on empty) skip the chain entirely — parity with the `set` trap's deep-equal dedup. Return a value to substitute for `newValue`; return `undefined` to leave `newValue` unchanged; throw to abort the write entirely.\n\n`context.source` discriminates origin:\n\n- `'local'` — user-driven write (v-model, direct assignment). Synced-state middleware processes these.\n- `'remote'` — server fanout. Synced-state middleware skips.\n- `'rollback'` — framework restoring a pre-write value after a failed transaction. Synced-state middleware skips.\n- `'computed'` — framework vivifying intermediate containers under `store.resources.*` so descendant access works before snapshot arrival. Synced-state middleware skips.\n\nRegister additional middleware via `use()` from the factory return. Synced-state middleware is always-on and runs LAST, after the user chain: a user middleware abort (throw) therefore also aborts the submission, and synced-state sees the final post-substitution value.\n\n**Contract**: a middleware MUST NOT write to its own path inside its callback (would re-enter the `set` trap). Cross-path writes from inside a middleware ARE allowed and fire their own middleware chains.\n",
  ".platform/docs/auth-flows.md": "---\ntitle: Auth flows\ndescription: Login, token management, and scope switching sequences for Nebula.\n---\n\n# Auth flows\n\nNebula uses [nebula-auth](/docs/auth) for passwordless authentication with a two-scope model: **auth scope** (determines the refresh cookie path) and **active scope** (baked into the JWT `aud` claim). This page shows the end-to-end sequences from the UI perspective.\n\n:::info[Where the pieces live]\n\nThere is **no per-scope auth DO**. Identity and all durable auth state live in one **singleton Registry DO** (the identity authority + single writer); the login/token flows (`email-magic-link`, `magic-link`, `accept-invite`, `refresh-token`, `logout`, `invite`, `mint-narrower-token`) run in the **default Worker** (`routeNebulaAuthRequest`); and the refresh record lives in **Workers KV** (`refresh:{tokenHash}`), read at the edge on refresh with **no Registry round-trip**. Identity is keyed by a registry-minted surrogate **`sub`** (never the email). Diagrams reference `NebulaClient`, the client-side class that manages connections.\n\n:::\n\n## Cross-origin browser deploys\n\nBy default Nebula serves the UI and the API from the same origin (e.g. `https://lumenize.com`), so no [CORS](/docs/routing/cors-support) configuration is required. For deployments where the browser app and the Nebula worker live on different origins — custom-domain deploys (`https://apps.acme.com` calling `https://nebula.lumenize.com`), real-browser test rigs hitting a miniflare worker on a different localhost port, etc. — set the `LUMENIZE_APPROVED_ORIGINS` env binding in `wrangler.jsonc` (`vars`) to a comma-separated allowlist:\n\n```jsonc\n\"vars\": {\n  \"LUMENIZE_APPROVED_ORIGINS\": \"https://apps.acme.com,https://admin.acme.com\"\n}\n```\n\nThe Nebula entrypoint parses this once and threads it as a single `cors` config through both the `/auth/*` router (`routeNebulaAuthRequest`) and the `/gateway/*` router (`routeDORequest`), so a browser frontend at an approved origin can hit both magic-link / refresh-token endpoints and the WebSocket mesh with the same allowlist. Empty or unset → no CORS headers (safe default).\n\n## Who can create a scope (identity is minted only at mint points)\n\nLogin **never mints** a membership. A magic-link login *verifies* an already-existing one — recording that the mailbox is proved and that this membership has been taken up — and is **rejected** if none exists — this is what closes stranger-self-join. Memberships are minted only at mint points:\n\n- **Universe** — open self-signup: `claim-universe` mints the claiming admin identity (`scopeAdmin=true`) + the scope.\n- **Galaxy / Star** — the parent-scope admin creates the child (`create-galaxy` / `create-star`, admin-gated); the child is **parent-managed** (no local admin stamped — the parent admin's own scope is at or above it, so their token reaches it). There is no open, identity-minting star self-signup.\n- **Invite** — an admin invites an email into an existing scope; issuance pre-creates the invitee's membership (`scopeAdmin=false`, not yet taken up), and `accept-invite` records the take-up. Proving the mailbox is a property of the **address**, so someone who already proved it in another scope does not re-prove it here — only the new membership's take-up is recorded.\n\n## First-time login (self-signup — founding a Universe)\n\nA new user arrives with no existing refresh cookie and no identity yet. Discovery returns nothing, so they found a Universe (`claim-universe`), which mints the claiming admin identity and emails a magic link; clicking it issues the refresh cookie.\n\n```mermaid\nsequenceDiagram\n    participant UI as Login Page\n    participant NC as NebulaClient\n    participant W as Auth Worker\n    participant R as Registry DO\n    participant KV as Workers KV\n    participant GW as Gateway DO\n\n    rect rgba(220, 220, 255, 0.3)\n        Note over UI,R: 1. Name the account — MINTS the claiming admin identity\n        Note over UI: Nothing is asked about the address first\n        UI->>W: POST /auth/claim-universe { slug, email, cf-turnstile-response }\n        W->>R: claimUniverse(slug, email)\n        Note over R: register Scope + mint admin membership<br/>(scopeAdmin, NOT yet taken up) + create MagicLink\n        R-->>W: send magic-link email\n        W-->>UI: Show \"Check your email\"\n    end\n\n    rect rgba(240, 220, 200, 0.3)\n        Note over UI,KV: 2. Click the link — prove the mailbox, place the session\n        UI->>W: GET /auth/{slug}/magic-link?one_time_token=...\n        W->>R: resolveConsume(kind, tokenHash)\n        Note over R: prove the mailbox once, globally<br/>return EVERY membership this address holds\n        R-->>W: plan (memberships, link scope)\n        W->>R: recordSessions(hashes, expiresAt)\n        R->>KV: put refresh:{tokenHash} per membership\n        W-->>UI: one Set-Cookie per membership + 302 to /auth/{slug}/home\n    end\n\n    rect rgba(255, 235, 200, 0.3)\n        Note over UI,R: 3. Consent — the cookie is INERT until this\n        Note over UI: Home renders the self-signup modal:<br/>\"Only accept if you initiated this signup\" + the data-use notice\n        UI->>W: POST /auth/{slug}/pending-membership\n        W-->>UI: the modal's inputs (no access token exists yet)\n        UI->>W: POST /auth/{slug}/accept-membership\n        W->>R: acceptMembership(sub)\n        Note over R: stamp acceptedAt + converge the KV record\n        W-->>UI: accepted\n    end\n\n    rect rgba(200, 240, 200, 0.3)\n        Note over UI,GW: 4. Get access token and connect\n        UI->>W: POST /auth/{slug}/refresh-token { activeScope: \"{slug}\" }\n        W->>KV: get refresh:{tokenHash}\n        KV-->>W: { sub, scope, scopeAdmin, expiresAt }\n        Note over W: mint JWT (aud = activeScope, access from the KV record)<br/>NO Registry round-trip\n        W-->>UI: Access token (stored in memory)\n        Note over NC: NebulaClient created with access token\n        NC->>W: WebSocket upgrade (token in subprotocol)\n        W->>W: onBeforeConnect: verify JWT signature + aud\n        W->>GW: Forward to Gateway\n        GW-->>NC: WebSocket connected\n        Note over NC: Ready — lmz.call() works\n    end\n```\n\n:::note[Joining an existing scope]\n\nAn invited user follows the same shape but via `GET /auth/{scope}/accept-invite?invite_token=...` — the invite (single-use) is consumed, the mailbox is proved, and the same inert cookie is issued. They land on the same Home screen, where the modal names who invited them rather than warning them off. `email-magic-link` never creates membership; it proves an address and hands back whatever that address already holds.\n\n:::\n\n## Returning user\n\nA user with a valid refresh cookie (not expired, not revoked) returns to the app. The cookie is `HttpOnly`, so the client can't check for it — it makes the refresh call and lets the browser send the cookie if the path matches.\n\n```mermaid\nsequenceDiagram\n    participant UI as Login Page\n    participant NC as NebulaClient\n    participant W as Auth Worker\n    participant R as Registry DO\n    participant KV as Workers KV\n    participant GW as Gateway DO\n\n    rect rgba(200, 220, 240, 0.3)\n        Note over UI,R: 1. Pick where to go — AFTER the session exists\n        Note over UI: The cookie is already in the browser, so no email is needed\n        UI->>W: POST /auth/{scope}/refresh-token (bootstrap)\n        UI->>W: POST /auth/scope-summary (Bearer)\n        W->>R: getScopeSummary(profileId, sub)\n        R-->>W: every address on this identity + the tree beneath each\n        W-->>UI: the Home tree\n        Note over UI: User picks an account, app or tenant\n    end\n\n    rect rgba(200, 240, 200, 0.3)\n        Note over UI,GW: 2. Refresh succeeds — cookie exists and path matches\n        UI->>W: POST /auth/acme.app.tenant-a/refresh-token<br/>{ activeScope: \"acme.app.tenant-a\" }\n        W->>KV: get refresh:{tokenHash} (browser sent the path-matched cookie)\n        KV-->>W: { sub, scope, scopeAdmin, expiresAt }\n        Note over W: mint JWT (aud: \"acme.app.tenant-a\")\n        W-->>UI: Access token (stored in memory)\n        Note over NC: NebulaClient created with access token\n        NC->>W: WebSocket upgrade (token in subprotocol)\n        W->>W: onBeforeConnect: verify JWT signature + aud\n        W->>GW: Forward to Gateway\n        GW-->>NC: WebSocket connected\n        Note over NC: Ready — lmz.call() works\n    end\n```\n\n:::tip[Bookmarked URLs]\n\nIf the user arrives via a bookmarked URL that encodes the scope (e.g. `https://app.example.com/acme/app/tenant-a/dashboard`), the client already knows the active scope. It can skip discovery and try refresh directly, falling back to a re-login (`email-magic-link`, since the identity already exists) only if refresh fails.\n\n:::\n\n:::note[Refresh is a pure KV read]\n\nThe refresh token gets a fixed 30-day TTL at login — there is no per-refresh rotation and no slide, so `refresh-token` is a pure Workers-KV read plus a JWT mint, with **zero writes** and the Registry never on the path. (Defensive fallback: on a rare KV read-your-write miss, the Worker falls back once to the Registry's strongly-consistent index, which reconstructs and self-heals the KV record.) `logout` deletes the KV record + its index entry; because KV is eventually consistent, revocation propagates within the KV window plus the short access-token TTL.\n\n:::\n\n## Scope switching\n\nAn admin (or any user with access to multiple scopes) wants to switch from one star to another. Scope switching is a **full re-login, not an in-place reconnect** — the old `NebulaClient` is destroyed and a new one is created. This section's diagram covers **separately-held** scopes (each with its own path-scoped cookie); an admin switching within their own subtree uses the lighter flow in [Admin active-scope switching](#admin-active-scope-switching-within-one-scopes-subtree) below.\n\nThe key insight: `NebulaClient` is ephemeral; the refresh cookie is the durable credential. Each access token has a single `aud` (active scope), so switching scope requires a new token.\n\n```mermaid\nsequenceDiagram\n    participant UI as Login Page\n    participant NC1 as NebulaClient (old)\n    participant NC2 as NebulaClient (new)\n    participant W as Auth Worker\n    participant KV as Workers KV\n    participant GW as Gateway DO\n\n    Note over NC1: Currently connected to<br/>acme.app.tenant-a<br/>(aud: \"acme.app.tenant-a\")\n\n    rect rgba(200, 220, 240, 0.3)\n        Note over UI,W: 1. User opens Home and picks a different tenant\n        UI->>W: POST /auth/scope-summary (Bearer, person-scoped)\n        W-->>UI: every address on this identity + the tree beneath each\n        Note over UI: User selects \"acme.app.tenant-b\"<br/>(can back out here — old client stays alive)\n    end\n\n    rect rgba(240, 220, 200, 0.3)\n        Note over UI,KV: 2. Login flow for new scope\n        UI->>W: POST /auth/acme.app.tenant-b/refresh-token<br/>{ activeScope: \"acme.app.tenant-b\" }\n        W->>KV: get refresh:{tokenHash} (path-matched cookie)\n        KV-->>W: record\n        Note over W: mint JWT (aud: \"acme.app.tenant-b\")\n        W-->>UI: New access token\n    end\n\n    rect rgba(255, 220, 220, 0.3)\n        Note over UI,NC1: 3. Destroy old client\n        UI->>NC1: destroy()\n        Note over NC1: WebSocket closed, state discarded\n    end\n\n    rect rgba(200, 240, 200, 0.3)\n        Note over UI,GW: 4. Create new client and connect\n        Note over NC2: NebulaClient created with new access token\n        NC2->>W: WebSocket upgrade (new token in subprotocol)\n        W->>W: onBeforeConnect: verify JWT (aud: \"acme.app.tenant-b\")\n        W->>GW: Forward to new Gateway instance\n        GW-->>NC2: WebSocket connected\n        Note over NC2: onSubscriptionRequired fires<br/>set up subscriptions for tenant-b\n    end\n```\n\n:::note[When refresh fails]\n\nIf the refresh call returns 401 (cookie expired or doesn't exist for the new scope's path), the flow falls back to `email-magic-link` re-login (the identity already exists → find-and-flip). The old client stays alive until the login completes.\n\n:::\n\n### Admin active-scope switching (within one scope's subtree)\n\nA **Galaxy or Universe admin** holds a single membership covering the parent scope *and every scope beneath it*, so switching the active scope needs neither discovery nor a new cookie — only a refresh with a different `activeScope`.\n\nAn admin logged in at the Galaxy `acme.app`:\n\n- holds **one** refresh cookie, path-scoped to `/auth/acme.app`;\n- has `authScope` `acme.app` — the Galaxy itself — which is at or above the Galaxy **and** every Star under it.\n\nEvery switch is the *same* request — `POST /auth/acme.app/refresh-token`, **same cookie** — varying only the body's `activeScope`. The Worker validates the requested `activeScope` against **the KV record's own scope** (server-trusted), never the request path or body:\n\n| Goal | `activeScope` | at or below `acme.app`? |\n| --- | --- | --- |\n| Work directly in the Galaxy (Studio) | `acme.app` | ✓ (a scope is at or below itself) |\n| Activate a child Star | `acme.app.tenant-a` | ✓ |\n| Switch to a different child Star | `acme.app.tenant-b` | ✓ |\n| Return to the Galaxy | `acme.app` | ✓ |\n\nThe admin's **`authScope` never changes** (the cookie stays at `/auth/acme.app`); only **`activeScope`** (the JWT `aud`) moves. Each new `aud` is a new token, so the old `NebulaClient` is destroyed and a new one created — but there is **no magic link and no discovery**: the admin's cookie already authorizes the whole subtree. (A Universe admin is the same one tier up: cookie at `/auth/acme`, `authScope` `acme`, reaching any Galaxy or Star beneath.)\n\n```mermaid\nsequenceDiagram\n    participant UI as Studio (scope picker)\n    participant NC1 as NebulaClient (Galaxy)\n    participant NC2 as NebulaClient (Star)\n    participant W as Auth Worker\n    participant KV as Workers KV\n\n    Note over NC1: Connected to acme.app<br/>(aud: \"acme.app\")\n\n    Note over UI: Admin picks Star \"tenant-a\"\n    UI->>W: POST /auth/acme.app/refresh-token<br/>{ activeScope: \"acme.app.tenant-a\" }\n    W->>KV: get refresh:{tokenHash} (same cookie, path /auth/acme.app)\n    KV-->>W: record (scope = acme.app)\n    Note over W: record scope = \"acme.app\"<br/>isAtOrAbove(\"acme.app\", \"acme.app.tenant-a\") ✓\n    W-->>UI: { access_token } (aud: \"acme.app.tenant-a\")\n    UI->>NC1: destroy()\n    Note over NC2: new client, aud = tenant-a\n    Note over UI: \"Return to Galaxy\" / pick another Star<br/>= same call, activeScope = acme.app / tenant-b\n```\n\n**UI shape (Studio).** A Galaxy admin sees a scope picker showing the current active scope plus the selectable children (the Stars under the Galaxy, with a \"Galaxy (Studio)\" entry to return to the parent). Selecting one re-creates the client at that `aud`. Most of the time the admin works directly in the Galaxy, where Studio lives; activating a Star is for inspecting or operating inside a tenant's data.\n\n:::note[Switching scope ≠ acting as another user]\n\nActivating a Star gives the admin a token whose **`aud`** is that Star, but the **`sub` stays the admin's own** — actions are attributed to the admin, with their admin rights cascading. Impersonating another user (carrying a different `sub`) is a **separate** mechanism — the admin-only `mint-narrower-token` endpoint, which takes `{ subOfNarrowerToken, activeScope }` and mints a token whose `sub` is that person and whose `act.sub` is the caller — not active-scope switching.\n\n:::\n\n## Security layers during connection\n\nEvery `NebulaClient` connection passes through four security layers before any `lmz.call()` reaches a Nebula DO. This diagram shows what happens at each layer for a single connection attempt. (These are the mesh **connection** layers, independent of the token flow above.)\n\n```mermaid\nsequenceDiagram\n    participant C as NebulaClient\n    participant EP as Entrypoint<br/>(onBeforeConnect)\n    participant GW as NebulaClientGateway<br/>(onBeforeAccept)\n    participant DO as NebulaDO<br/>(onBeforeCall)\n    participant M as mesh guard<br/>(e.g. requireDominionHere)\n\n    rect rgba(200, 220, 240, 0.3)\n        Note over C,EP: Layer 1 — Entrypoint JWT verification\n        C->>EP: WebSocket upgrade<br/>(JWT in subprotocol)\n        Note over EP: extractWebSocketToken(request)<br/>verifyJwt(token, publicKey)<br/>isAtOrAbove(authScope, aud)\n        alt Invalid JWT or scope mismatch\n            EP-->>C: 401/403 (no DO instantiated)\n        end\n    end\n\n    rect rgba(220, 220, 255, 0.3)\n        Note over EP,GW: Layer 2 — Gateway star-scoping\n        EP->>GW: Forward WebSocket\n        Note over GW: onBeforeAccept:<br/>read aud into universeGalaxyStarId<br/>store in GatewayConnectionInfo.claims\n        GW-->>C: WebSocket accepted\n    end\n\n    Note over C: Connection established. Now lmz.call() happens:\n\n    rect rgba(240, 220, 200, 0.3)\n        Note over C,DO: Layer 3 — NebulaDO starId binding\n        C->>GW: lmz.call(orgDO, 'addToAllowlist', sub)\n        Note over GW: onBeforeCallToMesh:<br/>stamp universeGalaxyStarId onto callContext\n        GW->>DO: RPC with NebulaCallContext\n        Note over DO: onBeforeCall:<br/>first call stores starId<br/>subsequent verify starId match\n        alt StarId mismatch\n            DO-->>GW: Error: Star scope mismatch\n            GW-->>C: Error propagated\n        end\n    end\n\n    rect rgba(200, 240, 200, 0.3)\n        Note over DO,M: Layer 4 — Method-level guard\n        Note over M: requireDominionHere(instance):<br/>check originAuth.claims.access.scopeAdmin\n        alt Guard rejects\n            M-->>DO: Error: Admin access required\n            DO-->>GW: Error propagated\n            GW-->>C: Error propagated\n        else Guard passes\n            Note over DO: Execute method\n            DO-->>GW: Result\n            GW-->>C: Result\n        end\n    end\n```\n\n## Multi-tab (Coach Carol scenario)\n\nCoach Carol manages multiple client organizations. She opens each in a separate browser tab. Path-scoped refresh cookies let tabs coexist without interfering — and because refresh is a keyed Workers-KV read (one record per refresh token), there is no per-scope DO for the tabs to contend on.\n\n```mermaid\nsequenceDiagram\n    participant T1 as Tab 1<br/>(acme.crm.acme-corp)\n    participant T2 as Tab 2<br/>(bigco.hr.bigco-hq)\n    participant W as Auth Worker\n    participant KV as Workers KV\n\n    rect rgba(200, 220, 240, 0.3)\n        Note over T1,KV: Tab 1 — login to acme.crm.acme-corp\n        T1->>W: POST /auth/acme.crm.acme-corp/refresh-token<br/>{ activeScope: \"acme.crm.acme-corp\" }\n        Note over W: Browser sends cookie scoped to<br/>/auth/acme.crm.acme-corp\n        W->>KV: get refresh:{tokenHash-1}\n        KV-->>W: record\n        W-->>T1: { access_token } (aud: \"acme.crm.acme-corp\")<br/>NebulaClient connects\n    end\n\n    rect rgba(220, 220, 255, 0.3)\n        Note over T2,KV: Tab 2 — login to bigco.hr.bigco-hq\n        T2->>W: POST /auth/bigco.hr.bigco-hq/refresh-token<br/>{ activeScope: \"bigco.hr.bigco-hq\" }\n        Note over W: Browser sends cookie scoped to<br/>/auth/bigco.hr.bigco-hq\n        W->>KV: get refresh:{tokenHash-2}\n        KV-->>W: record\n        W-->>T2: { access_token } (aud: \"bigco.hr.bigco-hq\")<br/>NebulaClient connects\n    end\n\n    Note over T1,T2: Both tabs active simultaneously.<br/>Each has its own access token (in memory),<br/>own WebSocket, own Gateway instance.<br/>Path-scoped cookies + per-token KV records don't interfere.\n```\n\nKey properties:\n- **Shared cookie jar** — both tabs are same-origin, so refresh cookies coexist (different paths)\n- **Independent access tokens** — stored in memory per tab, not shared\n- **Independent WebSockets** — each `NebulaClient` has its own Gateway connection\n- **No cross-talk** — updates arrive only on the correct tab's connection\n",
  ".platform/docs/coding-your-ui.md": "---\ntitle: Coding your UI\ndescription: How to build a Nebula front end with Vue 3 SFCs and TypeScript — store reads and writes, auto-subscribe, conflict resolution, recursive components.\n---\n\n# Coding your UI\n\nA Nebula front end is Vue 3 Single-File Components (SFCs) written in TypeScript, styled with DaisyUI, rendering resources whose shape you defined in your ontology (a TypeScript `.d.ts`-style file). The framework handles subscribes, transactions, and conflicts.\n\nThis page is the narrative reference Nebula Studio's hosted LLM consults when generating UI code in dialog with a user-developer — naming, defaults, and example shape are tuned for that LLM-as-reader audience. For exact signatures see [API reference](./api-reference.md). For the resource data model (addressing, eTags, transactions, conflict resolution) see [Resources](./resources.md). This page is \"how to wire it together\"; those pages are the contract.\n\n## Resources at a glance\n\n**Resources are the heart of this system. They are both simple and powerful. You use them when developing your app on the Nebula platform. Your users indirectly use them when they interact with your app because they are the only place you have to store user data.**\n\nResources also handle [**access control**](./access-control.md). Every resource is attached at create time (movable later) to a node in your app's **org/permission tree**. Each node carries a per-user permissions table. A permission grant on a node flows down to every descendant.\n\nEach resource is a JavaScript object (not just JSON, but rather rich types like Map, Date, cycles, etc.) addressed by a `(resourceType, resourceId)` pair, with its shape declared in your ontology. From your UI's perspective:\n\n- `store.resources.<resourceType>[<resourceId>].value` — the resource's current value.\n- `store.resources.<resourceType>[<resourceId>].meta` — server-managed metadata (`eTag`, change metadata, etc.).\n\nThe full resource model — addressing, optimistic concurrency, the per-type handler, transaction outcomes — is documented in [Resources](./resources.md), but other than shown in the examples in this document, you will rarely have to deal with them directly.\n\n## Building your UI on top of Resources\n\nResources reside in the cloud. The UI in your user's web browser must access and manipulate them. This occurs in three layers:\n\n1. **`NebulaClient`** — the WebSocket connection between your browser and the back end as well as authentication flows.\n2. **The store** — a Vue-reactive Proxy that your `v-*` directives bind to. Reads under `store.resources.*` auto-subscribe to the resources they touch; writes flow through optimistic apply + debounced server submission. The whole reactive UI surface lives here.\n3. **Vue 3** — `.vue` files with `<script setup lang=\"ts\">`, `<template>`, and optional `<style scoped>`. Studio compiles them to render-function modules on every save (to a nearby dev server during development iteration; to your Galaxy when you are ready to deploy it to production). \n\nStudio auto-populates the bootstrap (a `nebula.ts` that calls `createNebulaClient()`, top-level-awaits the factory's `ready` promise, and exports `{ client, store, ready }`, plus a Vue entrypoint and an `index.html` shell). Because the bootstrap awaits `ready`, the app mounts only after the first connection completes — see [Current user](#current-user-clientclaims) for what that guarantees. Your `.vue` components import `{ store, client } from './nebula'` and define the UI. The full `createNebulaClient` config is at [API reference § createNebulaClient](./api-reference.md#createnebulaclient).\n\n## `store` vs `client` — what goes where\n\n`store` holds everything reactive — synced resources, your own UI state, and connection status mirrored from the client (`store.lmz.connection.*`). `client` is the underlying connection: method calls (`client.resources.transaction`, `client.resources.subscribe`, `client.dispose`, etc.) and non-reactive identity like `client.claims`. The prefix on every path expression in this doc is load-bearing — `store.X` is something to bind to, `client.X` is something to call or look up.\n\n## Reading and writing through the store\n\nRead and write the store inline in templates using stock [Vue 3](https://vuejs.org/) syntax. Auto-subscribe on read and debounced server submission on write are invisible. No Nebula-specific directives or modifiers.\n\n```html @skip-check\n<!-- The `?.` guards against the snapshot not having arrived yet. Auto-subscribes on first read. -->\n<h2>{{ store.resources.todo[id]?.value?.title ?? 'Loading…' }}</h2>\n\n<!-- :class object syntax (shorthand for v-bind:class) toggles a class on a reactive value. -->\n<li :class=\"{ 'line-through': store.resources.todo[id]?.value?.status === 'done' }\">\n  <!-- v-model: each keystroke optimistically updates the store and queues a debounced\n       transaction. The v-if guard is required — see \"v-model requires a real writable path\" below. -->\n  <template v-if=\"store.resources.todo[id]?.value\">\n    <input v-model=\"store.resources.todo[id].value.title\" />\n  </template>\n</li>\n\n<span v-if=\"store.resources.todo[id]?.value?.status === 'done'\" class=\"badge badge-success\">Done</span>\n<span v-else class=\"badge\">Open</span>\n```\n\nThe same paths work from TypeScript — inside a `computed`, a method, or an event handler. `value` is typed loosely on the store; when script code needs typing, cast it to the ontology type at the read site:\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nconst title = store.resources.todo[id]?.value?.title;          // reactive read\nstore.resources.todo[id].value.title = 'New title';            // optimistic write + debounced transaction\nconst todo = store.resources.todo[id]?.value as Todo | undefined;  // cast to the ontology type for typed script code\n```\n\nFor multi-resource atomic batches, explicit conflict-resolution handlers, programmatic subscriptions, and other operations that don't fit \"read or write a single field,\" use the underlying `client` directly — the canonical case is [Forms: explicit save](#forms-explicit-save) below.\n\n### `v-model` requires a real writable path\n\nOptional chaining (`?.`) isn't allowed in a `v-model` expression. Guard the input with `v-if` so it only mounts after the resource value is synchronized into the store:\n\n```html @skip-check\n<template v-if=\"store.resources.todo[id]?.value\">\n  <input v-model=\"store.resources.todo[id].value.title\" />\n</template>\n<span v-else>Loading…</span>\n```\n\n## Write timing\n\nBy default `v-model` listens on `input` (fires every keystroke). The optimistic local update is immediate; the network transaction is **debounced** by the synced-state middleware so per-keystroke `v-model` doesn't pile up server traffic. The middleware coalesces transaction submissions per `(resourceType, resourceId)`:\n\n- **Quiet window**: wait this long after the last write to a resource before submitting (default 500 ms).\n- **Max wait**: submit at least every N ms regardless of continued typing (default 2000 ms).\n- **Flush on lifecycle**: a pending write flushes immediately on input blur (a `focusout` on the bound input) and on `client.dispose()`. Component unmount does *not* itself force a flush — but the quiet/max-wait timers above run at the client level (per `(resourceType, resourceId)`, not per component), so a buffered write still submits on schedule after the component is gone; nothing is lost.\n- **Serial per resource**: at most one transaction in flight per resource; subsequent writes buffer and submit using the in-flight transaction's resulting eTag.\n\nA typical 10-character edit produces ~1 transaction, not 10.\n\n**Write timing and conflict handling have type-derived defaults** — booleans and enums commit immediately, long-form text gets slower debounce plus an auto-registered text-merge resolver, short text uses the 500/2000 ms windows above. The full table and how to override it (`@debounce`, `@longform`) is the canonical reference in [Ontology § Annotations](./ontology.md#annotations). For runtime overrides (rare — A/B testing, dynamic config), `client.resources.transactionDebounce(rt, opts)` is available; see [API reference § resources.transactionDebounce](./api-reference.md#resourcestransactiondebounce).\n\n### `v-model.lazy` — commit on blur\n\n```html @skip-check\n<!-- Listen on `change` instead of `input`: text input fires on blur, select on\n     commit. Use when \"I'm done editing this field\" matches better than\n     \"live update on every keystroke.\" Same v-if guard as any v-model binding\n     (see \"Loading and first paint\"): value must exist before binding. -->\n<template v-if=\"store.resources.todo[id]?.value\">\n  <input v-model.lazy=\"store.resources.todo[id].value.title\" />\n</template>\n```\n\n### IME and composition input\n\n`v-model` follows Vue's stock composition handling, and you write nothing special to get it right. While an input-method editor is composing a character — CJK input, dead-key/accent sequences, some mobile autocomplete — Vue suppresses the per-keystroke `input` updates and stages a single optimistic write only when composition ends (`compositionend`, when `event.isComposing` clears). So composing にほんご produces **one** optimistic write at the end, not one per intermediate keystroke, and the debounce above coalesces from there. Flush-on-blur still applies: if a composing field loses focus, its committed value flushes. (This is the real-browser behavior our IME probe pins — jsdom doesn't model composition, so it's only observable in the browser.)\n\n## Concurrent edits and long-form text\n\nThe default `'use-server'` conflict resolution can clobber a user's in-progress\nkeystrokes when a concurrent edit from another client lands mid-typing. Annotating\na field `@longform` auto-registers a text-merge resolver that preserves both\nedits, so long-form text (descriptions, comments, document bodies) is handled for\nyou — no handler to write. For custom merge logic, register your own per-type\nhandler — see [Resources § Text fields specifically — don't leave the\ndefault](./resources.md#text-fields-specifically--dont-leave-the-default). Short\nsingle-line fields like titles don't need any of this.\n\nText-merge preserves *non-overlapping* concurrent edits cleanly; when two users\nedit the same span at once it can still garble. Conflict-free collaborative\nediting (Google-Docs-style) needs a CRDT, which is out of scope for now.\n\n## Loading and first paint\n\nA resource's `?.value` is `undefined` until the initial server push lands (typically tens of ms; longer on cold connect). Three patterns:\n\n**1. Inline placeholder via `??`** — simplest; works for any one-way text binding.\n\n```html @skip-check\n<span>{{ store.resources.todo['task-42']?.value?.title ?? 'Loading…' }}</span>\n```\n\n**2. Skeleton loader** — `v-if` on `value` swaps branches atomically once the snapshot arrives.\n\n```html @skip-check\n<div v-if=\"store.resources.todo['task-42']?.value\" class=\"card\">\n  <h2>{{ store.resources.todo['task-42'].value.title }}</h2>\n</div>\n<div v-else class=\"card skeleton\"></div>\n```\n\n**3. Multi-state status via `computed`** — distinguishes loading from deleted (connection state is shown separately — see the reconnect banner below). A deleted resource is **not** falsy: tombstones arrive as a real snapshot with `meta.deleted: true` and the last value still present, so the `meta.deleted` check must run *before* any `value` truthiness test. Patterns 1 and 2 don't cover deletion — they'd render a tombstone as if it were alive. (`meta.deleted` is `undefined` only for never-loaded resources.)\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nimport { computed } from 'vue';\n\nconst todoStatus = computed(() => {\n  const snap = store.resources.todo['task-42'];\n  // No 'connecting' state here: the app mounts only after `await ready` (so it's\n  // connected by first render). First-connect \"Connecting…\" lives in the static\n  // pre-mount shell; a later drop shows the reconnect banner (below) over the\n  // painted data while this stays 'ready'. A logged-out visitor never reaches\n  // this — `ready` rejects and the bootstrap redirects before mount.\n  if (snap?.meta?.deleted) return 'deleted';\n  if (!snap?.value)        return 'loading';\n  return 'ready';\n});\n```\n\n```html @skip-check\n<div v-if=\"todoStatus === 'deleted'\" class=\"alert alert-warning\">This todo was deleted.</div>\n<div v-else-if=\"todoStatus === 'loading'\" class=\"card skeleton\"></div>\n<div v-else class=\"card\">\n  <h2>{{ store.resources.todo['task-42'].value.title }}</h2>\n</div>\n```\n\n## Connection state\n\nThe factory mirrors `NebulaClient`'s connection state onto the store under `store.lmz.connection.*`. UI binds declaratively; no event listeners. Initial seeds (`'disconnected'` / `false` / `undefined`) mean first-paint reads never need `?.` guards.\n\n| Path | Type | Description |\n| --- | --- | --- |\n| `store.lmz.connection.state` | `'connecting'` / `'connected'` / `'reconnecting'` / `'disconnected'` | Current state. |\n| `store.lmz.connection.connected` | `boolean` | `true` iff `state === 'connected'`. |\n| `store.lmz.connection.lastConnectedAt` | `number \\| undefined` | `Date.now()` from the most recent `'connected'` transition. |\n\n```html @skip-check\n<!-- Banner while reconnecting (was connected, socket dropped). The promise is\n     real: while not connected the framework suspends submission and holds writes\n     (the optimistic store already shows them), flushing on reconnect (idempotent),\n     so nothing rolls back from a blip. Held writes live in memory only — a page\n     reload while offline drops anything unsent. (A terminal auth failure instead\n     fires onLoginRequired → redirect; it does not show this banner.) -->\n<div v-if=\"store.lmz.connection.state === 'reconnecting'\" class=\"alert alert-warning\">\n  Reconnecting — your changes are queued.\n</div>\n\n<!-- Disable a button while not connected. -->\n<button :disabled=\"!store.lmz.connection.connected\" class=\"btn btn-primary\" @click=\"save\">Save</button>\n```\n\nFor richer status UI (color-coded badges, \"last connected X minutes ago\" tooltips), use `:class` object syntax against `store.lmz.connection.state` and format `store.lmz.connection.lastConnectedAt` with `new Date(...)`.\n\n## Current user (`client.claims`)\n\nThe decoded JWT payload is on `client.claims` — `sub` (subject, the user's stable ID — a bare UUID minted by nebula-auth), `aud` (audience), `access` (the user's scope grant — `{ authScope, scopeAdmin? }`), and any other claims your auth provider mints. The object is frozen; it is replaced wholesale on each token refresh (the values you key on — `sub`, `aud` — don't change within a session).\n\n`client.claims` is `null` until the client's first token refresh completes, and `client` is not reactive — a `v-if` gated on it never re-evaluates. Studio-generated apps never see that window: the bootstrap top-level-awaits the factory's `ready` promise before the app mounts, so claims are populated before any component renders. That contract is pinned at [API reference § client.claims](./api-reference.md#clientclaims); the examples below rely on it. Outside a Studio bootstrap (admin tools, scripts), guard with `client.claims?.`.\n\n```html @skip-check\n<!-- Per-user keying — bind to this user's own list, looked up by their JWT sub. -->\n<h2 v-if=\"store.resources.todoList[client.claims.sub]?.value\">Your list</h2>\n```\n\nThe same `client.claims.sub` keying works in script too — the [Forms](#forms-explicit-save) examples below use it as a transaction key.\n\n### Gating admin-only UI\n\n\"Admin\" has **two** independent sources, and admin-only UI checks both:\n\n- **App admin** — a user holding `admin` on the relevant org-tree node. App-wide admin is `admin` on the root node; per-area admin is `admin` (directly or cascaded) on that area's node. This lives in the reactive tree at `store.lmz.orgTree`, so the UI tracks grants as they change.\n- **Scope admin** — a Galaxy- or Universe-level operator, carried in the JWT as `client.claims.access.scopeAdmin`. They have effective admin everywhere in the scope, but — being a scope property, not a node grant — they do **not** appear in the org-tree's `permissions` map (see [the note in Resources](./access-control.md)). So you can't discover them from the tree; you read the claim.\n\nA `computed` that covers both:\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nimport { computed } from 'vue';\nimport { ROOT_NODE_ID } from '@lumenize/nebula/frontend';\nimport { store, client } from './nebula';\n\nconst isAppAdmin = computed(() =>\n  client.claims.access.scopeAdmin ||                                     // Galaxy/Universe scope admin\n  store.lmz.orgTree?.value?.permissions\n    .get(ROOT_NODE_ID)?.get(client.claims.sub) === 'admin'          // app admin (grant on root)\n);\n```\n\n```html @skip-check\n<button v-if=\"isAppAdmin\" class=\"btn\">Admin settings</button>\n```\n\n`isAppAdmin` is a **UI gate, not an authorization boundary.** It reads `store.lmz.orgTree` (client-held, freely mutable in the browser) and `client.claims`, so it only decides what *renders* — it is not a security check. Every privileged operation behind it is re-authorized server-side (`requirePermission` / the org-tree cascade on each transaction; the JWT `aud`-lock on each mesh call). Never let a generated app treat a passing `isAppAdmin` as sufficient to expose an action whose server endpoint lacks its own permission check.\n\n`client.claims` is the client-side counterpart of `originAuth.claims` server-side. See [mesh: LumenizeClient](/docs/mesh/lumenize-client#client-identity-clientclaims) for the surface and [Nebula auth flows](./auth-flows.md) for how the JWT is issued.\n\n## Subscription lifecycle\n\nAuto-subscribe is already at work in the examples above — any `store.resources.*` read inside a component (`setup()`, `computed`, template, `watch`) subscribes that resource, with no manual `subscribe` call. This section is about the rest of the lifecycle: how live subscriptions are coalesced, and how they're released when components go away.\n\nSubscriptions are reference-counted across the whole app. Reading the same resource from several places — multiple fields in one component, or several mounted components showing it at once — shares one subscription; the count tracks how many live references it has.\n\nWhen a component unmounts, its reference drops. The subscription starts releasing only when the count reaches zero (the last component using the resource has gone away), and even then waits a **2-second grace period** (configurable via `createNebulaClient({ unsubscribeGraceMs: ... })`). If a new read appears within that window — tab-switch back, modal close-then-reopen, `<KeepAlive>` swap, click-to-edit toggle — the pending release cancels and the subscription stays live with no re-subscribe round-trip.\n\n```html @skip-check\n<!-- Click-to-edit. Toggling between the <h2> and <input> unmounts one and\n     mounts the other — the subscription to store.resources.todo[id] survives\n     the toggle because both reads happen well within the 2 s grace window. -->\n<template v-if=\"store.resources.todo[id]?.value\">\n  <h2 v-if=\"!store.ui.editingTitle\" @click=\"store.ui.editingTitle = true\">\n    {{ store.resources.todo[id].value.title }}\n  </h2>\n  <input v-else v-model=\"store.resources.todo[id].value.title\"\n         @blur=\"store.ui.editingTitle = false\" />\n</template>\n```\n\nFor non-component cases (warming a cache before navigation, scripting, headless tests), call `client.resources.subscribe(rt, rid)` directly. The returned handle is `Disposable` — use `using` for auto-release on scope exit, or call `client.resources.unsubscribe(rt, rid)` manually if subscribe and unsubscribe happen in different places. See [API reference § resources.subscribe](./api-reference.md#resourcessubscribe).\n\nTwo parts of the lifecycle need no UI code: after a dropped connection reconnects, live subscriptions re-subscribe themselves; and deploying a new app version clears server-side subscriptions and triggers a refresh (`onShouldRefreshUI`).\n\n## Plain Vue state\n\nAnything **not** under `store.resources.*` is plain Vue reactive state. Two common patterns:\n\n- **Instance-local** — Vue's [`ref` / `reactive`](https://vuejs.org/api/reactivity-core.html) inside `<script setup>`.\n- **Shared across components or persists across remount** — put it on the store under a non-reserved prefix, typically `store.ui.*` (transient UI state like form drafts) or `store.app.*` (app-wide state like the current view). The factory pre-seeds `store.ui` and `store.app` as empty objects, so first-level use (`store.ui.editingTitle = true`, `v-if=\"!store.ui.editingTitle\"`) works with no setup.\n\nDeeper state needs initialization before being used as a `v-model` target. The two kinds initialize differently:\n\n- **`store.resources.*`** — create the resource on the server, typically via `client.resources.transaction({ ... op: 'create' ... })`. See [Atomic append](#atomic-append--adding-to-a-collection) for the pattern.\n- **Plain Vue state** — initialize the intermediate objects locally; the factory does NOT auto-vivify under non-reserved prefixes. `v-model=\"store.ui.todoForm.draft.title\"` requires `store.ui.todoForm.draft` to already exist. Initialize in `nebula.ts` at module load or in `onMounted` — see [Forms: explicit save](#forms-explicit-save).\n\n\n## Lists with `v-for`\n\nFor lists of resources, use a **container resource** whose value holds an array of IDs. Reading `store.resources.<rt>[<rid>]` for each ID inside the loop auto-subscribes that resource individually.\n\n```typescript @skip-check\n// Ontology (.d.ts-style file)\ninterface TodoList {\n  items: string[];        // IDs of Todo resources, in display order\n}\n\ninterface Todo {\n  title: string;\n  description: string;\n  status: 'open' | 'done';\n}\n```\n\n```html @skip-check\n<!-- Subscribes to the container; each iteration subscribes to its todo.\n     Removing an ID unmounts the <li>, decrements the refcount, and\n     unsubscribes after the 2 s grace period. -->\n<ul>\n  <li v-for=\"todoId in store.resources.todoList[client.claims.sub]?.value?.items ?? []\" :key=\"todoId\">\n    {{ store.resources.todo[todoId]?.value?.title ?? '...' }}\n    <span v-if=\"store.resources.todo[todoId]?.value?.status === 'done'\">✓</span>\n  </li>\n</ul>\n```\n\nA count like \"open todos\" is a **client-side computed**, derived from the subscribed todos — not a stored field. It recomputes automatically on any change (a local edit, a server fanout, or a committed transaction all mutate the reactive store), so it always matches what's on screen:\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nimport { computed } from 'vue';\n\nconst openCount = computed(() =>\n  (store.resources.todoList[client.claims.sub]?.value?.items ?? [])\n    .filter(id => store.resources.todo[id]?.value?.status === 'open').length\n);\n```\n\n(Storing such an aggregate on the resource — for cross-view display without loading the items, or for time-series analytics over history — needs a server-enforced derived-field invariant, a future ontology capability. Until then, keep aggregates client-computed.)\n\nThe container is keyed per user — `('todoList', client.claims.sub)` — so each user has their own list, looked up by their JWT subject. Subscribing to a resource that doesn't exist yet is a server-side error, so the app creates the list on first visit: read, then create if absent. This runs in `nebula.ts` after `await ready` (claims are populated, and module evaluation finishes before any component renders):\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// nebula.ts (after `await ready`)\nimport { ROOT_NODE_ID } from '@lumenize/nebula/frontend';\nconst sub = client.claims.sub;\n\n// Create the list under a node the user can write to. This demo signs in as\n// the Star's initial DataPlane root admin, who holds `admin` on the root node (granted when the\n// Star was created), so resources attach under ROOT_NODE_ID. In a multi-user\n// app, attach under whatever node the user was granted — see \"Mutating the\n// org/permission tree\" for how access is granted.\nif (await client.resources.read('todoList', sub) === null) {\n  const outcome = await client.resources.transaction({\n    [sub]: { op: 'create', typeName: 'todoList', nodeId: ROOT_NODE_ID,\n             value: { items: [] } },\n  });\n  // A single-resource create commits iff the top-level outcome is 'committed'\n  // (atomicity ⟹ if the batch committed, the create landed). Any failure is NOT\n  // 'committed': permission/validation → 'rejected'; a lost first-create race\n  // (\"already exists\") → 'infrastructure-error' today (M11 may reclassify it).\n  // Race-safe: when not created, re-read to disambiguate — the list now exists (a\n  // tab won the race, proceed) or it genuinely doesn't (a real failure to surface).\n  const created = outcome.kind === 'committed';\n  if (!created && await client.resources.read('todoList', sub) === null) {\n    throw new Error('Could not create your list — check your connection and reload.');\n  }\n}\n```\n\n(A node the user can write to is the only prerequisite; the Star's own admin gets one — `admin` on root — on first touch. Other users acquire write on a node by being granted it — see [Mutating the org/permission tree](#mutating-the-orgpermission-tree); who to ask is resolved client-side from the tree (see the [worked example](#worked-example-rendering-the-built-in-tree)).)\n\nBy contrast, a field whose elements are **inline objects** — composition *within* this one resource, e.g. a todo's `checklist: { text, done }[]` — iterates the same way but without auto-subscribing per item; the fields are right there in the value. The distinction is by type: a field typed as **another ontology type** (e.g. `assignees: User[]`) is a *relationship*, stored by id and read like `items` above — one auto-subscribe per id — never an embedded object; nesting is for inline composition only (see [Resources](./resources.md)).\n\nThis works up to ~hundreds of items. Beyond that, a query language is the right tool — deferred for now.\n\n### Atomic append — adding to a collection\n\nCreating a new resource and adding its ID to a container happens in **one transaction**, so neither orphan-todo nor dangling-reference state ever exists. For the \"two users added at the same time\" race, register a handler on the list type that returns `'use-this'` with a **set-union of `items`** — so neither client's just-added id is dropped (a plain `'use-server'` would orphan the loser's new todo) — see [Resources § per-resource handler](./resources.md#per-resource-behavior--the-ontransactionresourceresolution-handler).\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nasync function addTodo(title: string) {\n  const newId = crypto.randomUUID();\n  const listSnap = store.resources.todoList[client.claims.sub];\n  const list = listSnap?.value;\n  if (!list) return;   // snapshot not arrived yet — see \"Loading and first paint\"\n\n  // Both ops in one call → atomic. Either both commit or neither does.\n  // eTag for the put auto-derives from store.resources.todoList[...]?.meta?.eTag;\n  // a missing baseline (resource never subscribed) THROWS synchronously here\n  // rather than returning a non-committed outcome — the v-if/snapshot guard above\n  // prevents that. The new todo attaches under the same tree node as the list\n  // (meta.nodeId, not value — nodeId is server-managed metadata).\n  const outcome = await client.resources.transaction({\n    [newId]:             { op: 'create', typeName: 'todo', nodeId: listSnap.meta.nodeId,\n                           value: { title, description: '', status: 'open' } },\n    [client.claims.sub]: { op: 'put',    typeName: 'todoList',\n                           value: { ...list, items: [...list.items, newId] } },\n  });\n  // error handling on outcome goes here\n}\n```\n\n## Conditionals with `v-if`\n\nStock Vue. The one Nebula-relevant note: subscriptions inside an unmounted branch don't initiate. A `v-if=\"false\"` branch's resource paths are NOT subscribed.\n\n```html @skip-check\n<!-- While `expanded` is false, the todo resource is NOT subscribed. -->\n<div v-if=\"expanded\">\n  {{ store.resources.todo[id]?.value?.description }}\n</div>\n```\n\n## Forms: explicit save\n\nFor multi-field forms that should commit together (rather than per-keystroke transactions), bind inputs to a local draft path and submit on click. Each form keeps its draft under its own `store.ui.<formName>.draft` path.\n\nForm-scoped reactions — clear the draft on commit, surface validation errors next to fields — belong in a **per-call handler** passed to that save's `transaction()` call, NOT in the per-type handler: the per-type handler fires on *every* transaction touching the type (debounced `v-model` edits, other forms, list mutations), so form state wired there gets clobbered by unrelated commits. Keep the per-type handler (registered once in `nebula.ts`) for type-wide policy — conflict verdicts, custom flashes; see [Resources § per-resource handler](./resources.md#per-resource-behavior--the-ontransactionresourceresolution-handler). Per-call handlers are **keyed by `resourceId`** — `{ 'task-42': handler }` — so each handles only its own resource, and any sibling in the batch falls through to its per-type handler automatically (the per-call entry layers in front of its resource's per-type handler — it does not replace it; see [API reference § Precedence](./api-reference.md#precedence)).\n\nMount the form only after the resource's snapshot has arrived — the same `v-if` guard from [Loading and first paint](#loading-and-first-paint): `<TodoForm v-if=\"store.resources.todo['task-42']?.value\" />`. Seeding the draft before the snapshot lands would stage blank values that Save then commits over the real data (the eTag auto-derive matches, so no conflict fires to stop it).\n\n```vue @skip-check\n<!-- TodoForm.vue — local draft → explicit transaction on submit.\n     Parent mounts it only once the snapshot exists (see above). -->\n<script setup lang=\"ts\">\nimport { onMounted } from 'vue';\nimport { store, client } from './nebula';\n\n// Seed the draft from the synced value on first mount. store.ui.todoForm must\n// exist as an object before v-model can bind nested fields (the factory\n// pre-seeds store.ui itself, but not intermediates).\nonMounted(() => {\n  if (!store.ui.todoForm) store.ui.todoForm = {};\n  store.ui.todoForm.draft = { ...store.resources.todo['task-42'].value };\n});\n\nasync function saveTodo() {\n  const draft = store.ui.todoForm.draft;\n  // A status change needs no coordinated write — openCount is a client computed —\n  // so saving a todo is a single-resource put.\n  const outcome = await client.resources.transaction({\n    'task-42': { op: 'put', typeName: 'todo', value: draft },\n  }, {\n    // Per-call handlers are keyed by resourceId — this one handles 'task-42'.\n    // (In a multi-resource batch, any resource not listed here falls through to\n    // its per-type handler automatically — no rid filtering, no shadowing. See\n    // API reference § Precedence; e.g. addTodo lets todoList fall through to its\n    // per-type set-union handler.)\n    onTransactionResourceResolution: {\n      'task-42': (rid, resolution) => {\n        switch (resolution.kind) {\n          case 'committed':         store.ui.todoForm.draft = undefined; break;\n          case 'validation-failed': store.ui.todoForm.validationErrors = resolution.errors; break;\n          case 'permission-denied': store.ui.todoForm.saveError = { kind: 'permission-denied', rid }; break;\n        }\n      },\n    },\n  });\n  // transaction-wide failures (timeout, infrastructure-error) handled here\n}\n</script>\n\n<template>\n  <form v-if=\"store.ui.todoForm?.draft\" @submit.prevent=\"saveTodo\">\n    <input v-model=\"store.ui.todoForm.draft.title\" />\n    <textarea v-model=\"store.ui.todoForm.draft.description\"></textarea>\n    <select v-model=\"store.ui.todoForm.draft.status\">\n      <option value=\"open\">Open</option>\n      <option value=\"done\">Done</option>\n    </select>\n    <button type=\"submit\">Save</button>\n  </form>\n</template>\n```\n\nRule of thumb: `store.resources.*` for per-keystroke (debounced) writes; `store.ui.<formName>.*` for staged writes that the user explicitly commits. For multiple concurrent forms, use distinct form names (`store.ui.projectForm.draft`, etc.).\n\n## Recursive components\n\nEach recursive instance auto-subscribes to its own resource (the foreign-key pattern from [Lists](#lists-with-v-for) applied at every level). Unmounting decrements the refcount; grace period applies as usual.\n\n```vue @skip-check\n<!-- TreeNode.vue -->\n<script setup lang=\"ts\">\nimport { store } from './nebula';\n\ndefineProps<{ nodeId: string }>();\n</script>\n\n<template>\n  <span>{{ store.resources.treeNode[nodeId]?.value?.label ?? '...' }}</span>\n  <ul v-if=\"(store.resources.treeNode[nodeId]?.value?.childIds?.length ?? 0) > 0\">\n    <!-- `childIds` is an array of node IDs (foreign-key pattern from \"Lists\"\n         above). Each recursive <TreeNode> auto-subscribes to its own resource\n         via store.resources.treeNode[childId]. -->\n    <li\n      v-for=\"childId in store.resources.treeNode[nodeId].value.childIds\"\n      :key=\"childId\"\n    >\n      <TreeNode :node-id=\"childId\" />\n    </li>\n  </ul>\n</template>\n```\n\nMount the recursive component from any parent at a known root id: `<TreeNode :node-id=\"rootId\" />`.\n\n\n## Mutating the org/permission tree\n\nThe tree itself is mutable through `client.orgTree.*` methods. Each method requires the caller to hold a specific permission on the target node — `admin` for permission grants, `write` for structural changes (create, reparent, delete, rename, relabel; edge ops check the parent). The one hybrid is `addEdge`, which also requires `admin` on the *child*: adding a parent edge widens who has access to the child's subtree, so the child side demands `setPermission`'s tier. Failures reject the returned Promise.\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// Grant a permission. `sub` is a JWT subject claim — a bare UUID (the current\n// user's is client.claims.sub; other users' subs come from wherever your app\n// stores its member list). `level` is 'read' (view), 'write' (edit +\n// structural changes), or 'admin' (write + manage permissions).\n// Caller must hold `admin` on `nodeId`.\nawait client.orgTree.setPermission(nodeId, bobsSub, 'read');\n\n// Revoke. Idempotent — no-op if `sub` has no grant on this node.\nawait client.orgTree.revokePermission(nodeId, bobsSub);\n\n// Create a child node — YOU supply the id (a UUID), so you have it immediately\n// (no round-trip) and a retry with the same id is idempotent. Caller must hold\n// `write` on `parentNodeId`.\nconst listShoppingId = crypto.randomUUID();\nawait client.orgTree.createNode(listShoppingId, userAliceNodeId, 'list-shopping', 'Shopping');\n\n// Co-ownership sharing — the two-party share-accept flow from Resources §\n// Access control. Step 1, owner offers (runs as Alice): grant Bob admin on\n// the list.\nawait client.orgTree.setPermission(listShoppingId, bobsSub, 'admin');\n\n// Step 2, recipient accepts (runs as Bob): the edge makes the list a child\n// of both user-alice AND user-bob, so Bob's admin on user-bob now cascades\n// to it. addEdge requires `write` on the new parent + `admin` on the child.\nawait client.orgTree.addEdge(userBobNodeId, listShoppingId);\n\n// Step 3, optional cleanup (either co-owner): the direct grant from step 1\n// is redundant once the edge cascades.\nawait client.orgTree.revokePermission(listShoppingId, bobsSub);\n\n// \"Remove from my account\" = delete only this user's edge to the list.\n// The list lives on under its other parents.\nawait client.orgTree.removeEdge(userBobNodeId, listShoppingId);\n```\n\nThe full surface (`reparentNode`, `deleteNode`, `undeleteNode`, `renameNode`, `relabelNode`) is at [API reference § client.orgTree](./api-reference.md#clientorgtree). For the conceptual model (cascading permissions, the two sharing approaches, when to use which), see [Resources § Access control](./access-control.md).\n\n## Worked example: rendering the built-in tree\n\n**Every Nebula app receives the same built-in org/permission tree** — the structure that resources are attached to for permissions and tenancy. Every connected client gets the full tree at `store.lmz.orgTree.value` — structure *and* the full permissions table (opaque-ID-keyed; see [Resources § Access control](./access-control.md) for what that exposes and why). Visibility is intentionally not restricted — the sub-second-RTT permission UX wants every client to know the full shape locally, to grey out inaccessible nodes and resolve who to ask for access. Most apps will surface it somewhere in their UI; rendering it as a tree view is the most common form (others: a flat list of accessible nodes, a breadcrumb selector for the current scope, a permission-grant dialog).\n\nThe example pulls together: reading the built-in org tree (delivered on its own channel to `store.lmz.orgTree`), walking the embedded `Map<string, ...>` in a `computed`, recursive Vue components, per-instance state, and `provide` / `inject` to broadcast a derived signal down the tree. It includes multi-parent rendering (the tree allows a node to have more than one parent — see [Resources § Access control](./access-control.md) for why and the tradeoffs), virtual \"Deleted\" / \"Orphaned\" branches, and search with match highlighting + auto-expand of ancestors of matches.\n\n### The tree shape\n\n`store.lmz.orgTree.value` is an [`OrgTreeState`](./api-reference.md#orgtreestate) — `nodes` (a `Map<string, { slug, label, deleted }>`, keyed by the node's UUID), `edges` (a `Set` of `\"parentId:childId\"` keys — adjacency lives here, not on the nodes), and `permissions`. For O(1) parent/child lookups while walking, build an `OrgTreeView` with `buildOrgTreeView(orgTree)` (exported from `@lumenize/nebula/frontend`); the `tree.ts` helpers below use it.\n\nThe tree is subscribed once on connect and kept current at `store.lmz.orgTree`; every server-side mutation broadcasts a fresh snapshot to all connected clients (the actor included — `client.orgTree.*` has no optimistic local write, so the broadcast echo is what updates your own store). The delivery is tagged `new-in-v3` — see [API reference § OrgTreeState](./api-reference.md#orgtreestate).\n\nThe framework reserves the `lmz` resourceType for its own resources (mirrors the `lmz.*` reserved prefix used for non-resource paths like `lmz.connection.*` — anything under `lmz` in either reserved namespace is framework territory).\n\n**Multi-parent rendering**: a node with parents `[A, B]` renders once under each. The derivation walks every parent edge; each rendered position is its own `OrgTreeNode` instance with independent per-instance state automatically.\n\n**Virtual branches**: `__deleted__` and `__orphaned__` are IDs in the derived `TreeNodeData` tree. Real tree nodes have a UUID `nodeId`, so the derived `TreeNodeData.id` — `String(nodeId)` — is a hyphenated hex UUID for every real node; the underscore-prefixed virtual IDs can't collide with a UUID.\n\n### Derivation helpers (`tree.ts`)\n\n```typescript @skip-check\n// tree.ts — shape + derivation helpers used by App.vue and OrgTreeNode.vue.\nimport { ROOT_NODE_ID, buildOrgTreeView, type OrgTreeState } from '@lumenize/nebula/frontend';\n\nexport interface TreeNodeData {\n  id: string;                                       // String(nodeId) for real nodes; '__deleted__' / '__orphaned__' for virtuals\n  label: string;\n  labelRuns?: { text: string; match: boolean }[];   // populated when query is non-empty\n  deleted?: boolean;\n  children: TreeNodeData[];\n}\n\n// Walks from ROOT_NODE_ID through `dag.nodes`, rendering a node under each of\n// its parents. Skips deleted nodes during the main walk; collects them into a\n// __deleted__ subtree. Computes orphaned (nodes not reachable from root via\n// undeleted edges) into __orphaned__. When `query` is non-empty, splits each\n// label into labelRuns = [{text, match: boolean}, ...] so the template can\n// render match highlighting safely without v-html.\nexport function deriveTreeWithVirtuals(\n  orgTree: OrgTreeState,\n  query: string,\n): TreeNodeData {\n  // Build the adjacency view once (childrenByParent / parentsByChild from\n  // orgTree.edges), then walk from ROOT_NODE_ID: view.childrenByParent.get(id)\n  // for each node's children, orgTree.nodes.get(id) for its {slug, label, deleted}.\n  const view = buildOrgTreeView(orgTree);\n  return { /* root TreeNodeData */ } as TreeNodeData;\n}\n\n// For each node whose labelRuns contains a match, adds every ancestor id to\n// `ids` (App.vue provides the result as the auto-expand set).\nexport function walkAndCollectAncestorsOfMatches(\n  tree: TreeNodeData, ancestors: string[], ids: Set<string>,\n): void { /* ... */ }\n```\n\n### Component (`OrgTreeNode.vue`)\n\n```vue @skip-check\n<!-- OrgTreeNode.vue — recursive tree row + child list. -->\n<script setup lang=\"ts\">\nimport { ref, inject, watch, type Ref } from 'vue';\nimport type { TreeNodeData } from './tree';\n\nconst props = defineProps<{ node: TreeNodeData }>();\n\n// Per-instance state: each OrgTreeNode instance has its own isOpen.\nconst isOpen = ref(false);\nconst toggleOpen = () => { isOpen.value = !isOpen.value; };\n\n// App.vue provides a reactive set of ids to auto-expand on search match.\n// When our id appears in the set, flip isOpen to true.\nconst expansionsForQuery = inject<Ref<Set<string>>>('expansionsForQuery');\nwatch(\n  () => expansionsForQuery?.value,\n  (set) => { if (set?.has(props.node.id)) isOpen.value = true; },\n  { immediate: true },\n);\n</script>\n\n<template>\n  <li>\n    <button v-show=\"node.children.length\" @click=\"toggleOpen\">\n      {{ isOpen ? '▼' : '▶' }}\n    </button>\n\n    <!-- Plain label when not searching; highlighted runs when query is active. -->\n    <span v-if=\"!node.labelRuns\">{{ node.label }}</span>\n    <span v-else>\n      <span v-for=\"(run, i) in node.labelRuns\" :key=\"i\"\n            :class=\"{ 'bg-warning': run.match }\">{{ run.text }}</span>\n    </span>\n\n    <ul v-if=\"isOpen\">\n      <OrgTreeNode v-for=\"child in node.children\" :key=\"child.id\" :node=\"child\" />\n    </ul>\n  </li>\n</template>\n```\n\n### Root component (`App.vue`)\n\n```vue @skip-check\n<!-- App.vue — search input + tree derivation + provide auto-expand set. -->\n<script setup lang=\"ts\">\nimport { computed, provide, onMounted } from 'vue';\nimport type { OrgTreeState } from '@lumenize/nebula/frontend';\nimport { store } from './nebula';\nimport OrgTreeNode from './OrgTreeNode.vue';\nimport { deriveTreeWithVirtuals, walkAndCollectAncestorsOfMatches,\n  type TreeNodeData } from './tree';\n\nonMounted(() => { if (!store.ui.search) store.ui.search = { query: '' }; });\n\n// The org tree is delivered on a dedicated channel (subscribed on connect) and\n// kept current at store.lmz.orgTree — read it reactively here.\n// Re-runs when the server pushes a new OrgTreeState or the query changes.\n// Vue 3's reactivity tracks Map.get / Map iteration natively.\nconst tree = computed<TreeNodeData | null>(() => {\n  const orgTree = store.lmz.orgTree?.value as OrgTreeState | undefined;\n  if (!orgTree) return null;\n  return deriveTreeWithVirtuals(orgTree, (store.ui.search?.query ?? '').toLowerCase());\n});\n\n// Pure derivation (returns a Set, doesn't mutate component state) — every\n// OrgTreeNode instance rendered at the same id (multi-parent positions) sees\n// the same set independently.\nconst expansionsForQuery = computed<Set<string>>(() => {\n  const t = tree.value;\n  const q = store.ui.search?.query;\n  if (!q || !t) return new Set();\n  const ids = new Set<string>();\n  walkAndCollectAncestorsOfMatches(t, [], ids);\n  return ids;\n});\nprovide('expansionsForQuery', expansionsForQuery);\n</script>\n\n<template>\n  <input v-if=\"store.ui.search\" v-model=\"store.ui.search.query\" placeholder=\"Search…\" />\n  <ul v-if=\"tree\"><OrgTreeNode :node=\"tree\" /></ul>\n</template>\n```\n",
  ".platform/docs/nebula-client.md": "---\ntitle: NebulaClient\ndescription: Client-side class for connecting to Nebula.\n---\n\n# NebulaClient\n\n`NebulaClient` extends [`LumenizeClient`](/docs/mesh/lumenize-client) with Nebula's **two-scope model**:\n\n- **Auth scope** — the NebulaAuth instance name the user authenticated against (e.g., `acme.app.tenant-a` for a regular user, `acme` for a universe admin). Determines the refresh cookie path.\n- **Active scope** — the specific universe, galaxy, or star the client is targeting. Baked into the JWT `aud` claim. For regular users, same as auth scope; for an admin it can be any scope at or below their auth scope.\n\n```typescript @skip-check\n// Direct construction — admin/scripting path with explicit scopes.\nconst client = new NebulaClient({\n  baseUrl: 'https://my-app.example.com',\n  authScope: 'acme.app.tenant-a',\n  activeScope: 'acme.app.tenant-a',\n  ontologyVersion: 'v42',                  // the server-installed ontology version (enforced)\n});\n```\n\nBrowser apps don't construct `NebulaClient` directly — they use [`createNebulaClient`](./api-reference.md#createnebulaclient), where `baseUrl`, `activeScope`, and `onShouldRefreshUI` auto-detect. `ontologyVersion` is always required; `authScope` is currently required-in-practice too (its URL auto-detect is deferred — omitting it throws a clear error), and the explicit scopes above are the admin/scripting escape hatch.\n\nSwitching active scope means creating a new `NebulaClient` with a different `activeScope`. The refresh cookie (scoped to the auth scope path) carries over automatically.\n\n## Calling `@mesh()` methods locally\n\n`NebulaClient` subclasses can have `@mesh()` methods that DOs call through the Gateway. The `@mesh()` decorator is pure metadata — it marks the method as remotely callable but does not wrap it. Calling a `@mesh()` method directly from surrounding JavaScript (e.g., `client.echo('hello')`) executes the method normally with no interception and no guard check. Guards only run when the call arrives via the mesh.\n\nSee [Auth flows](./auth-flows.md) for the full login, returning user, and scope-switching sequences.\n",
  ".platform/docs/ontology.md": "---\ntitle: Ontology\ndescription: How you define resource types in Nebula — the .d.ts schema, per-type configuration, references, and how the ontology becomes a runtime parser-validator.\n---\n\n# Ontology\n\n:::warning Outline only\nThis page is a stub outlining planned content. Sections list what they'll cover but bodies are not yet written. Drafting begins after the `coding-your-ui.md` manual review pass and a separate review of `resources.md` and `api-reference.md`.\n:::\n\nThe **ontology** is the single declaration of what resource types exist in your Nebula app, what shape each one has, how it references other types, and how it behaves under conflict. It's the first conversation Studio has with a user-developer — before any UI work happens, you and Studio agree on the data model. From the LLM's point of view, the ontology is the cornerstone context for everything else.\n\n## What an ontology is\n\n- A `.d.ts`-style TypeScript file (one file per app, or one per type with a barrel — open question, see below).\n- Defines resource types via standard TypeScript `interface` / `type` declarations.\n- Annotated with JSDoc-style tags (`@title`, `@description`, `@inverse`, etc.) that Studio's LLM and the runtime parser-validator both consume.\n- Compiled at deploy time by [typia](https://typia.io) into a runtime parser-validator (see [@lumenize/ts-runtime-parser-validator](../ts-runtime-parser-validator/index.md) for the compilation pipeline).\n- The single source of truth: the server validates every transaction against it; the client uses it for typed `store.resources.<type>` access (typed access is a planned addition — currently `Record<string, any>`).\n\n> **Open**: file layout. Single `ontology.d.ts` per app vs. per-type files (`Todo.d.ts`, `TodoList.d.ts`, ...) with a barrel `ontology/index.d.ts`. The single-file form is simpler for small apps and easier for the LLM to consult; per-type files scale better for large apps and co-locate the type with its resolver. Probably let Studio pick based on app size; document both shapes.\n\n## Defining a type\n\nWill show:\n\n- `interface MyType { ... }` shape declarations.\n- Primitive fields (`string`, `number`, `boolean`, `Date`, ULID/UUID `string` typedefs).\n- Embedded objects and arrays of embedded objects.\n- Optional vs required (`field?:` vs `field:`) — per the project's `optional-over-nullable` preference, default to `field?: T`, not `field: T | null`.\n- Default values (via TypeScript's default-value tricks or annotations — open: which mechanism to prefer).\n- Constraints: numeric ranges, string patterns, enum literal unions, etc. (via typia tags).\n\n> **Open**: how to express constraints. typia supports JSDoc tags like `@minimum 0`, `@pattern \"...\"`, but also branded types. Both work; need to pick a canonical idiom for Studio's LLM to use consistently.\n\n## References between types\n\nA field whose type is another ontology type is a **relationship**, and Nebula models relationships **by id (foreign key) — never by embedding**. This is a hard contract ([ADR-006](https://github.com/lumenize/lumenize/blob/main/docs/adr/006-resources-reference-by-id.md)):\n\n- **A reference field holds the *id* of the related resource, not the resource itself.** You write the related *type* in the schema (`list: TodoList`); on the wire and in storage that field is the related resource's id `string` — Nebula derives this \"write shape\" automatically. A to-many reference (`members: User[]`) is an array of ids (`string[]`).\n- **Related resources are created and updated as separate ops in one transaction.** A `transaction(...)` is a map of independent ops that commit atomically, so \"create a parent and its children together\" is several ops in a single call — each with its own client-supplied id, each reference field pointing at a sibling's id. The client owns every id (Nebula never generates them) and wires the relationships explicitly.\n- **Embedding is for composition *within* one resource, not for references.** Inline object/array fields (`address: { city: string }`) are part of that one resource's value and its single snapshot. A resource's value round-trips the full structured-clone space — `Map`, `Date`, cycles, shared (aliased) sub-objects — but that richness lives *inside* one value; it does not reach *across* resource references, which are always ids.\n- **Embedding an object where an id belongs is rejected loudly.** Passing the related object (or a nested/cyclic object) into a reference field fails validation with a message that names the field and its target type and tells you to reference by id — not a cryptic type error.\n\nExample — a todo that references its list by id, created with the list in one atomic transaction:\n\n```typescript @skip-check\n// ontology\ninterface TodoList { title: string }\ninterface Todo {\n  title: string;\n  list: TodoList;     // a relationship — sent/stored as the TodoList's id string\n  done: boolean;\n}\n\n// client: create the list and a todo that references it, atomically\nconst listId = crypto.randomUUID();\nconst todoId = crypto.randomUUID();\nawait client.resources.transaction({\n  [listId]: { op: 'create', typeName: 'TodoList', nodeId, value: { title: 'Groceries' } },\n  [todoId]: { op: 'create', typeName: 'Todo',     nodeId, value: { title: 'Milk', list: listId, done: false } },\n});\n```\n\nStill to document (mechanism, not yet settled):\n\n- The `@inverse` annotation for declaring back-references (e.g., `User.todos` is the inverse of `Todo.ownerId`).\n- One-to-one, one-to-many, many-to-many — how each shows up in the ontology and on the store.\n- **Reference integrity is deferred.** Today validation checks only that a reference is a well-formed id `string` — it does **not** verify the referenced resource exists, so a dangling id is accepted. Enforcing \"the referenced resource exists, or is created in the same transaction\" is a planned, **intra-Star, same-transaction**-scoped feature (cross-Star references are ids that can't be checked at write time and stay eventually-consistent). Tracked in the backlog.\n\n## Annotations\n\nTwo categories of annotation, named consistently within each category:\n\n- **Pure-config annotations** — named after the knob they set. Example: `@debounce(quietMs, maxWaitMs)`.\n- **Semantic field-shape annotations** — named after what the field IS. Effects derive from the shape and may span multiple concerns. Example: `@longform`.\n\nThe asymmetry is intentional. Config-named annotations are unambiguous about scope (\"ah, this sets debounce\"). Semantic-named annotations let the framework decide what behaviors that shape implies, so the user-developer declares intent once and gets multiple right defaults across resolver registration, debounce timing, UI rendering, etc.\n\n### Inventory\n\n| Annotation | Category | Effect |\n|---|---|---|\n| `@title` | metadata | Display name for Studio's UI surfaces (form labels, list headers). |\n| `@description` | metadata | Human/LLM explanation; Studio consults when reasoning about the type. |\n| `@inverse` | reference | Back-reference declaration for relationships. |\n| `@debounce(q?, m?)` | config | Debounce timing for writes to this field. `@debounce(0)` makes the field commit immediately (no debounce) — used for booleans, enums, anything click-to-commit. |\n| `@longform` | semantic | This field is long-form text. Effects: slower debounce (default `quietMs: 1000`, `maxWaitMs: 5000`), auto-register a text-merge conflict resolver, Studio renders as `<textarea>` in generated UI. |\n| typia validation tags (`@minimum`, `@maximum`, `@pattern`, `@format`, etc.) | validation | Standard typia constraints; see [@lumenize/ts-runtime-parser-validator](../ts-runtime-parser-validator/index.md). |\n\n### Type-derived defaults (no annotation needed)\n\nMost fields get sensible debounce config from their type. Studio's LLM relies on these so the user-developer doesn't have to think about timing for routine fields:\n\n| Field type | Default debounce |\n|---|---|\n| `boolean` | `{ quietMs: 0 }` (eager — click-to-commit) |\n| enum / literal union (e.g., `'open' \\| 'done'`) | `{ quietMs: 0 }` (eager) |\n| `string` (short) | inherits type default (`500` / `2000`) |\n| `string` with `@longform` | inherits the `@longform` config |\n| `number` | inherits type default |\n| arrays / objects / embedded | inherits type default |\n\nExplicit `@debounce(q, m)` always overrides the type-derived default.\n\n### Example\n\n```typescript @skip-check\ninterface Todo {\n  /** @title(\"Title\") */\n  title: string;                  // short string → inherits type default\n\n  /** @longform */\n  description: string;            // long-form → slower debounce + text-merge + <textarea>\n\n  done: boolean;                  // boolean → @debounce(0) implied\n\n  status: 'open' | 'done';        // enum → @debounce(0) implied\n\n  /** @debounce(2000, 10000) */\n  notes: string;                  // explicit override — used for, e.g., journal entries\n}\n```\n\nStudio's LLM, when generating the ontology, picks annotations from a small rule table (covered in [tasks/nebula-studio.md § Code Generation](https://github.com/lumenize/lumenize/blob/main/tasks/nebula-studio.md#code-generation)). The user-developer typically only sees explicit annotations during review.\n\n### How annotations reach the runtime\n\nThe compiler (typia or our extension) reads the .d.ts at deploy time and emits a config map alongside the validator bundle. The factory loads the bundle at startup and applies the per-field debounce config to its synced-state middleware automatically. For runtime overrides (rare — A/B testing, dynamic config), [`client.resources.transactionDebounce(rt, opts)`](./api-reference.md#resourcestransactiondebounce) is the override surface.\n\n*(Status: the per-field debounce-config emission is post-demo. The initial release ships the global framework defaults — 500 ms quiet / 2000 ms maxWait — for every field, with `transactionDebounce` as the per-type override; per-field annotations take effect once the emission lands, the global defaults remaining the fallback for unannotated fields. `@longform`'s resolver + UI effects are on their own tracks, independent of this.)*\n\nPrecedence: runtime override > ontology annotation > type-based default > framework default.\n\n## Per-type conflict resolvers\n\nConflict-resolver registration is **per resource type** — the right merge strategy for a text-body field is different from the right strategy for a status enum or a set-of-tags. Conceptually the resolver is a property of the type, alongside its shape.\n\nWill cover:\n\n- Where the registration lives in code (see open question below).\n- The handler signature and the `TransactionResourceResolution` shape (link to [Resources § Per-resource behavior](./resources.md#per-resource-behavior--the-ontransactionresourceresolution-handler) for the full union; this section just shows per-type recipes).\n- Common per-type patterns and when to use each:\n  - **Text-body fields** (descriptions, comments, document bodies) — register a 3-way text-merge handler. The default `'use-server'` policy will yank typing mid-keystroke during concurrent edits; text-merge preserves both edits.\n  - **Set-of-tags / set-of-IDs** — `'use-this'` with set-union merge so neither client's adds get lost.\n  - **Enums / IDs / single-line labels** — `'use-server'` is usually fine (default; no handler needed).\n  - **High-stakes user choice** (e.g., scheduled meeting time) — `'use-this'` with async modal; user picks.\n  - **Deferred-review conflicts** — `'human-in-the-loop'`; app stashes for later review.\n- Resolver-as-property-of-type philosophy: when you change a type's shape, you may also need to change its resolver. Co-locating reduces the chance of drift.\n\n> **Resolved direction (2026-05-18)**: per the [Annotations](#annotations) section above, per-type config (debounce, resolver registration, default UI rendering) flows from the ontology. For resolvers specifically, the cleanest endpoint is **annotation-driven registration** — the same compile-time pass that emits debounce config also emits resolver registration for fields/types that carry semantic annotations (`@longform` auto-registers a text-merge resolver, etc.). Custom resolvers that need code (a domain-specific merge function, a modal flow) get a sibling `resolvers.ts` (or `ontology/resolvers.ts`) that the bootstrap imports. The user-developer rarely sees this file — annotations cover the common cases. Implementation detail to settle during v3; the API surface (`client.resources.onTransactionResourceResolution(rt, handler)`) stays as-is, just with fewer direct callers now that annotations handle the typical patterns.\n\n## Default permissions and DAG attachment\n\nWill cover:\n\n- Every resource has a `nodeId` at create time — which DAG (org/permission) tree node it attaches to. See [Resources § Access control](./access-control.md) for the conceptual model.\n- The ontology can declare a **default attachment pattern** per type. Common patterns:\n  - **Per-user subtree** — every `Todo` attaches under the creating user's `user-<sub>` node (the consumer SaaS pattern from the todo-list sharing example in resources.md).\n  - **Shared workspace** — every `Document` attaches under a `workspace-<id>` node specified at create time (the team-collab pattern).\n  - **Tenant-root** — every resource attaches under the tenant's root (the small-app pattern with no internal grouping).\n- Open: what's the annotation/declaration syntax for the default pattern. Possibly an `@attachment` tag, or a registered factory function, or just convention in the resolver/code.\n\n## How the ontology becomes a validator\n\nWill cover briefly (link out for depth):\n\n- typia compiles the .d.ts at deploy time into a runtime parser-validator.\n- The validator runs on every transaction (server-side, before write).\n- Validation failures surface per-resource as `{ kind: 'validation-failed', errors }` in the `TransactionResourceResolution` (see [Resources § Per-resource behavior](./resources.md#per-resource-behavior--the-ontransactionresourceresolution-handler)).\n- Detailed pipeline + the typia tag vocabulary live in [@lumenize/ts-runtime-parser-validator](../ts-runtime-parser-validator/index.md).\n- The validator bundle ships alongside the deployed app (lock-step with `ontologyVersion`); old clients hitting a new server get `{ kind: 'ontology-stale' }` and reload.\n\n## When to evolve the ontology\n\nWill cover:\n\n- **Backward-compatible changes** — adding optional fields, adding new types, adding non-required references. Old clients keep working; new clients use the new fields.\n- **Breaking changes** — removing fields, renaming, making optional fields required, changing field types. These require a coordinated `ontologyVersion` bump.\n- The `ontologyVersion` ↔ ontology version lock-step model: server enforces that incoming transactions match its current ontology; mismatch yields `{ kind: 'ontology-stale' }` and the client reloads via `onShouldRefreshUI` (see [API reference § createNebulaClient](./api-reference.md#createnebulaclient)).\n- Migrations: link to wherever the migration story ultimately lives (`tasks/on-hold/nebula-lazy-schema-migrations.md` references this; the user-facing doc TBD).\n\n## Authoring with Studio\n\nWill cover:\n\n- Studio's typical conversation flow: the user-developer describes their app, Studio asks clarifying questions about entities and relationships, Studio drafts the ontology, the user-developer reviews in chat (no file editor — per [nebula-studio.md § Chat-first UI direction](https://github.com/lumenize/lumenize/blob/main/tasks/nebula-studio.md)).\n- How the LLM consults this doc when generating ontology files.\n- What gets generated alongside: per-type resolvers (per the Q1 decision above), default attachment configuration, Studio's seed data for the dev preview.\n- Iteration: when the user-developer asks for a behavior change that requires a schema change, Studio updates the ontology AND the dependent code in lock-step.\n",
  ".platform/docs/resources.md": "---\ntitle: Resources\ndescription: The core data model in Nebula — JavaScript objects addressed by (type, id), with real-time sync, optimistic concurrency, and pluggable conflict resolution.\n---\n\n# Resources\n\nResources are the heart of this system. They are both simple and powerful. You use them when developing your app in Nebula Studio. Your users use them when they interact with your app because they are the only place for them to store anything.\n\nFrom your UI's perspective, each resource is a JavaScript object — fully supporting everything the structured-clone algorithm supports: `Map`, `Date`, cycles, etc. The framework handles the conversion to/from a storable representation transparently. You write to the resource the same way you'd write any in-memory JavaScript object, and the rich types round-trip correctly. (This richness — including cycles and shared/aliased sub-objects — lives *within* a single resource's value. A field that points at *another* resource is a reference held by id, not an embedded object; see [Ontology § References between types](./ontology.md#references-between-types).)\n\nEach resource also carries a client-generated `eTag` (UUID) attached on every write — the eTag does double duty as both the optimistic-concurrency token and the idempotency key for safe retries. The shape of each resource type is defined by your ontology — a TypeScript `.d.ts`-style file that Nebula compiles into a runtime parser-validator. See [TS Runtime Parser-Validator](../ts-runtime-parser-validator/index.md) for how the ontology becomes the validator.\n\nThink of Nebula's resource layer as a document database with inter-resource relationships, real-time sync, and structural access control:\n\n- **Document database** — each resource is a JavaScript object addressed by `(type, id)`.\n- **With references** — a field typed as another resource is a relationship held **by id** (a foreign key), never an embedded object. Create related resources as separate ops in one atomic `transaction(...)`, each with a client-supplied id, wiring the references explicitly. See [Ontology § References between types](./ontology.md#references-between-types).\n- **Real-time sync** — clients subscribe to resources they care about; mutations fan out to all subscribers automatically.\n- **Structural access control** — every resource is attached at create time to a node in your app's **org/permission tree**. Each node has a per-user permissions table; permissions cascade additively from ancestors. See [Access control](./access-control.md).\n\n## Addressing resources\n\nTwo encodings, isomorphic — same segments, different syntax per context.\n\n**1. In Vue templates (JavaScript expressions):**\n\n```html @skip-check\n<span>{{ store.resources.todo['task-42'].value.title }}</span>\n<span>{{ store.resources.todo[id].value.title }}</span>\n```\n\nBracket notation handles any `resourceId` shape (hyphens, ULIDs, UUIDs). Dot notation works for identifier-safe IDs.\n\n**2. In code (tuple at the top level):**\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nclient.resources.subscribe('todo', 'task-42');   // returns a Disposable handle (not a Promise) — see api-reference\nawait client.resources.transaction({\n  'task-42': { op: 'put', typeName: 'todo', value: { title: 'New title', /* ... */ } },\n});\nconst snap = await client.resources.read('todo', 'task-42');\n```\n\n**3. REST (slash-delimited, coming soon):**\n\n```\nGET  /resources/todo/task-42\nPOST /resources/todo/task-42\n```\n\n`resourceType` and `resourceId` are restricted to `[A-Za-z0-9_-]` — no periods (would break path parsing), no slashes (would break URL parsing). ULIDs, UUIDs, and conventional slugs all fit.\n\n### Reserved state-path prefixes\n\nAll paths below live on the Vue-reactive `store` (the alternate access point, `client`, is for method calls and non-reactive identity — see [Coding your UI § `store` vs `client`](./coding-your-ui.md#store-vs-client--what-goes-where)). Two top-level prefixes under `store` are framework-reserved:\n\n- **`store.resources.*`** — synced resource snapshots, written by the framework on every server push. `store.resources.{type}.{id}.value` holds the resource value; `store.resources.{type}.{id}.meta` holds the eTag, change metadata, etc.\n- **`store.lmz.*`** — everything else framework-owned. Today: connection state (`store.lmz.connection.state`, `store.lmz.connection.connected`, `store.lmz.connection.lastConnectedAt`) and the org/permission tree (`store.lmz.orgTree`, delivered on its own channel; mutate via `client.orgTree.*`). Future framework-meta paths land here too.\n\nEvery other top-level segment is yours. Common conventions:\n\n- `store.ui.*` — transient UI state (modal open/closed, form drafts, conflict tracking, anything reactive but not synced)\n- `store.app.*` — application-wide local state (active view, current user prefs, etc.)\n- Anything else — completely free\n\nThe factory pre-seeds `store.ui` and `store.app` as empty objects (conveniences, not reserved — the framework never writes to them after seeding). Beyond that, the framework only touches `store.resources.*` and `store.lmz.*`. User-developers write to the rest however they want.\n\n## Optimistic concurrency\n\n### What's an eTag?\n\nEvery resource snapshot carries an `eTag` — a UUID generated by whichever client most recently wrote the resource. The eTag travels with the data into your local state at `store.resources.{type}.{id}.meta.eTag`. When your front end submits a transaction, it sends two things: the eTag of the snapshot it based its edit on (`eTag`), and a freshly-generated UUID for the new snapshot (`newETag`).\n\nThe server uses both:\n\n- **Concurrency check** — if the current stored eTag matches your `eTag`, your write wins (and the new snapshot gets your `newETag`). If it doesn't, another client wrote first — your transaction conflicts and the resolver fires.\n- **Idempotency** — if the current stored eTag matches your `newETag`, that means your prior transaction landed but you didn't get the response (network drop mid-flight, etc.) and now you're retrying. Server returns idempotent success rather than spuriously conflicting with your own prior write.\n\nYou never construct or compare eTags yourself. The framework reads the cached `eTag` from state when emitting a transaction, generates a fresh `newETag` via `crypto.randomUUID()`, and sends both to the server. Same UUID does both jobs — no separate idempotency-key field.\n\n### Per-resource behavior — the `onTransactionResourceResolution` handler\n\nPer-resource behavior is configured by registering a handler per resource type. The framework calls this handler once per resource per transaction with that resource's current `TransactionResourceResolution`. The handler does two jobs in one place — decide conflict resolutions, and react to terminal outcomes:\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nclient.resources.onTransactionResourceResolution('todo', (rid, resolution) => {\n  switch (resolution.kind) {\n    // Non-terminal: handler returns a ConflictResolverVerdict.\n    case 'conflict-pending':\n      return { kind: 'use-server' };                  // example: server-wins (= framework default)\n\n    // Terminal: handler return is ignored. React however you like.\n    case 'committed':         /* navigate, clear draft */ break;\n    case 'use-server':        /* server's value painted; default red flash fired */ break;\n    case 'human-in-the-loop': /* stash for review-later UI */ break;\n    case 'validation-failed': /* surface resolution.errors */ break;\n    case 'permission-denied': /* show \"not authorized\" */ break;\n    case 'retries-exhausted': /* show error */ break;\n  }\n});\n```\n\n**You don't need to register a handler.** The framework has sensible defaults:\n\n- Committed writes get a `lumenize-commit-success` class (green outline animation) on bound elements for ~1 second.\n- Reverted writes (`'use-server'`, `'validation-failed'`, `'permission-denied'`, `'retries-exhausted'`) get `lumenize-conflict-revert` (red outline animation).\n- `'conflict-pending'` defaults to the server-wins verdict (`{ kind: 'use-server' }`) when no handler is registered.\n\n```css @skip-check\n.lumenize-commit-success {\n  animation: flash-green 1s ease-out;\n}\n.lumenize-conflict-revert {\n  animation: flash-red 1s ease-out;\n}\n@keyframes flash-green {\n  0%   { outline: 2px solid var(--color-success); }\n  100% { outline: 2px solid transparent; }\n}\n@keyframes flash-red {\n  0%   { outline: 2px solid var(--color-error); }\n  100% { outline: 2px solid transparent; }\n}\n```\n\nRegister a handler when you want to override or extend the defaults — typically to merge text fields differently than server-wins, to navigate on commit, to surface validation errors next to fields, or to stash conflicts for a review-later UI.\n\nThree conflict verdicts cover the `'conflict-pending'` branch. Each example below shows the minimum handler body needed; only the `case 'conflict-pending':` arm differs.\n\n#### `'use-server'` verdict (the framework default — server wins)\n\nNo code needed. Without a handler (or with one that returns nothing from `'conflict-pending'`), the framework applies `'use-server'`: the user's local edit gets replaced with the server's authoritative value, and the `lumenize-conflict-revert` flash fires on bound elements.\n\nThe flash signals \"your input was reverted\" without any modal or prompt. Use the default for fields where the data race is rare and the cost of the user re-typing is low (enums, booleans, IDs, short labels).\n\n#### `'use-this'` verdict — automatic merge\n\nReturn `{ kind: 'use-this', value: merged }` and the framework submits a new transaction at the server's current eTag with your merged value. Use for fields where the right merge can be computed without asking the user.\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nclient.resources.onTransactionResourceResolution('todo', (rid, resolution) => {\n  if (resolution.kind === 'conflict-pending') {\n    const { local, server, base } = resolution;\n    return {\n      kind: 'use-this',\n      value: {\n        title:       local.value.title,                                                      // mine wins (short string)\n        status:      server.value.status,                                                    // theirs wins (enum)\n        description: textMerge(server.value.description, local.value.description, base.value.description),  // base = common ancestor (NOT server)\n        assignees:   [...new Set([...local.value.assignees, ...server.value.assignees])],    // set-union by hand\n      },\n    };\n  }\n});\n```\n\nIf the re-submit *also* conflicts (another client wrote again in the meantime), the handler fires again with `'conflict-pending'` and a fresh server snapshot. The chain is bounded by `maxRetries` (default 5); on cap, the resource lands at `'retries-exhausted'`.\n\nPer-type or per-call override:\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nclient.resources.onTransactionResourceResolution('todo', handler, { maxRetries: 10 });\n// or per-call — a map keyed by resourceId:\nawait client.resources.transaction(ops, { onTransactionResourceResolution: { 'task-42': handler }, maxRetries: 3 });\n```\n\nThe per-call override is a **map keyed by `resourceId`**: each entry **layers in front of** its own resource's per-type handler (it does not replace it), and any resource not in the map falls through to its per-type handler automatically — so a per-call handler can't shadow a sibling it didn't name. See [API reference § Precedence](./api-reference.md#resourcesontransactionresourceresolution).\n\n#### `'use-this'` verdict — async modal\n\nSame verdict, async handler. Show a `<dialog>`, wait for the user's choice, return the verdict. The transaction queue parks while the handler awaits; when it resolves, the framework submits the new transaction.\n\nRegister the handler once in `nebula.ts` (after the factory call); it stashes both versions on the reactive store so the modal template can read them declaratively.\n\n```typescript @check-example('apps/nebula/test/chromium/conflict-modal-browser.test.ts')\n// nebula.ts (continuing from the bootstrap example — `client`, `store` already created)\nclient.resources.onTransactionResourceResolution('todo', async (rid, resolution) => {\n  if (resolution.kind === 'conflict-pending') {\n    const { local, server } = resolution;\n    store.ui.conflict = { local, server };\n\n    const modal = document.getElementById('conflict-modal') as HTMLDialogElement;\n    const choice = await new Promise<string>((resolve) => {\n      modal.addEventListener('close', () => resolve(modal.returnValue), { once: true });\n      modal.showModal();\n    });\n    store.ui.conflict = undefined;\n\n    return choice === 'mine'\n      ? { kind: 'use-this', value: local.value }\n      : { kind: 'use-server' };\n  }\n});\n```\n\nPut the `<dialog>` once in your root component's template (typically `App.vue`):\n\n```vue @skip-check\n<!-- App.vue — shown only the modal fragment; the rest of App.vue is your UI. -->\n<template>\n  <!-- ...your other markup... -->\n  <dialog id=\"conflict-modal\" class=\"modal\">\n    <form method=\"dialog\" class=\"modal-box\">\n      <h3 class=\"font-bold text-lg\">Someone else edited this</h3>\n      <div class=\"mt-4 space-y-2\">\n        <p><strong>Your version:</strong> {{ store.ui.conflict?.local?.value?.title }}</p>\n        <p><strong>Server's version:</strong> {{ store.ui.conflict?.server?.value?.title }}</p>\n      </div>\n      <div class=\"modal-action\">\n        <button value=\"mine\" class=\"btn btn-primary\">Keep mine</button>\n        <button value=\"theirs\" class=\"btn\">Use server's</button>\n      </div>\n    </form>\n  </dialog>\n</template>\n```\n\nStashing the conflict on the reactive `store` lets the modal template read it declaratively — closure variables would force imperative DOM updates. The `store.ui.*` prefix isn't synced; it's local-only transient state, separate from `store.resources.*`.\n\nThis resource's transaction queue parks while the modal is open. There's no artificial timeout on how long the modal can stay open — if the user takes five minutes to decide, that's fine. While the modal is open, the user can keep editing — writes to *other* resources flow through their own per-resource queues unaffected; only further writes to *this same* resource buffer behind the parked transaction (and re-submit on its resulting eTag).\n\nIf the new transaction *also* conflicts (someone else wrote again between the user picking and the submission landing), the handler fires again with `'conflict-pending'` and the latest server snapshot. The transaction's outcome chain stays pending across all retries.\n\n#### `'human-in-the-loop'` verdict (non-blocking — defer to the app)\n\nWhen you don't want the transaction queue parked while a conflict is pending — the user is mid-edit elsewhere, the conflict isn't urgent — return `{ kind: 'human-in-the-loop' }` and the framework hands off entirely:\n\n- That resource's `TransactionResourceResolution` becomes `{ kind: 'human-in-the-loop', snapshot }` (handler fires again with the terminal outcome).\n- Optimistic local state stays painted (the user keeps seeing what they typed).\n- No new transaction submitted by the framework.\n- Transaction queue unblocks immediately; subsequent writes flow without waiting.\n\nYour app stashes the conflict somewhere and surfaces it on its own schedule. Typical pattern: a banner that shows pending conflicts, the user clicks \"Review\" when they're ready, your code walks the stash and submits resolution transactions.\n\n```typescript @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// nebula.ts (handler runs once at module load; alongside the factory call)\nclient.resources.onTransactionResourceResolution('document', (rid, resolution) => {\n  switch (resolution.kind) {\n    case 'conflict-pending':\n      // Stash the conflict for later review.\n      if (!store.app.conflicts) store.app.conflicts = {};\n      store.app.conflicts[resolution.server.meta.eTag] = {\n        resourceType: 'document',\n        resourceId: rid,\n        local: resolution.local,\n        server: resolution.server,\n      };\n      return { kind: 'human-in-the-loop' };\n    case 'committed':\n      // The eventual review-later submission committed — clear this conflict.\n      // (Match by some app-defined key; here we clear all eTags pointing at rid.)\n      for (const eTag of Object.keys(store.app.conflicts ?? {})) {\n        if (store.app.conflicts[eTag].resourceId === rid) {\n          delete store.app.conflicts[eTag];\n        }\n      }\n      break;\n  }\n});\n```\n\n```vue @skip-check\n<!-- ConflictBanner.vue (or just folded into App.vue) -->\n<script setup lang=\"ts\">\nimport { store, client } from './nebula';\nimport { showYourReviewUI } from './your-review-ui';  // app-defined\n\nasync function reviewConflicts() {\n  const conflicts = store.app.conflicts ?? {};\n\n  // Walk each conflict, collect the user's chosen value into one batch.\n  // NOTE: we pass `eTag` EXPLICITLY (skipping the framework's auto-derive)\n  // because the right baseline here is the server snapshot at conflict-stash\n  // time, not the current local store eTag (which may have moved on since).\n  // This is the canonical case for explicit eTag override; see\n  // api-reference.md § Explicit eTag override.\n  const ops: Record<string, { op: 'put'; typeName: string; eTag: string; value: unknown }> = {};\n  for (const [, conflict] of Object.entries(conflicts)) {\n    const choice = await showYourReviewUI(conflict);\n    ops[conflict.resourceId] = {\n      op: 'put',\n      typeName: conflict.resourceType,\n      eTag: conflict.server.meta.eTag,                  // stashed baseline, not auto-derived\n      value: choice,\n    };\n  }\n\n  // Submit all resolutions as one atomic transaction. The per-type handler\n  // registered in nebula.ts fires per resource — clears the stash on\n  // 'committed', re-stashes on a re-conflict (returns 'human-in-the-loop' again).\n  await client.resources.transaction(ops);\n  // Nothing to inspect here unless the transaction-wide outcome is\n  // infrastructure-error / timeout / ontology-stale (handled separately).\n}\n</script>\n\n<template>\n  <div\n    v-if=\"Object.keys(store.app.conflicts ?? {}).length > 0\"\n    class=\"alert alert-warning\"\n  >\n    {{ Object.keys(store.app.conflicts).length }} pending conflicts.\n    <button @click=\"reviewConflicts\" class=\"btn btn-sm\">Review</button>\n  </div>\n</template>\n```\n\nThe handler is the single point of truth for per-resource state — conflicts stashed on entry, cleared on commit. The await-site code doesn't need to inspect per-resource outcomes; the handler already did.\n\n#### When to use which verdict\n\n- **`'use-server'`** — most fields most of the time. Safe default.\n- **`'use-this'` (sync)** — automatic merge per field (text-merge, set-union, last-write-wins per field, etc.).\n- **`'use-this'` (async)** — user must pick *right now*, framework handles submission. Modal-style UX. The most common choice for \"give the user agency on a conflict.\"\n- **`'human-in-the-loop'`** — conflicts can be deferred. Banner + review-later UX. The user keeps working uninterrupted.\n\n#### Text fields specifically — don't leave the default\n\nFor any field a user is actively typing into (long-form text, descriptions, comments, document bodies), the framework-default `'use-server'` is the wrong choice. Here's why:\n\n1. The user is typing into `<input v-model=\"store.resources.doc[id].value.body\">`. Each keystroke fires an optimistic local update; the synced-state middleware debounces transaction submission.\n2. While the user is mid-sentence, **another client commits a write to the same resource.** The server broadcasts the new snapshot — but the synced-state middleware **holds** the incoming snapshot while this resource has pending optimistic writes, so the input doesn't snap mid-keystroke.\n3. The debounced transaction then arrives at the server with the now-stale eTag → conflict → the resolver sees the local state, the buffered server snapshot, and `base`.\n4. Under the default `'use-server'`, the user's typing is rolled back to the other client's value **at resolution time** — held off mid-keystroke, but still lost.\n\nThis is the data race; debouncing and fanout-holding narrow it but don't resolve it. The reliable fix is text-merge. Annotating the field [`@longform`](./ontology.md#annotations) auto-registers exactly the handler below — most apps never write it by hand. Write your own only when you need custom merge logic; here's what the auto-registered handler does:\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\n// textMerge is a 3-way (LCS-based) merge helper\nimport { textMerge } from '@lumenize/nebula/frontend';\n\nclient.resources.onTransactionResourceResolution('doc', (rid, resolution) => {\n  if (resolution.kind === 'conflict-pending') {\n    return {\n      kind: 'use-this',\n      value: {\n        ...resolution.server.value,                                          // start from server snapshot (keeps its other-field changes)\n        body: textMerge(resolution.server.value.body, resolution.local.value.body, resolution.base.value.body),  // base = common ancestor\n      },\n    };\n  }\n});\n```\n\nFor typing-into-text-fields, **custom merge is almost always the right answer**, not `'use-server'`. The framework default exists because it's safe for non-text fields (enums, booleans, IDs) and because every resource type needs *some* default. Register an explicit handler for text-bearing types.\n\nWhat \"right merge\" looks like depends on the data:\n- **Short single-line text** (titles, labels): typical pattern is `local wins` — short strings rarely have meaningful concurrent edits worth merging. `value: { ...server.value, title: local.value.title }`.\n- **Long-form text** (descriptions, comments, document bodies): three-way merge — the shipped `textMerge` helper (LCS-based). It preserves non-overlapping edits but can garble overlapping ones — true conflict-free collaborative editing needs a CRDT (out of scope for now).\n- **Structured content** (markdown, code): three-way merge at the line level, OR fall back to async `'use-this'` with a modal showing both versions.\n\nSet fields (assignees, tags) typically want set-union; enums want last-write-wins (server is fine); IDs want last-write-wins (server is fine).\n\n### Awaiting `transaction()` at the call-site\n\n**Three nouns, one `.kind` discriminant — anchor them once:** `TransactionOutcome` = the whole transaction's fate (what `await transaction()` resolves with); `TransactionResourceResolution` = one resource's fate within it (what the per-type handler receives); `ConflictResolverVerdict` = what you *return* from a `'conflict-pending'` resolution to steer it. Outcome and Resolution are reported *to* you; Verdict is your reply.\n\nTwo patterns, depending on whether you call `transaction()` yourself.\n\n**Fire-and-forget** — when `v-model` triggers a transaction via the synced-state middleware, your code never calls `transaction()` directly. The framework owns the round-trip: per-type handler reacts to each resource, `onShouldRefreshUI` handles ontology-staleness, optimistic state paints regardless. No `await` to write, no `switch` to add.\n\n**Explicit transactions** — when you call `client.resources.transaction(ops)` yourself (programmatic save, batch resolution, action handlers), `await` is right when you need to react to transaction-wide failures (infrastructure, timeout, ontology-stale). **Per-resource outcomes are NOT handled here** — they're handled in the per-type [`onTransactionResourceResolution`](./api-reference.md#resourcesontransactionresourceresolution) handler.\n\n`transaction()` **always resolves** with a `TransactionOutcome` — never rejects. Infrastructure failures (network drops, mesh crashes) come back as `{ kind: 'infrastructure-error', error }`. The top-level shape has five kinds; the await-site's one decision — \"do I resubmit?\" — is answered by `outcome.retryable`:\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nconst outcome = await client.resources.transaction(ops);\nswitch (outcome.kind) {\n  case 'committed':\n    // Every op landed (after any below-the-bucket conflict resolution). The per-type\n    // handler has already fired for each resource (navigation, draft-clearing,\n    // validation-error display, etc.). outcome.resources has the per-resource breakdown\n    // if you need it, but most callers don't.\n    break;\n\n  case 'rejected':\n    // The server processed it but nothing committed, for a per-op reason. outcome.retryable\n    // is the resubmit verdict: an exhausted conflict → true; permission/validation → false.\n    // The per-type handler has already surfaced each op's reason from outcome.resources\n    // ('permission-denied' → request access via the orgTree, 'validation-failed' → fix input,\n    // 'human-in-the-loop' → optimistic paint stays; the app owns the follow-up).\n    if (outcome.retryable) showToast('Save problem — retry?');\n    break;\n\n  case 'timeout':\n  case 'infrastructure-error':\n    // Transaction-wide failure; optimistic state rolled back (connection-gated — a mere\n    // disconnect never lands here). An idempotent resubmit (same newETag) can land.\n    showToast('Connection problem — retry?');\n    if (outcome.kind === 'infrastructure-error') console.error(outcome.error);\n    break;\n\n  case 'ontology-stale':\n    // The client's app version is stale; onShouldRefreshUI usually fires (page reload).\n    // Optimistic state untouched. Nothing extra to do here.\n    break;\n}\n```\n\nFor most form-save flows where the per-type handler does the work, the entire `switch` can collapse to:\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nconst outcome = await client.resources.transaction(ops);\nif (outcome.kind !== 'committed') {\n  showToast('Save problem — retry?');\n}\n```\n\nThe per-type handler has already done navigation / draft-clearing on `'committed'` and surfaced validation errors / not-authorized messages on `'validation-failed'` / `'permission-denied'`. The await-site is only on the hook for transaction-wide failures.\n\nIf you need aggregate decisions at the await-site (e.g., \"only navigate if EVERY resource committed, not just some\"), iterate `outcome.resources`:\n\n```js @check-example('apps/nebula/test/test-apps/baseline/for-docs.test.ts')\nif (outcome.kind === 'committed') {\n  const allCommitted = Object.values(outcome.resources)\n    .every(r => r.kind === 'committed');   // an op may have resolved to 'use-server' — committed, but your value was reverted\n  if (allCommitted) {\n    store.app.activeView = 'list';\n  }\n}\n```\n\nWhy discriminated unions over `try`/`catch`? Studio-generated UIs are LLM-authored. Switching on every variant forces every terminal state to be handled explicitly — a bare `try`/`catch` would swallow the discrimination. Several per-resource outcomes (`'use-server'`, `'human-in-the-loop'`) are *normal* terminal states, not errors; conflating them with \"something broke\" loses signal. Including infrastructure failures in the resolution lets the LLM-authored consumer write one switch instead of remembering that one code path uses exceptions.\n\n### Custom flash visuals\n\n:::note[Deferred to v4]\n\nDOM flash ships in v4 — 5.3.7 has no element-flash mechanism (it needs a binding-discovery step Vue doesn't provide for free; a compiler-injected directive is the leading v4 candidate). The `flashClass` / `flashDuration` options below are reserved so the API stays stable; they have no effect yet.\n\n:::\n\nBoth default classes — `lumenize-commit-success` (green) on commit and `lumenize-conflict-revert` (red) on rollback — are configurable per type (once flash lands):\n\n```js @skip-check\nclient.resources.onTransactionResourceResolution('todo', handler, {\n  flashClass: {\n    committed: 'my-success-flash',     // or null to disable framework flash on commit\n    rolledBack: 'my-warn-flash',       // or null to disable framework flash on rollback\n  },\n  flashDuration: 1500,                 // ms\n});\n```\n\nFor richer UX (apply CSS to a parent, fire a JS animation, combine flash with an alert), the handler's `'conflict-pending'` branch receives a `context.bindings` map of DOM elements bound to each path under the resource:\n\n```js @skip-check\nclient.resources.onTransactionResourceResolution('todo', (rid, resolution) => {\n  if (resolution.kind === 'conflict-pending') {\n    // resolution.context.bindings is Map<path, HTMLElement[]>\n    // (deferred-post-5.3.7 — empty Map in 5.3.7; see api-reference.md § Handler bindings)\n    resolution.context.bindings.forEach((els, path) => {\n      els.forEach(el => el.closest('.card')?.classList.add('alert-conflict'));\n    });\n    return { kind: 'use-server' };\n  }\n});\n```\n\nThe default flash still fires unless `flashClass: null` was set at registration.\n",
  ".platform/docs/using-vue.md": "---\ntitle: Using @lumenize/nebula/frontend with Vue\ndescription: How the factory + Vue fit together — the minimal single-file shape, the debounce knobs, and why production deploys pre-compile templates for a strict CSP.\n---\n\n# Using `@lumenize/nebula/frontend` with Vue\n\n`createNebulaClient` is a thin reactive bridge: it wraps a `NebulaClient` and returns a Vue-reactive `store` plus the `client` and a `ready` promise. Your components read and write `store.resources.*` like any reactive object; the factory handles auto-subscribe, optimistic writes, debouncing, and conflict resolution. The full surface is in [API reference § createNebulaClient](./api-reference.md#createnebulaclient); this page is about *setup* — how Vue is loaded and compiled, and the knobs that affect write timing.\n\nIn Nebula Studio you don't hand-write any of the shell below — Studio generates the bootstrap (`nebula.ts`), the Vue entry, and the `index.html`, and compiles your `.vue` single-file components for you (see [Security: CSP and template compilation](#security-csp-and-template-compilation)). The single-file shape here is for understanding the moving parts and for non-Studio/standalone use.\n\n## The minimal single-file shape\n\nThe smallest thing that runs: load Vue, create the factory, mount an app whose template reads the store. Vue is loaded from a CDN; the `@lumenize/nebula/frontend` factory is served from your Nebula deployment (the `/frontend` subpath — it is not on a public CDN, since Nebula packages ship with your Star).\n\n```html @skip-check\n<!doctype html>\n<div id=\"app\">\n  <template v-if=\"store.resources.todo[id]?.value\">\n    <input v-model=\"store.resources.todo[id].value.title\" />\n  </template>\n</div>\n\n<script type=\"importmap\">\n{\n  \"imports\": {\n    \"vue\": \"https://unpkg.com/vue@3/dist/vue.esm-browser.js\",\n    \"@lumenize/nebula/frontend\": \"/frontend/index.js\"\n  }\n}\n</script>\n\n<script type=\"module\">\n  import { createApp } from 'vue';\n  import { createNebulaClient } from '@lumenize/nebula/frontend';\n\n  const { client, store, ready } = createNebulaClient({ ontologyVersion: 'v1' });\n  await ready;  // first connection complete → client.claims populated\n\n  createApp({ setup: () => ({ store, id: 'todo-1' }) }).mount('#app');\n</script>\n```\n\n`createNebulaClient({ ontologyVersion: 'v1' })` is the whole config in a deployed browser session: `baseUrl`, `activeScope`, and `onShouldRefreshUI` auto-detect from the environment (`authScope` is currently required-in-practice — see the [config table](./api-reference.md#createnebulaclient)). `ontologyVersion` is the one field Studio substitutes at deploy time.\n\nThis single-file shape uses **in-DOM templates** — the `v-model` markup lives in the HTML and is compiled in the browser by Vue's runtime compiler. That's the convenient path for a quick page, but it has a CSP cost (below) that production deploys avoid.\n\n## Debounce knobs\n\n`v-model` updates paint optimistically on every keystroke, but the network transaction is **debounced** per `(resourceType, resourceId)` — default **500 ms** quiet window, **2000 ms** max wait. A buffered write also flushes immediately on input blur and on `client.dispose()`. See [Coding your UI § Write timing](./coding-your-ui.md#write-timing) for the behavior and [Coding your UI § IME and composition input](./coding-your-ui.md#ime-and-composition-input) for how composition input interacts with it.\n\nYou rarely set timing in code — it's **type-derived** from the ontology (`@debounce`, `@longform`; booleans/enums commit eagerly). That table is canonical in [Ontology § Annotations](./ontology.md#annotations). For the occasional runtime override (A/B testing, dynamic config), there's a per-type setter:\n\n```typescript @skip-check\n// Override the debounce profile for one resource type at runtime.\nclient.resources.transactionDebounce('note', { quietMs: 1000, maxWaitMs: 5000 });\n```\n\nSee [API reference § resources.transactionDebounce](./api-reference.md#resourcestransactiondebounce).\n\n## Security: CSP and template compilation\n\nVue templates have to be compiled to render functions somewhere. **Where** that happens decides whether you can ship a strict Content-Security-Policy.\n\n- **In-DOM / CDN mode (the single-file shape above):** templates are strings compiled in the browser by Vue's *runtime compiler*. Compiling a template string is `new Function(...)` under the hood, so the page needs CSP `script-src 'unsafe-eval'`. Fine for a prototype; not what you want for a deployed app.\n\n- **Studio production mode (what deployed apps use):** you author `.vue` **single-file components**, and the templates are compiled to render functions **server-side, ahead of time** — per-save in your user-local dev Star while you iterate, and at deploy time in the Galaxy. The browser receives only the **runtime-only** Vue build (~22 KB gzip) with no compiler, plus already-compiled render functions. No template string is ever compiled in the browser, so there's no `new Function`, so the app runs under a **strict CSP with no `'unsafe-eval'`**.\n\nThis is why Studio compiles for you rather than shipping in-DOM templates: the SFC-compiled path is the one that's secure by default. The server-side compile placement is fixed (dev Star for iteration, Galaxy for deploys); wiring the Galaxy-side production compile is part of Studio's deploy pipeline, not something app code calls.\n\n:::note[Tag case in compiled vs in-DOM templates]\n\nIn an in-DOM template (markup the browser parses), component tags must be **kebab-case** (`<tree-node>`) — the HTML parser lowercases tag names before Vue sees them. Inside `.vue` SFC templates (parsed by Vue's compiler, not the browser), PascalCase (`<TreeNode>`) works. If you're hand-writing the single-file shape, prefer kebab-case.\n\n:::\n",
  ".platform/skills/define-ontology/SKILL.md": "---\nname: define-ontology\ndescription: The app's data model, when a request names data the ontology does not yet hold or a change needs a field or type it lacks. Read this BEFORE any view skill — it decides, from the prompt, whether to propose a shape and build or to ask first.\n---\n\n# Define the ontology\n\nThe ontology (`src/ontology.d.ts`) is the app's data model, as TypeScript interfaces. Every resource a component reads or writes has a type here first. This skill is a judgment about how much to ask, then one file write.\n\n## Ask, or propose and invite correction\n\nWhether to ask before writing the shape is your call, made from what you know. Three things tell you, in the order they exist:\n\n- **How much shape the prompt already carries.** \"Create a wishlist app\" carries none: propose a reasonable shape, build it, and state the shape in your reply so a correction is one sentence away. A prompt that names fields, relationships or rules carries hints: ask the one or two questions those hints leave open, then propose. The number of questions scales with the hints — never a questionnaire.\n- **The user-developer's stated preference** for being asked or being shown, once their profile carries it. Today it does not; do not invent one — the prompt is the signal.\n- **The conversation so far.** A correction to a shape you proposed is a signal to ask more the next time; a \"just build it\" is a signal to ask less.\n\n## Before you start\n\nRead `.platform/docs/ontology.md` — in particular *References between types*: a field typed as another resource type is a reference held by id, never an embedded object, and related resources are created as separate ops in one transaction. Read the current `src/ontology.d.ts` with `read_file` so you extend what exists rather than replace it.\n\n## Procedure\n\n1. **Name the things.** From the request, list the kinds of thing the app stores — a `Wishlist`, a `WishlistItem`, a `Group`. One interface per kind. Prefer the user-developer's own words for the names.\n2. **Decide what each one holds.** For each kind, what does a `WishlistItem` need — a name, a link, a price, who claimed it? Take what the request answered; where the prompt's hints leave a real choice open, ask, one question at a time. Stop when the shape is enough for the request at hand; the ontology grows later.\n3. **Decide each relationship.** For every field that points at another kind, state it as a reference (`list: Wishlist` — an id on the wire) and say which side owns the list of ids (a container holding `items: string[]` is how a list renders). Ask only when two shapes are both plausible.\n4. **Propose the shape.** With `@title` on each interface and `?` on every field that may be absent. When the prompt carried no hints, write it and state the interfaces in your reply so a correction is one sentence away. When it carried hints, or the user-developer prefers to be asked, show the interfaces in prose and wait — their yes is the write's trigger.\n5. **Write the file.** `write_file` the complete `src/ontology.d.ts` (it is a deliberate rewrite of one file, so `write_file`, not `edit_file`), then `build` — the ontology step of the report compiles it and reports errors by line. Fix and build again until the ontology step is clean.\n6. **Say what changed and what comes next.** One sentence naming the types added or changed. Applying the ontology to the running app is the user-developer's step outside this chat; say that it is ready to apply. If the change removes or retypes a field that existing data uses, say that applying it will need a data wipe, so they decide with eyes open.\n\n## What not to do\n\n- Do not invent fields the request did not ask for \"in case\". A missing field is one more turn; a wrong one is data to migrate.\n- Do not use `T | null` where `field?: T` says the same thing.\n- Do not embed one resource's value inside another. If you want to, it is a reference.\n",
  ".platform/skills/define-the-cast/SKILL.md": "---\nname: define-the-cast\ndescription: Elicit the app's personas and decide each relationship's sharing shape, then write docs/personas.md and docs/permissions.md. Use when a request names more than one kind of user, or when who may see or change something is unclear.\n---\n\n# Define the cast, and decide how they share\n\nAn app with more than one kind of user has a permission model, and Nebula's org tree can express the same intent two ways: a grant on a node (limited sharing) or a second parent (co-ownership). Which is right turns on whether either party may leave. This skill elicits the cast, decides each relationship once, and records both.\n\n## Before you start\n\nRead `.platform/docs/access-control.md` — *Worked example: sharing in a todo-list app* and its *When to use which* — for the two shapes and the test that separates them. Read `docs/personas.md` and `docs/permissions.md` with `read_file`; both are seeded with headings and a template, and you write into them rather than replacing them.\n\n## Procedure\n\n1. **Name the personas.** From the request and `docs/vision.md`, list each kind of person who uses the app — the organizer, a participant, an admin. Give each a name (Sally the organizer, Gerry a participant) and one line on what they do. Ask the user-developer to confirm or correct the list.\n2. **Find the relationships.** For every pair of personas that touch the same data, name the data: the organizer and a participant's wishlist; two co-organizers and the event.\n3. **Ask, per relationship: co-owner or limited share?** Put the question in their terms: \"Can the organizer edit a participant's wishes, or only see them?\" A limited share is a grant — one party owns the node, the other holds `read` or `write` on it. Co-ownership is a second parent — the resource sits under both, and either may act on it. One question per relationship, in order.\n4. **Record each decision.** In `docs/permissions.md`, one row per relationship in the Decisions table: the relationship, the shape chosen, the alternative rejected and why. For example: *the organizer and a participant's wishlist — a grant, participant `write` on their own list and organizer `read`; co-ownership rejected, because the organizer must never edit a wish.* Add the prose that explains the model above the table.\n5. **Write the cast as a procedure.** In `docs/personas.md`, fill the numbered steps using the four verbs the template names — mint, node, edge, grant — so the same cast can be re-created after a data wipe: *Step 1: mint Sally as the stand-in founder. Step 2: create the node `lists`. Step 3: add `example` beneath it. Step 4: grant Gerry `admin` on `example`.* Keep personas keyed by name, never by id; every persona's address is on a reserved dead domain such as `@example.com`.\n6. **Stop and hand it over.** Creating the personas' identities and applying the grants is a confirmed step outside this chat, run from the file you wrote; say that the cast is ready to provision. Use `edit_file` for both files — they hold headings and a template you keep.\n\n## What not to do\n\n- Do not choose a shape by default. A grant where an edge was decided, or the reverse, is the mistake the Decisions table exists to stop; if a later request would re-propose one, read the row first.\n- Do not invent a persona the app does not need. Two is a cast.\n- Do not write a `sub` or any id into `docs/personas.md`; ids are re-minted by every wipe.\n",
  ".platform/skills/wire-a-view/SKILL.md": "---\nname: wire-a-view\ndescription: Bind a component to a resource through the store — read, edit, list, create, delete. Use when the ontology ALREADY holds the type the request shows, edits or adds; when it does not, define-ontology comes first.\n---\n\n# Wire a view to a resource\n\nA component reaches user data only through `store` and `client` from `./nebula`. This skill is the order of operations for one data-bound view, and the doc sections that carry each step's exact form.\n\n## Before you start\n\nRead `.platform/docs/coding-your-ui.md`: *Reading and writing through the store* (the reactive path and the `v-if` guard `v-model` needs), *Lists with `v-for`* (a container resource holding ids), *Forms: explicit save* (a local draft committed in one transaction), and *Loading and first paint*. Read `src/ontology.d.ts` for the type you are binding. If the type does not exist yet, stop and run `define-ontology` first.\n\n## Procedure\n\n1. **Pick the shape of the view.** A single record is a read of `store.resources.<type>[<id>]?.value`. A list is a container resource whose value holds an array of ids (the field's name is the ontology's to choose), with `v-for` over those ids. A form that should commit fields together is a local draft under `store.ui.<form>.draft` and one `client.resources.transaction` on save.\n2. **Choose where new resources attach.** A create needs a `nodeId` — the org-tree node the resource lives under for permissions. A single-tenant app attaches to `ROOT_NODE_ID` (imported from `@lumenize/nebula/frontend`). If the app has personas with different access, `docs/permissions.md` says which node; read it.\n3. **Write the read first.** Render the resource with the `?.` guards; a snapshot that has not arrived renders a loading state, never an error.\n4. **Add the write.** Field edits: `v-model` on the resource path inside a `v-if` guard. Creates: `client.resources.transaction({ [crypto.randomUUID()]: { op: 'create', typeName, nodeId, value } })`, and if the new resource belongs in a list, put its id into the container's array in the same transaction. Deletes: `{ op: 'delete' }` at the id, and remove the id from any container that lists it.\n5. **Build, then read the report.** `build` runs the type check over every `.vue`; a finding names the file and line. Fix real ones; a finding you judge harmless is a judgment you state in your reply.\n6. **Say what the view does in one sentence**, naming the resource type it binds.\n\n## What not to do\n\n- Do not hold user data in a `ref` that outlives the component or in `localStorage`; the store is the state.\n- Do not put optional chaining inside a `v-model` expression; guard with `v-if` instead.\n- Do not generate ids on the server side or ask for them; the client mints every id.\n",
};

/** The always-on platform layer — the system bundle every turn carries. */
export const PLATFORM_AGENTS_MD: string = PLATFORM_FILES[".platform/AGENTS.md"]!;
